INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('491174d5-e9b8-5e32-a544-7a756a2cd511', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 12, 12, 'has wronged the poor and needy, has taken by robbery, has not restored the pledge, and has lifted up his eyes to the idols, has committed abomination,'),
  ('614d6451-5186-5fea-a587-b32a73f96257', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 13, 13, 'has given forth on interest, and has taken increase; shall he then live? he shall not live: he has done all these abominations; he shall surely die; his blood shall be on him.'),
  ('23d1e926-7169-51ec-ae84-8212fe36783f', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 14, 14, 'Now, behold, if he fathers a son, who sees all his father''s sins, which he has done, and fears, and does not such like;'),
  ('b2831d70-f7da-5ec0-aa03-94ecb17778b8', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 15, 15, 'who has not eaten on the mountains, neither has lifted up his eyes to the idols of the house of Israel, has not defiled his neighbor''s wife,'),
  ('99108955-e2ce-5ced-a026-1d2a432a3374', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 16, 16, 'neither has wronged any, has not taken anything to pledge, neither has taken by robbery, but has given his bread to the hungry, and has covered the naked with a garment;'),
  ('8bab2425-f8d6-50ad-a94a-ffca7c1a6789', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 17, 17, 'who has withdrawn his hand from the poor, who has not received interest nor increase, has executed my ordinances, has walked in my statutes; he shall not die for the iniquity of his father, he shall surely live.'),
  ('7c9c446d-96a9-5ab6-a997-c546829b200b', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 18, 18, 'As for his father, because he cruelly oppressed, robbed his brother, and did that which is not good among his people, behold, he shall die in his iniquity.'),
  ('c09c114b-2305-5c89-ac8b-458df9fbef68', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 19, 19, 'Yet you say, Why doesn''t the son bear the iniquity of the father? When the son has done that which is lawful and right, and has kept all my statutes, and has done them, he shall surely live.'),
  ('81054d85-981d-5035-a024-d9d692814f33', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 20, 20, 'The soul who sins, he shall die: the son shall not bear the iniquity of the father, neither shall the father bear the iniquity of the son; the righteousness of the righteous shall be on him, and the wickedness of the wicked shall be on him.'),
  ('56a901b7-d9d3-54dc-a89a-5afb016488e3', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 21, 21, 'But if the wicked turn from all his sins that he has committed, and keep all my statutes, and do that which is lawful and right, he shall surely live, he shall not die.'),
  ('a3e847b2-ddd4-5c65-a467-180462373401', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 22, 22, 'None of his transgressions that he has committed shall be remembered against him: in his righteousness that he has done he shall live.'),
  ('06ae8a4a-03fa-50c5-a2c3-22560efd1188', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 23, 23, 'Have I any pleasure in the death of the wicked? says the Lord Yahweh; and not rather that he should return from his way, and live?'),
  ('a216c9bb-c74e-5522-adae-dc21e045093b', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 24, 24, 'But when the righteous turns away from his righteousness, and commits iniquity, and does according to all the abominations that the wicked man does, shall he live? None of his righteous deeds that he has done shall be remembered: in his trespass that he has trespassed, and in his sin that he has sinned, in them shall he die.'),
  ('5d310762-4af8-5f7c-a5ed-bd88b11b3d53', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 25, 25, 'Yet you say, The way of the Lord is not equal. Hear now, house of Israel: Is my way not equal? Aren''t your ways unequal?'),
  ('0ad526eb-6ea2-5354-a1f1-4abb8bd53693', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 26, 26, 'When the righteous man turns away from his righteousness, and commits iniquity, and dies therein; in his iniquity that he has done shall he die.'),
  ('3100c716-3209-5685-a384-c9e86d26fc16', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 27, 27, 'Again, when the wicked man turns away from his wickedness that he has committed, and does that which is lawful and right, he shall save his soul alive.'),
  ('2ecae653-600b-56ba-a50d-4921232e2367', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 28, 28, 'Because he considers, and turns away from all his transgressions that he has committed, he shall surely live, he shall not die.'),
  ('a5cc3f1d-dde8-543e-a1ba-af6396adc8c3', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 29, 29, 'Yet says the house of Israel, The way of the Lord is not equal. house of Israel, are not my ways equal? Aren''t your ways unequal?'),
  ('3c95a67f-29a2-5914-a616-d22c7f315560', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 30, 30, 'Therefore I will judge you, house of Israel, everyone according to his ways, says the Lord Yahweh. Return, and turn yourselves from all your transgressions; so iniquity shall not be your ruin.'),
  ('3a35ab0e-2d4a-5fd2-ab3f-36b13d7e16d4', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 31, 31, 'Cast away from you all your transgressions, in which you have transgressed; and make yourself a new heart and a new spirit: for why will you die, house of Israel?'),
  ('4e7cec88-51bd-5f40-a0c9-cf4640d84ad4', '0037fe30-cdf4-5608-ae59-ec42ddad8fac', NULL, 32, 32, 'For I have no pleasure in the death of him who dies, says the Lord Yahweh: therefore turn yourselves, and live.'),
  ('d05fdaf9-2ff8-5244-a1be-f28dda8191a0', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 1, 1, 'Moreover, take up a lamentation for the princes of Israel,'),
  ('13ad1f75-d0b7-5932-a452-1f5c29cf666a', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 2, 2, 'and say, What was your mother? A lioness: she couched among lions, in the midst of the young lions she nourished her cubs.'),
  ('53e1486e-c3a4-564c-ad28-c185eb884d4e', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 3, 3, 'She brought up one of her cubs: he became a young lion, and he learned to catch the prey; he devoured men.'),
  ('8de48bbf-830e-584c-a066-819f7d972768', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 4, 4, 'The nations also heard of him; he was taken in their pit; and they brought him with hooks to the land of Egypt.'),
  ('968f55c2-3330-5850-a300-e5112731b0cc', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 5, 5, 'Now when she saw that she had waited, and her hope was lost, then she took another of her cubs, and made him a young lion.'),
  ('ab3b0325-401c-5616-aff3-ca0a8da475be', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 6, 6, 'He went up and down among the lions; he became a young lion, and he learned to catch the prey; he devoured men.'),
  ('d85f0673-3a39-50df-ac20-238140e2729b', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 7, 7, 'He knew their palaces, and laid waste their cities; and the land was desolate, and its fullness, because of the noise of his roaring.'),
  ('40f41506-6279-5a9c-a3bb-2c29a269a9e5', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 8, 8, 'Then the nations set against him on every side from the provinces; and they spread their net over him; he was taken in their pit.'),
  ('09ff0414-d488-5d6a-ac74-4992d19c2ecf', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 9, 9, 'They put him in a cage with hooks, and brought him to the king of Babylon; they brought him into strongholds, that his voice should no more be heard on the mountains of Israel.'),
  ('7c97d044-f0cf-5e2a-ae33-3fa780ee5412', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 10, 10, 'Your mother was like a vine, in your blood, planted by the waters: it was fruitful and full of branches by reason of many waters.'),
  ('173d6964-9b88-52cf-a9c8-bafccf41e133', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 11, 11, 'It had strong rods for the scepters of those who bore rule, and their stature was exalted among the thick boughs, and they were seen in their height with the multitude of their branches.'),
  ('6143ccc9-e2e6-5bd0-af33-818883397a1c', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 12, 12, 'But it was plucked up in fury, it was cast down to the ground, and the east wind dried up its fruit: its strong rods were broken off and withered; the fire consumed them.'),
  ('7f0f0e6b-9914-556d-a61c-3136acbafb3d', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 13, 13, 'Now it is planted in the wilderness, in a dry and thirsty land.'),
  ('004aa984-da21-5d1a-a8b6-b5f8a9be91a9', '082578e0-039e-5019-aefb-e8966e8ee186', NULL, 14, 14, 'Fire is gone out of the rods of its branches, it has devoured its fruit, so that there is in it no strong rod to be a scepter to rule. This is a lamentation, and shall be for a lamentation.'),
  ('d9aded94-5364-5081-a3dc-164aa9fff959', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 1, 1, 'It happened in the seventh year, in the fifth [month], the tenth [day] of the month, that certain of the elders of Israel came to inquire of Yahweh, and sat before me.'),
  ('4d2be6bc-fac7-52a3-a792-f9237f1a7d04', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 2, 2, 'The word of Yahweh came to me, saying,'),
  ('b9ffd255-5852-5208-a910-3e2610eb2579', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 3, 3, 'Son of man, speak to the elders of Israel, and tell them, Thus says the Lord Yahweh: Is it to inquire of me that you have come? As I live, says the Lord Yahweh, I will not be inquired of by you.'),
  ('f23b6038-37b0-57a1-a219-71abf7561ce6', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 4, 4, 'Will you judge them, son of man, will you judge them? Cause them to know the abominations of their fathers;'),
  ('ee11e062-e5ca-57bd-afd7-41d726f22e8d', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 5, 5, 'and tell them, Thus says the Lord Yahweh: In the day when I chose Israel, and swore to the seed of the house of Jacob, and made myself known to them in the land of Egypt, when I swore to them, saying, I am Yahweh your God;'),
  ('2ef6cfdf-bc5d-5e8b-a1e3-9eb0486b409b', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 6, 6, 'in that day I swore to them, to bring them forth out of the land of Egypt into a land that I had searched out for them, flowing with milk and honey, which is the glory of all lands.'),
  ('f1489895-2c75-51f9-a778-66820b0804d6', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 7, 7, 'I said to them, Cast away every man the abominations of his eyes, and don''t defile yourselves with the idols of Egypt; I am Yahweh your God.'),
  ('881707cb-d2e2-527a-a1b9-fb14ef280da3', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 8, 8, 'But they rebelled against me, and would not listen to me; they did not every man cast away the abominations of their eyes, neither did they forsake the idols of Egypt. Then I said I would pour out my wrath on them, to accomplish my anger against them in the midst of the land of Egypt.'),
  ('18a79c3d-9693-51fa-a7e5-82cb70b4a059', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 9, 9, 'But I worked for my name''s sake, that it should not be profaned in the sight of the nations, among which they were, in whose sight I made myself known to them, in bringing them forth out of the land of Egypt.'),
  ('81135675-5889-5f65-a5ad-ab5aba93539d', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 10, 10, 'So I caused them to go forth out of the land of Egypt, and brought them into the wilderness.'),
  ('a41de182-aaa6-50e1-a018-04dc2664c71a', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 11, 11, 'I gave them my statutes, and showed them my ordinances, which if a man does, he shall live in them.'),
  ('7adf6659-8a0f-5b9e-a8cf-7affe1e34dc7', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 12, 12, 'Moreover also I gave them my Sabbaths, to be a sign between me and them, that they might know that I am Yahweh who sanctifies them.'),
  ('697bbb07-0ee8-5e51-a8a9-09394c8a99eb', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 13, 13, 'But the house of Israel rebelled against me in the wilderness: they didn''t walk in my statutes, and they rejected my ordinances, which if a man keep, he shall live in them; and my Sabbaths they greatly profaned. Then I said I would pour out my wrath on them in the wilderness, to consume them.'),
  ('9ac50614-f935-5fce-a1f8-cca6e20b6a60', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 14, 14, 'But I worked for my name''s sake, that it should not be profaned in the sight of the nations, in whose sight I brought them out.'),
  ('a174b88a-6da4-5ac1-a568-25765cf8a49b', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 15, 15, 'Moreover also I swore to them in the wilderness, that I would not bring them into the land which I had given them, flowing with milk and honey, which is the glory of all lands;'),
  ('3cda423e-c896-56ff-a75c-066086024bd6', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 16, 16, 'because they rejected my ordinances, and didn''t walk in my statutes, and profaned my Sabbaths: for their heart went after their idols.'),
  ('3346ac5d-720c-56f4-a574-42174277932e', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 17, 17, 'Nevertheless my eye spared them, and I didn''t destroy them, neither did I make a full end of them in the wilderness.'),
  ('0126243c-1dfa-51e5-a478-d136b99810cf', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 18, 18, 'I said to their children in the wilderness, Don''t walk in the statutes of your fathers, neither observe their ordinances, nor defile yourselves with their idols.'),
  ('0dfd36dd-9f6f-5b75-a172-774a5b9811a3', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 19, 19, 'I am Yahweh your God: walk in my statutes, and keep my ordinances, and do them;'),
  ('4e2933b9-7551-5008-a1ce-616025c96b15', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 20, 20, 'and make my Sabbaths holy; and they shall be a sign between me and you, that you may know that I am Yahweh your God.'),
  ('83c0d168-ef4d-5b90-a041-8911face8d6f', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 21, 21, 'But the children rebelled against me; they didn''t walk in my statutes, neither kept my ordinances to do them, which if a man do, he shall live in them; they profaned my Sabbaths. Then I said I would pour out my wrath on them, to accomplish my anger against them in the wilderness.'),
  ('8f1b9aee-d198-5dd1-a1f5-6c1e4d5467b4', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 22, 22, 'Nevertheless I withdrew my hand, and worked for my name''s sake, that it should not be profaned in the sight of the nations, in whose sight I brought them forth.'),
  ('420cd6e8-2336-5daa-a597-90268a09db04', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 23, 23, 'Moreover I swore to them in the wilderness, that I would scatter them among the nations, and disperse them through the countries;'),
  ('7874dc5a-c66d-5763-a77f-783dccdf576d', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 24, 24, 'because they had not executed my ordinances, but had rejected my statutes, and had profaned my Sabbaths, and their eyes were after their fathers'' idols.'),
  ('ca685bee-52b5-5bd9-aab7-06191b57fa15', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 25, 25, 'Moreover also I gave them statutes that were not good, and ordinances in which they should not live;'),
  ('a80ebaa4-bd01-5a2f-a038-860f30ad4c23', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 26, 26, 'and I polluted them in their own gifts, in that they caused to pass through [the fire] all that opens the womb, that I might make them desolate, to the end that they might know that I am Yahweh.'),
  ('43273591-a80f-546b-ac9d-6e0c51727d4b', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 27, 27, 'Therefore, son of man, speak to the house of Israel, and tell them, Thus says the Lord Yahweh: In this moreover have your fathers blasphemed me, in that they have committed a trespass against me.'),
  ('c5f7edb9-8725-56af-aae6-db0029fa9e66', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 28, 28, 'For when I had brought them into the land, which I swore to give to them, then they saw every high hill, and every thick tree, and they offered there their sacrifices, and there they presented the provocation of their offering; there also they made their pleasant aroma, and they poured out there their drink offerings.'),
  ('eb43bf62-f5d7-53fd-a604-711030785ef9', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 29, 29, 'Then I said to them, What does the high place where you go mean? So its name is called Bamah to this day.'),
  ('0449dc9f-bf53-57bd-a200-42929265c062', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 30, 30, 'Therefore tell the house of Israel, Thus says the Lord Yahweh: Do you pollute yourselves in the way of your fathers? and do you play the prostitute after their abominations?'),
  ('00d0d6bc-9719-5163-a351-95254038cc2b', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 31, 31, 'and when you offer your gifts, when you make your sons to pass through the fire, do you pollute yourselves with all your idols to this day? and shall I be inquired of by you, house of Israel? As I live, says the Lord Yahweh, I will not be inquired of by you;'),
  ('d663d31e-de9d-5ad8-ae91-d5c2d3f5c14a', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 32, 32, 'and that which comes into your mind shall not be at all, in that you say, We will be as the nations, as the families of the countries, to serve wood and stone.'),
  ('988aa843-b26d-5b31-a9ba-548ae7204fae', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 33, 33, 'As I live, says the Lord Yahweh, surely with a mighty hand, and with an outstretched arm, and with wrath poured out, will I be king over you:'),
  ('39b81a83-35c8-51f3-a809-e6718c0870c1', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 34, 34, 'and I will bring you out from the peoples, and will gather you out of the countries in which you are scattered, with a mighty hand, and with an outstretched arm, and with wrath poured out;'),
  ('d61b78a9-6756-5d5a-a2e3-d7abf061a55d', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 35, 35, 'and I will bring you into the wilderness of the peoples, and there will I enter into judgment with you face to face.'),
  ('0fa9f387-bbb1-5d72-a595-fcfe197b1f9f', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 36, 36, 'Like as I entered into judgment with your fathers in the wilderness of the land of Egypt, so will I enter into judgment with you, says the Lord Yahweh.'),
  ('6ef74528-9a94-549d-a539-17654cf62552', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 37, 37, 'I will cause you to pass under the rod, and I will bring you into the bond of the covenant;'),
  ('21ed207d-1843-56bd-a751-99ce8b7fe5b6', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 38, 38, 'and I will purge out from among you the rebels, and those who disobey against me; I will bring them forth out of the land where they live, but they shall not enter into the land of Israel: and you shall know that I am Yahweh.'),
  ('feb5138c-0196-5433-ab4c-d85a0be19f82', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 39, 39, 'As for you, house of Israel, thus says the Lord Yahweh: Go, serve everyone his idols, and hereafter also, if you will not listen to me; but my holy name you shall no more profane with your gifts, and with your idols.'),
  ('9c235e7e-cdc3-5c9b-a2c4-8608f67b5cd1', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 40, 40, 'For in my holy mountain, in the mountain of the height of Israel, says the Lord Yahweh, there shall all the house of Israel, all of them, serve me in the land: there will I accept them, and there will I require your offerings, and the first fruits of your offerings, with all your holy things.'),
  ('895c7015-c3c2-5e9d-a5ac-12827e1b9a70', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 41, 41, 'As a pleasant aroma will I accept you, when I bring you out from the peoples, and gather you out of the countries in which you have been scattered; and I will be sanctified in you in the sight of the nations.'),
  ('7c4fa1f0-f51d-5adb-a6ae-291a8b651d0b', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 42, 42, 'You shall know that I am Yahweh, when I shall bring you into the land of Israel, into the country which I swore to give to your fathers.'),
  ('059750fd-63b3-52d3-ad89-b2145f444465', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 43, 43, 'There you shall remember your ways, and all your doings, in which you have polluted yourselves; and you shall loathe yourselves in your own sight for all your evils that you have committed.'),
  ('823f3928-dd62-503e-ad09-2f38c0c2968a', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 44, 44, 'You shall know that I am Yahweh, when I have dealt with you for my name''s sake, not according to your evil ways, nor according to your corrupt doings, you house of Israel, says the Lord Yahweh.'),
  ('bf76cd09-12d2-54f0-abb4-4b4210f82ff2', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 45, 45, 'The word of Yahweh came to me, saying,'),
  ('064431a0-159b-5e06-ae33-64a2d4954053', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 46, 46, 'Son of man, set your face toward the south, and drop [your word] toward the south, and prophesy against the forest of the field in the South;'),
  ('3d634254-6725-53ed-afc9-b8f276f6838c', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 47, 47, 'and tell the forest of the South, Hear the word of Yahweh: Thus says the Lord Yahweh, Behold, I will kindle a fire in you, and it shall devour every green tree in you, and every dry tree: the flaming flame shall not be quenched, and all faces from the south to the north shall be burnt thereby.'),
  ('192b2008-5b36-58ba-a068-af5342e19817', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 48, 48, 'All flesh shall see that I, Yahweh, have kindled it; it shall not be quenched.'),
  ('088b83a7-3ce1-5a4b-a605-7435f1641237', '0c6b5570-7142-519b-ace6-771f62b9cb5c', NULL, 49, 49, 'Then I said, Ah Lord Yahweh! they say of me, Isn''t he a speaker of parables?'),
  ('3414173c-d28e-5f9f-a9f1-c144b0177a9f', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('68b23703-e15e-5cc2-a676-93838a065d1e', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 2, 2, 'Son of man, set your face toward Jerusalem, and drop [your word] toward the sanctuaries, and prophesy against the land of Israel;'),
  ('128325b0-0ef0-53f1-aead-8a98d6757e51', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 3, 3, 'and tell the land of Israel, Thus says Yahweh: Behold, I am against you, and will draw forth my sword out of its sheath, and will cut off from you the righteous and the wicked.'),
  ('ce7dc199-e13e-5c0a-a57c-b9a04f7edfa8', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 4, 4, 'Seeing then that I will cut off from you the righteous and the wicked, therefore shall my sword go forth out of its sheath against all flesh from the south to the north:'),
  ('3edc9569-31eb-57f3-af6b-bf80a76effb3', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 5, 5, 'and all flesh shall know that I, Yahweh, have drawn forth my sword out of its sheath; it shall not return any more.'),
  ('70a4367f-7a65-5d78-a52d-1f562773734d', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 6, 6, 'Sigh therefore, you son of man; with the breaking of your thighs and with bitterness you will sigh before their eyes.'),
  ('f09648c8-e598-5662-a4ac-24589504117d', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 7, 7, 'It shall be, when they tell you, Why do you sigh? that you shall say, Because of the news, for it comes; and every heart shall melt, and all hands shall be feeble, and every spirit shall faint, and all knees shall be weak as water: behold, it comes, and it shall be done, says the Lord Yahweh.'),
  ('8879cd95-2c4b-5304-a063-fc573871ed8a', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 8, 8, 'The word of Yahweh came to me, saying,'),
  ('c3416474-968c-54a9-a7de-77a96cc4e490', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 9, 9, 'Son of man, prophesy, and say, Thus says Yahweh: Say, A sword, a sword, it is sharpened, and also furbished;'),
  ('a3ca8d86-5fa3-5b28-a6d1-abc37c5222c7', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 10, 10, 'it is sharpened that it may make a slaughter; it is furbished that it may be as lightning: shall we then make mirth? the rod of my son, it condemns every tree.'),
  ('5759c5f0-9b1a-5233-a820-6d16915ac7d0', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 11, 11, 'It is given to be furbished, that it may be handled: the sword, it is sharpened, yes, it is furbished, to give it into the hand of the killer.'),
  ('98aa3d15-8dc7-5b79-ae28-1af82c5fc1f8', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 12, 12, 'Cry and wail, son of man; for it is on my people, it is on all the princes of Israel: they are delivered over to the sword with my people; strike therefore on your thigh.'),
  ('a33a00d6-5859-5ed8-a462-f906aeb3785a', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 13, 13, 'For there is a trial; and what if even the rod that condemns shall be no more? says the Lord Yahweh.'),
  ('79b00967-19f2-59d9-a143-a6fd4de8d0c9', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 14, 14, 'You therefore, son of man, prophesy, and strike your hands together; and let the sword be doubled the third time, the sword of the deadly wounded: it is the sword of the great one who is deadly wounded, which enters into their rooms.'),
  ('3e43a9d2-680d-53db-ad3e-94840f0d4fdb', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 15, 15, 'I have set the threatening sword against all their gates, that their heart may melt, and their stumblings be multiplied: ah! it is made as lightning, it is pointed for slaughter.'),
  ('d7077d51-91c3-54a5-a013-a8d8caaf4f21', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 16, 16, 'Gather yourselves together, go to the right, set yourselves in array, go to the left, wherever your face is set.'),
  ('a5a6b415-0fb4-5f64-a7be-66223753b6f8', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 17, 17, 'I will also strike my hands together, and I will cause my wrath to rest: I, Yahweh, have spoken it.'),
  ('f7e30a78-fa3a-5a2d-acdb-b832a8f98076', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 18, 18, 'The word of Yahweh came to me again, saying,'),
  ('77588381-655e-57b0-ab13-75502b609f5d', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 19, 19, 'Also, you son of man, appoint two ways, that the sword of the king of Babylon may come; they both shall come forth out of one land: and mark out a place, mark it out at the head of the way to the city.'),
  ('04c455ff-78c1-599f-a702-7f37a8144bed', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 20, 20, 'You shall appoint a way for the sword to come to Rabbah of the children of Ammon, and to Judah in Jerusalem the fortified.'),
  ('ac5592cc-27d6-5362-ae0a-8f9795c69247', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 21, 21, 'For the king of Babylon stood at the parting of the way, at the head of the two ways, to use divination: he shook the arrows back and forth, he consulted the teraphim, he looked in the liver.'),
  ('0035af25-7a7d-5d98-a168-fd2728b46338', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 22, 22, 'In his right hand was the divination [for] Jerusalem, to set battering rams, to open the mouth in the slaughter, to lift up the voice with shouting, to set battering rams against the gates, to cast up mounds, to build forts.'),
  ('b063bce6-6889-56c5-aef2-7331d3daeead', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 23, 23, 'It shall be to them as a false divination in their sight, who have sworn oaths to them; but he brings iniquity to memory, that they may be taken.'),
  ('0f4bb9fd-2f86-5d8f-af55-fcfb7cb48c0e', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 24, 24, 'Therefore thus says the Lord Yahweh: Because you have made your iniquity to be remembered, in that your transgressions are uncovered, so that in all your doings your sins appear; because you have come to memory, you shall be taken with the hand.'),
  ('a09b2e78-ee3f-54ab-a8af-2c61a190d4aa', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 25, 25, 'You, deadly wounded wicked one, the prince of Israel, whose day is come, in the time of the iniquity of the end,'),
  ('70bf12da-48de-58ef-ae84-f9e1bdfcc274', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 26, 26, 'thus says the Lord Yahweh: Remove the turban, and take off the crown; this [shall be] no more the same; exalt that which is low, and abase that which is high.'),
  ('fb8bf637-6277-59cf-a434-898a3d74ddd2', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 27, 27, 'I will overturn, overturn, overturn it: this also shall be no more, until he come whose right it is; and I will give it [him].'),
  ('30825987-e660-54a9-ab34-cec07fd7e6d8', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 28, 28, 'You, son of man, prophesy, and say, Thus says the Lord Yahweh concerning the children of Ammon, and concerning their reproach; and say, A sword, a sword is drawn, for the slaughter it is furbished, to cause it to devour, that it may be as lightning;'),
  ('2523df30-b94b-58d9-ad2a-f2531066ce59', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 29, 29, 'while they see for you false visions, while they divine lies to you, to lay you on the necks of the wicked who are deadly wounded, whose day is come in the time of the iniquity of the end.'),
  ('6a990a2d-6c31-5911-adad-f82303322adb', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 30, 30, 'Cause it to return into its sheath. In the place where you were created, in the land of your birth, will I judge you.'),
  ('b27d5a52-a400-50a9-a6aa-45c34855f78c', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 31, 31, 'I will pour out my indignation on you; I will blow on you with the fire of my wrath; and I will deliver you into the hand of brutish men, skillful to destroy.'),
  ('aa7c0cf6-9a1d-5c88-a5f9-594988bf574c', '4005c5c6-f5d2-548f-a2ac-3df93ffb6e49', NULL, 32, 32, 'You shall be for fuel to the fire; your blood shall be in the midst of the land; you shall be remembered no more: for I, Yahweh, have spoken it.'),
  ('83d46131-c053-5c2b-acc0-03a8596b08ec', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 1, 1, 'Moreover the word of Yahweh came to me, saying,'),
  ('780ee11b-7bfc-5ec1-a15a-5c4d764ba229', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 2, 2, 'You, son of man, will you judge, will you judge the bloody city? then cause her to know all her abominations.'),
  ('dc1cca7f-833d-50f5-aaa1-b150a7f6bda6', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 3, 3, 'You shall say, Thus says the Lord Yahweh: A city that sheds blood in the midst of her, that her time may come, and that makes idols against herself to defile her!'),
  ('7ef8b82e-92f8-5f38-aaba-08c24425c77c', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 4, 4, 'You have become guilty in your blood that you have shed, and are defiled in your idols which you have made; and you have caused your days to draw near, and are come even to your years: therefore have I made you a reproach to the nations, and a mocking to all the countries.'),
  ('2bad55da-02b1-563b-ad0b-661d9c8a1edc', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 5, 5, 'Those who are near, and those who are far from you, shall mock you, you infamous one [and] full of tumult.'),
  ('cb81d35f-472d-54aa-a1b3-547afde47441', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 6, 6, 'Behold, the princes of Israel, everyone according to his power, have been in you to shed blood.'),
  ('a47f5b42-2349-58f3-a5cd-71a5ae23c7b9', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 7, 7, 'In you have they set light by father and mother; in the midst of you have they dealt by oppression with the foreigner; in you have they wronged the fatherless and the widow.'),
  ('41e5128b-cc27-584c-a975-4569107d0eb8', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 8, 8, 'You have despised my holy things, and have profaned my Sabbaths.'),
  ('c9ea353d-ea79-51e3-af46-36b4e9c53933', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 9, 9, 'Slanderous men have been in you to shed blood; and in you they have eaten on the mountains: in the midst of you they have committed lewdness.'),
  ('09911e31-5362-54a3-af90-5d69b86ce167', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 10, 10, 'In you have they uncovered their fathers'' nakedness; in you have they humbled her who was unclean in her impurity.'),
  ('3215eb09-d7f6-5176-ad7f-84eb06251338', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 11, 11, 'One has committed abomination with his neighbor''s wife; and another has lewdly defiled his daughter-in-law; and another in you has humbled his sister, his father''s daughter.'),
  ('0d7a72ad-3eee-5a2d-afe6-94de89ca629b', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 12, 12, 'In you have they taken bribes to shed blood; you have taken interest and increase, and you have greedily gained of your neighbors by oppression, and have forgotten me, says the Lord Yahweh.'),
  ('8c2f9840-b3e9-5510-aed5-d7ae6be0a12d', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 13, 13, 'Behold, therefore, I have struck my hand at your dishonest gain which you have made, and at your blood which has been in the midst of you.'),
  ('0f1423e3-f135-5fb3-a1b9-7be9e50c8dd0', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 14, 14, 'Can your heart endure, or can your hands be strong, in the days that I shall deal with you? I, Yahweh, have spoken it, and will do it.'),
  ('909a4ca5-181a-5c16-a1fa-a548dfeb6b76', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 15, 15, 'I will scatter you among the nations, and disperse you through the countries; and I will consume your filthiness out of you.'),
  ('132ead0e-81b5-5e3d-aba8-c302c1170bd5', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 16, 16, 'You shall be profaned in yourself, in the sight of the nations; and you shall know that I am Yahweh.'),
  ('d64b9c9a-47b2-5b79-a402-51f87532e5a9', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 17, 17, 'The word of Yahweh came to me, saying,'),
  ('4e13dabb-b314-508c-ad23-efa7574f818e', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 18, 18, 'Son of man, the house of Israel is become dross to me: all of them are brass and tin and iron and lead, in the midst of the furnace; they are the dross of silver.'),
  ('c9b49043-efc3-5011-afe7-d915a1fa79f8', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 19, 19, 'Therefore thus says the Lord Yahweh: Because you have all become dross, therefore, behold, I will gather you into the midst of Jerusalem.'),
  ('3b5d8d7c-026f-5688-ab39-12317d06ca36', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 20, 20, 'As they gather silver and brass and iron and lead and tin into the midst of the furnace, to blow the fire on it, to melt it; so will I gather you in my anger and in my wrath, and I will lay you there, and melt you.'),
  ('afcb1f30-1db4-5e0d-abfc-4b87c82289e4', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 21, 21, 'Yes, I will gather you, and blow on you with the fire of my wrath, and you shall be melted in its midst.'),
  ('272c095c-abc2-553f-a9a6-632f49a76e56', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 22, 22, 'As silver is melted in the midst of the furnace, so you will be melted in its midst; and you will know that I, Yahweh, have poured out my wrath on you.'),
  ('eabcd952-ac77-5a47-a864-dee555c1c820', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 23, 23, 'The word of Yahweh came to me, saying,'),
  ('a140e2b2-ba4d-534e-a9a3-5a8bb6e886c5', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 24, 24, 'Son of man, tell her, You are a land that is not cleansed, nor rained on in the day of indignation.'),
  ('cb1e3290-509a-5fcb-a0f7-59fb5146627c', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 25, 25, 'There is a conspiracy of her prophets in its midst, like a roaring lion ravening the prey: they have devoured souls; they take treasure and precious things; they have made her widows many in its midst.'),
  ('0df97999-8d81-54f5-aa90-7d577464b12b', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 26, 26, 'Her priests have done violence to my law, and have profaned my holy things: they have made no distinction between the holy and the common, neither have they caused men to discern between the unclean and the clean, and have hidden their eyes from my Sabbaths, and I am profaned among them.'),
  ('c0aef631-f50e-50b7-aba7-c7666b133757', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 27, 27, 'Her princes in its midst are like wolves ravening the prey, to shed blood, [and] to destroy souls, that they may get dishonest gain.'),
  ('a4453e2d-3bd5-50b6-a6c2-9f739206e672', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 28, 28, 'Her prophets have plastered for them with whitewash, seeing false visions, and divining lies to them, saying, Thus says the Lord Yahweh, when Yahweh has not spoken.'),
  ('b2698609-b518-543f-a04a-2afcc8952742', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 29, 29, 'The people of the land have used oppression, and exercised robbery; yes, they have troubled the poor and needy, and have oppressed the foreigner wrongfully.'),
  ('f83e762d-cabc-5e26-affa-858c671dcc17', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 30, 30, 'I sought for a man among them, who should build up the wall, and stand in the gap before me for the land, that I should not destroy it; but I found none.'),
  ('176c87b2-dd7d-5e43-a5d7-191fffcce21a', '85a43b63-821b-53c3-a2a4-168794fa4285', NULL, 31, 31, 'Therefore have I poured out my indignation on them; I have consumed them with the fire of my wrath: their own way have I brought on their heads, says the Lord Yahweh.'),
  ('6d5187ba-25d6-5eaf-a12d-a6d97911359e', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 1, 1, 'The word of Yahweh came again to me, saying,'),
  ('3171df99-6565-58eb-a52d-e12665665735', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 2, 2, 'Son of man, there were two women, the daughters of one mother:'),
  ('f4f71b4a-77a7-5f10-ad2f-f4003318d693', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 3, 3, 'and they played the prostitute in Egypt; they played the prostitute in their youth; there were their breasts pressed, and there was handled the bosom of their virginity.'),
  ('db1990f8-4d2b-5891-addb-1a18c7900b23', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 4, 4, 'The names of them were Oholah the elder, and Oholibah her sister: and they became mine, and they bore sons and daughters. As for their names, Samaria is Oholah, and Jerusalem Oholibah.'),
  ('7b0b73bd-d93e-56ef-a601-6e485dadb4b5', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 5, 5, 'Oholah played the prostitute when she was mine; and she doted on her lovers, on the Assyrians [her] neighbors,'),
  ('8e0b0fd4-662d-5867-a44e-c7dbecadc735', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 6, 6, 'who were clothed with blue, governors and rulers, all of them desirable young men, horsemen riding on horses.'),
  ('a1f1ab9e-65db-5bfa-a249-37c9ef016799', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 7, 7, 'She bestowed her prostitution on them, the choicest men of Assyria all of them; and on whoever she doted, with all their idols she defiled herself.'),
  ('d0ac5745-825e-59c6-a949-9990a5daf738', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 8, 8, 'Neither has she left her prostitution since [the days of] Egypt; for in her youth they lay with her, and they handled the bosom of her virginity; and they poured out their prostitution on her.'),
  ('bac528b3-bb1b-5a9a-aaa3-69ec03a80879', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 9, 9, 'Therefore I delivered her into the hand of her lovers, into the hand of the Assyrians, on whom she doted.'),
  ('3aa42f34-a282-5fce-a580-5ca9627753f7', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 10, 10, 'These uncovered her nakedness; they took her sons and her daughters; and her they killed with the sword: and she became a byword among women; for they executed judgments on her.'),
  ('99bf9187-2bb6-5e89-a5b6-19ee5474cf59', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 11, 11, 'Her sister Oholibah saw this, yet was she more corrupt in her doting than she, and in her prostitution which were more than the prostitution of her sister.'),
  ('84a36120-3200-529c-aa04-ac1c30902958', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 12, 12, 'She doted on the Assyrians, governors and rulers, [her] neighbors, clothed most gorgeously, horsemen riding on horses, all of them desirable young men.'),
  ('f8f6420c-6bd1-5307-a949-284a711b3090', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 13, 13, 'I saw that she was defiled; they both took one way.'),
  ('cc0750ea-6181-5164-a8cb-e06190729352', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 14, 14, 'She increased her prostitution; for she saw men portrayed on the wall, the images of the Chaldeans portrayed with vermilion,'),
  ('339f5963-d0d8-54ef-a4d3-6a123d2dd41f', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 15, 15, 'dressed with girdles on their waists, with flowing turbans on their heads, all of them princes to look on, after the likeness of the Babylonians in Chaldea, the land of their birth.'),
  ('83a6611f-d6b1-5951-a9f7-53a494721884', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 16, 16, 'As soon as she saw them she doted on them, and sent messengers to them into Chaldea.'),
  ('f09e8dea-c5e5-5880-ac67-b2790e8d2ea1', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 17, 17, 'The Babylonians came to her into the bed of love, and they defiled her with their prostitution, and she was polluted with them, and her soul was alienated from them.'),
  ('15885c22-2a56-529f-a2dd-acda092b0731', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 18, 18, 'So she uncovered her prostitution, and uncovered her nakedness: then my soul was alienated from her, like as my soul was alienated from her sister.'),
  ('dbaeebdf-6ae3-5690-af14-ebbf461cc5ea', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 19, 19, 'Yet she multiplied her prostitution, remembering the days of her youth, in which she had played the prostitute in the land of Egypt.'),
  ('95d0ff5c-d5d1-51fa-af87-a4c2b674d712', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 20, 20, 'She doted on their paramours, whose flesh is as the flesh of donkeys, and whose issue is like the issue of horses.'),
  ('c09e8a0b-36b1-576d-a3b8-6b0c382b2df3', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 21, 21, 'Thus you called to memory the lewdness of your youth, in the handling of your bosom by the Egyptians for the breasts of your youth.'),
  ('6c711f5b-0024-52bb-a715-5ade44cd322b', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 22, 22, 'Therefore, Oholibah, thus says the Lord Yahweh: Behold, I will raise up your lovers against you, from whom your soul is alienated, and I will bring them against you on every side:'),
  ('6b6da6e8-23be-500e-a07e-ae9c94c8ca1b', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 23, 23, 'the Babylonians and all the Chaldeans, Pekod and Shoa and Koa, [and] all the Assyrians with them; desirable young men, governors and rulers all of them, princes and men of renown, all of them riding on horses.'),
  ('9bcaecad-e172-52b6-a809-0f8900b7b69d', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 24, 24, 'They shall come against you with weapons, chariots, and wagons, and with a company of peoples; they shall set themselves against you with buckler and shield and helmet all around; and I will commit the judgment to them, and they shall judge you according to their judgments.'),
  ('979b5fab-d149-50bc-a5c7-28515afc9adb', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 25, 25, 'I will set my jealousy against you, and they shall deal with you in fury; they shall take away your nose and your ears; and your residue shall fall by the sword: they shall take your sons and your daughters; and your residue shall be devoured by the fire.'),
  ('89a53935-c0bf-5a66-a274-c1d033c904fe', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 26, 26, 'They shall also strip you of your clothes, and take away your beautiful jewels.'),
  ('57d7a5fb-c467-5b56-afde-9e2c95ae7362', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 27, 27, 'Thus will I make your lewdness to cease from you, and your prostitution [brought] from the land of Egypt; so that you shall not lift up your eyes to them, nor remember Egypt any more.'),
  ('d1013e1e-8eeb-532c-ad91-89b5cc3bbac9', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 28, 28, 'For thus says the Lord Yahweh: Behold, I will deliver you into the hand of them whom you hate, into the hand of them from whom your soul is alienated;'),
  ('8d10c93e-8ea8-546e-a9e5-da02f05e7a7a', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 29, 29, 'and they shall deal with you in hatred, and shall take away all your labor, and shall leave you naked and bare; and the nakedness of your prostitution shall be uncovered, both your lewdness and your prostitution.'),
  ('d7a1d61b-0c0f-554f-a841-e887d5d4f501', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 30, 30, 'These things shall be done to you, because you have played the prostitute after the nations, and because you are polluted with their idols.'),
  ('208e1c0c-2a32-55fc-ab5f-86c896954156', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 31, 31, 'You have walked in the way of your sister; therefore will I give her cup into your hand.'),
  ('e770ef73-4473-5943-a024-f5e50f314002', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 32, 32, 'Thus says the Lord Yahweh: You will drink of your sister''s cup, which is deep and large; you will be ridiculed and held in derision; it contains much.'),
  ('2293b0ea-4975-5546-af61-117150753a36', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 33, 33, 'You shall be filled with drunkenness and sorrow, with the cup of astonishment and desolation, with the cup of your sister Samaria.'),
  ('e7407292-9f3c-5cbf-adb0-401182ad322d', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 34, 34, 'You shall even drink it and drain it out, and you shall gnaw the broken pieces of it, and shall tear your breasts; for I have spoken it, says the Lord Yahweh.'),
  ('f49dd06d-c0c3-5241-a0d5-9bbbbc920cbe', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 35, 35, 'Therefore thus says the Lord Yahweh: Because you have forgotten me, and cast me behind your back, therefore you also bear your lewdness and your prostitution.'),
  ('ac2e110a-da6c-594c-a818-4a56bfc9573b', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 36, 36, 'Yahweh said moreover to me: Son of man, will you judge Oholah and Oholibah? then declare to them their abominations.'),
  ('b67f3fa5-292e-5674-a662-325bedb4f8c7', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 37, 37, 'For they have committed adultery, and blood is in their hands; and with their idols have they committed adultery; and they have also caused their sons, whom they bore to me, to pass through [the fire] to them to be devoured.'),
  ('1a5f837c-b0b2-5633-aec6-f7035870bfe6', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 38, 38, 'Moreover this they have done to me: they have defiled my sanctuary in the same day, and have profaned my Sabbaths.'),
  ('adf972ad-7e97-5260-aac0-79348e830f5b', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 39, 39, 'For when they had slain their children to their idols, then they came the same day into my sanctuary to profane it; and behold, thus have they done in the midst of my house.'),
  ('00b648de-2ff4-5029-acce-9bb0f372aaa0', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 40, 40, 'Furthermore you have sent for men who come from far, to whom a messenger was sent, and behold, they came; for whom you did wash yourself, paint your eyes, and decorate yourself with ornaments,'),
  ('8886f4a5-7e18-5dc0-a70c-f074def92a1c', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 41, 41, 'and sit on a stately bed, with a table prepared before it, whereupon you set my incense and my oil.'),
  ('bd54ee71-a67f-59e8-a01f-75d28c1a3fb1', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 42, 42, 'The voice of a multitude being at ease was with her: and with men of the common sort were brought drunkards from the wilderness; and they put bracelets on the hands of them [twain], and beautiful crowns on their heads.'),
  ('66ac7c48-a3a4-5345-a4cd-c1176fb390f8', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 43, 43, 'Then I said of her who was old in adulteries, Now will they play the prostitute with her, and she [with them].'),
  ('59453530-b478-5079-a4e4-db20fcf695ee', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 44, 44, 'They went in to her, as they go in to a prostitute: so went they in to Oholah and to Oholibah, the lewd women.'),
  ('7efc0f89-f9b7-52f2-a17c-22ce934ecd59', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 45, 45, 'Righteous men, they shall judge them with the judgment of adulteresses, and with the judgment of women who shed blood; because they are adulteresses, and blood is in their hands.'),
  ('b07c819d-ee3d-5bc6-a5ae-4182b74af530', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 46, 46, 'For thus says the Lord Yahweh: I will bring up a company against them, and will give them to be tossed back and forth and robbed.'),
  ('97af18bd-ef7c-5ca5-a514-4906bf15d2c5', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 47, 47, 'The company shall stone them with stones, and dispatch them with their swords; they shall kill their sons and their daughters, and burn up their houses with fire.'),
  ('de4bb77e-0fa2-557c-aadd-4a20f753830d', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 48, 48, 'Thus will I cause lewdness to cease out of the land, that all women may be taught not to do after your lewdness.'),
  ('a2b26a98-4f6e-5984-a46a-27f33a7e04af', 'dff91021-6ded-5f36-a0ac-9772b3e9ce6b', NULL, 49, 49, 'They shall recompense your lewdness on you, and you shall bear the sins of your idols; and you shall know that I am the Lord Yahweh.'),
  ('a3c71a2d-4b16-582f-a823-f230bf315004', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 1, 1, 'Again, in the ninth year, in the tenth month, in the tenth [day] of the month, the word of Yahweh came to me, saying,'),
  ('68b5ae71-45e6-5482-a06e-59c36387df67', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 2, 2, 'Son of man, write the name of the day, [even] of this same day: the king of Babylon drew close to Jerusalem this same day.'),
  ('6bdd7023-00b2-5891-acb1-8a6d84097571', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 3, 3, 'Utter a parable to the rebellious house, and tell them, Thus says the Lord Yahweh, Set on the caldron, set it on, and also pour water into it:'),
  ('bfb661e8-69ce-5c6c-a831-2b3dc5e205c8', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 4, 4, 'gather its pieces into it, even every good piece, the thigh, and the shoulder; fill it with the choice bones.'),
  ('1b2a7954-1938-59d2-aafb-4c3d3f4f203b', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 5, 5, 'Take the choice of the flock, and also a pile [of wood] for the bones under [the caldron]; make it boil well; yes, let its bones be boiled in its midst.'),
  ('a59b6739-457f-5333-a9e2-170d8c0f354e', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 6, 6, 'Therefore thus says the Lord Yahweh: Woe to the bloody city, to the caldron whose rust is therein, and whose rust is not gone out of it! take out of it piece after piece; No lot is fallen on it.'),
  ('16b853a5-f7bd-5758-a513-f87e7c004daa', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 7, 7, 'For her blood is in the midst of her; she set it on the bare rock; she didn''t pour it on the ground, to cover it with dust.'),
  ('2c78f3cf-7eac-5547-ac7f-128143a379e2', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 8, 8, 'That it may cause wrath to come up to take vengeance, I have set her blood on the bare rock, that it should not be covered.'),
  ('eb6e2569-bf64-5ea7-a530-14e30afa288d', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 9, 9, 'Therefore thus says the Lord Yahweh: Woe to the bloody city! I also will make the pile great.'),
  ('32127243-6cd2-5668-aced-663f852e536e', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 10, 10, 'Heap on the wood, make the fire hot, boil well the flesh, and make thick the broth, and let the bones be burned.'),
  ('5234f385-f93c-5c01-a474-f4bfa037560f', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 11, 11, 'Then set it empty on its coals, that it may be hot, and its brass may burn, and that its filthiness may be molten in it, that its rust may be consumed.'),
  ('cd992e58-e3c8-54b1-a8aa-8b6c1d634653', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 12, 12, 'She has wearied [herself] with toil; yet her great rust doesn''t go forth out of her; her rust doesn''t [go forth] by fire.'),
  ('2b3f619c-b15d-54d8-a73f-8b5b91e8cdc1', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 13, 13, 'In your filthiness is lewdness: because I have cleansed you and you weren''t cleansed, you shall not be cleansed from your filthiness any more, until I have caused my wrath toward you to rest.'),
  ('7794e4aa-059a-54a4-a8d8-905fa2e2d5f3', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 14, 14, 'I, Yahweh, have spoken it: it shall happen, and I will do it: I will not go back, neither will I spare, neither will I repent; according to your ways, and according to your doings, shall they judge you, says the Lord Yahweh.'),
  ('78c72fe0-95bd-5662-a779-44c6be487c54', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 15, 15, 'Also the word of Yahweh came to me, saying,'),
  ('3020118f-7088-5e92-a3db-fff3fd87eeb3', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 16, 16, 'Son of man, behold, I will take away from you the desire of your eyes with a stroke: yet you shall neither mourn nor weep, neither shall your tears run down.'),
  ('53980978-0a80-5f3b-a10c-9424caa3e1ca', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 17, 17, 'Sigh, but not aloud, make no mourning for the dead; bind your headdress on you, and put your shoes on your feet, and don''t cover your lips, and don''t eat men''s bread.'),
  ('2c8f6224-9815-5b46-aed3-86f1caaa0019', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 18, 18, 'So I spoke to the people in the morning; and at even my wife died; and I did in the morning as I was commanded.'),
  ('1f6848cb-9877-5c96-afd3-240aa743e4bd', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 19, 19, 'The people said to me, Won''t you tell us what these things are to us, that you do so?'),
  ('8dbb50a3-ce8b-56d2-a144-7514390c84fb', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 20, 20, 'Then I said to them, The word of Yahweh came to me, saying,'),
  ('069fb26c-0ea2-5f10-a676-f24a97411287', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 21, 21, 'Speak to the house of Israel, Thus says the Lord Yahweh: Behold, I will profane my sanctuary, the pride of your power, the desire of your eyes, and that which your soul pities; and your sons and your daughters whom you have left behind shall fall by the sword.'),
  ('45eb7fa6-f574-5885-a6e2-f6ba57b3e6f6', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 22, 22, 'You shall do as I have done: you shall not cover your lips, nor eat the bread of men.'),
  ('661dfb87-3073-55c1-a7c8-265658d9f308', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 23, 23, 'Your tires shall be on your heads, and your shoes on your feet: you shall not mourn nor weep; but you shall pine away in your iniquities, and moan one toward another.'),
  ('634984c3-dc11-5e5d-a16d-5dd60f53922f', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 24, 24, 'Thus Ezekiel shall be a sign to you; according to all that he has done, you will do. When this comes, then you will know that I am the Lord Yahweh.'),
  ('9bce4570-95f5-5122-aec4-d726a8e7ae72', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 25, 25, 'You, son of man, shall it not be in the day when I take from them their strength, the joy of their glory, the desire of their eyes, and that whereupon they set their heart, their sons and their daughters,'),
  ('be7fc50f-431c-59ea-aca8-651894a76689', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 26, 26, 'that in that day he who escapes shall come to you, to cause you to hear it with your ears?'),
  ('73479742-e4fa-5d80-a410-83d892a98dd5', 'b2c2ebf1-da26-529a-ac5b-af83e8c59dac', NULL, 27, 27, 'In that day your mouth will be opened to him who has escaped, and you shall speak, and be no more mute: so you will be a sign to them; and they shall know that I am Yahweh.'),
  ('37d972f9-5cb4-5d27-a936-fa03d23cfd9b', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('958cbf5e-7ff2-5e90-a725-15f1bb4707c1', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 2, 2, 'Son of man, set your face toward the children of Ammon, and prophesy against them:'),
  ('fd65c455-fc5e-5d31-ac9d-48eb41dc9eda', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 3, 3, 'and tell the children of Ammon, Hear the word of the Lord Yahweh: Thus says the Lord Yahweh, Because you said, Aha, against my sanctuary, when it was profaned; and against the land of Israel, when it was made desolate; and against the house of Judah, when they went into captivity:'),
  ('e240bd45-0e84-5cae-a532-6cb272bfabbf', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 4, 4, 'therefore, behold, I will deliver you to the children of the east for a possession, and they shall set their encampments in you, and make their dwellings in you; they shall eat your fruit, and they shall drink your milk.'),
  ('6c0c9362-76bd-5b72-a2dc-991662d166e4', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 5, 5, 'I will make Rabbah a stable for camels, and the children of Ammon a resting place for flocks: and you shall know that I am Yahweh.'),
  ('79f9f1a8-33e0-5213-a0f1-6eb5e75bb236', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 6, 6, 'For thus says the Lord Yahweh: Because you have clapped your hands, and stamped with the feet, and rejoiced with all the despite of your soul against the land of Israel;'),
  ('81a6ce8e-2ecf-5bcd-a90f-c2b63b9af586', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 7, 7, 'therefore, behold, I have stretched out my hand on you, and will deliver you for a spoil to the nations; and I will cut you off from the peoples, and I will cause you to perish out of the countries: I will destroy you; and you shall know that I am Yahweh.'),
  ('b7cd9268-4a0b-5c75-a33f-29458af1c13d', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 8, 8, 'Thus says the Lord Yahweh: Because Moab and Seir say, Behold, the house of Judah is like all the nations;'),
  ('7ea1b7d3-2338-530d-a7e9-3c3151dadd2e', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 9, 9, 'therefore, behold, I will open the side of Moab from the cities, from his cities which are on his frontiers, the glory of the country, Beth Jeshimoth, Baal Meon, and Kiriathaim,'),
  ('6b5573d2-8d79-5375-afc3-4feb8ac8210f', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 10, 10, 'to the children of the east, [to go] against the children of Ammon; and I will give them for a possession, that the children of Ammon may not be remembered among the nations.'),
  ('9d56570c-d96e-5c10-ae7f-40a9c99f5586', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 11, 11, 'and I will execute judgments on Moab; and they shall know that I am Yahweh.'),
  ('db26d82d-0900-512a-adaf-7142e58e5dae', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 12, 12, 'Thus says the Lord Yahweh: Because Edom has dealt against the house of Judah by taking vengeance, and has greatly offended, and revenged himself on them;'),
  ('a83c9f77-1a81-5a82-a055-f2d845ffeb47', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 13, 13, 'therefore thus says the Lord Yahweh, I will stretch out my hand on Edom, and will cut off man and animal from it; and I will make it desolate from Teman; even to Dedan shall they fall by the sword.'),
  ('edde3a3a-b1bc-5f1b-aa31-cfcfbea9491f', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 14, 14, 'I will lay my vengeance on Edom by the hand of my people Israel; and they shall do in Edom according to my anger and according to my wrath; and they shall know my vengeance, says the Lord Yahweh.'),
  ('37813a51-bfce-5e21-a087-03b9fa941f89', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 15, 15, 'Thus says the Lord Yahweh: Because the Philistines have dealt by revenge, and have taken vengeance with despite of soul to destroy with perpetual enmity;'),
  ('fbb5b9a7-28cd-5ab7-a8d8-4fa7608d7b61', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 16, 16, 'therefore thus says the Lord Yahweh, Behold, I will stretch out my hand on the Philistines, and I will cut off the Cherethites, and destroy the remnant of the sea coast.'),
  ('a6e22a0b-889c-54bf-ab42-c34daf233b70', 'e61f9249-bc1b-5254-a2fd-3a44448ff15a', NULL, 17, 17, 'I will execute great vengeance on them with wrathful rebukes; and they shall know that I am Yahweh, when I shall lay my vengeance on them.'),
  ('e75d09ea-6c9e-54a2-ac05-89abbe39acd9', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 1, 1, 'It happened in the eleventh year, in the first [day] of the month, that the word of Yahweh came to me, saying,'),
  ('f8185399-33bf-513f-ae7d-8ec91c519252', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 2, 2, 'Son of man, because Tyre has said against Jerusalem, Aha, she is broken: the gate of the peoples; she is turned to me; I shall be replenished, now that she is laid waste:'),
  ('424eb9a3-eebd-5d49-ab49-3f476f941253', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 3, 3, 'therefore thus says the Lord Yahweh, Behold, I am against you, Tyre, and will cause many nations to come up against you, as the sea causes its waves to come up.'),
  ('c74c4b3d-0be4-56b4-a0ce-2fa30085233d', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 4, 4, 'They shall destroy the walls of Tyre, and break down her towers: I will also scrape her dust from her, and make her a bare rock.'),
  ('2a5d7636-c4f1-507b-ab70-575d3d8c5a5c', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 5, 5, 'She shall be a place for the spreading of nets in the midst of the sea; for I have spoken it, says the Lord Yahweh; and she shall become a spoil to the nations.'),
  ('d6bfc416-c2d0-5ced-aca8-749c60e24937', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 6, 6, 'Her daughters who are in the field shall be slain with the sword: and they shall know that I am Yahweh.'),
  ('970451c3-f1e2-5400-a285-613e581c485a', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 7, 7, 'For thus says the Lord Yahweh: Behold, I will bring on Tyre Nebuchadnezzar king of Babylon, king of kings, from the north, with horses, and with chariots, and with horsemen, and a company, and many people.'),
  ('125f78b7-d476-5ba7-a394-dbc1a0d80cd4', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 8, 8, 'He shall kill your daughters in the field with the sword; and he shall make forts against you, and cast up a mound against you, and raise up the buckler against you.'),
  ('2a6c1ade-f65e-509a-a2d8-d96a3d90d160', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 9, 9, 'He shall set his battering engines against your walls, and with his axes he shall break down your towers.'),
  ('f5dd316a-2f31-52c3-a64f-bdca225f80c8', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 10, 10, 'By reason of the abundance of his horses their dust shall cover you: your walls shall shake at the noise of the horsemen, and of the wagons, and of the chariots, when he shall enter into your gates, as men enter into a city in which is made a breach.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('b7cf643e-9e04-5981-aa16-e41197095d1c', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 11, 11, 'With the hoofs of his horses shall he tread down all your streets; he shall kill your people with the sword; and the pillars of your strength shall go down to the ground.'),
  ('59883e65-4bd4-5812-a632-65dd403a76a5', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 12, 12, 'They shall make a spoil of your riches, and make a prey of your merchandise; and they shall break down your walls, and destroy your pleasant houses; and they shall lay your stones and your timber and your dust in the midst of the waters.'),
  ('35e3e188-45c0-5993-ad52-e8a94da0d05a', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 13, 13, 'I will cause the noise of your songs to cease; and the sound of your harps shall be no more heard.'),
  ('e07f49c7-4a22-5801-a7f0-8a8adc869fc5', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 14, 14, 'I will make you a bare rock; you shall be a place for the spreading of nets; you shall be built no more: for I Yahweh have spoken it, says the Lord Yahweh.'),
  ('2ac5a5f3-241e-596b-a0b4-d285cbf39937', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 15, 15, 'Thus says the Lord Yahweh to Tyre: shall not the islands shake at the sound of your fall, when the wounded groan, when the slaughter is made in the midst of you?'),
  ('e419d835-5bd3-5383-ae63-537dbaf634a4', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 16, 16, 'Then all the princes of the sea shall come down from their thrones, and lay aside their robes, and strip off their embroidered garments: they shall clothe themselves with trembling; they shall sit on the ground, and shall tremble every moment, and be astonished at you.'),
  ('fa4d1b19-fd1a-599b-ac37-3dd385030906', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 17, 17, 'They shall take up a lamentation over you, and tell you, How you are destroyed, who were inhabited by seafaring men, the renowned city, who was strong in the sea, she and her inhabitants, who caused their terror to be on all who lived there!'),
  ('dc3155ff-6716-500f-a808-1e36797ae60f', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 18, 18, 'Now shall the islands tremble in the day of your fall; yes, the islands that are in the sea shall be dismayed at your departure.'),
  ('c97b9b9e-e935-5042-a364-d755291de5dd', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 19, 19, 'For thus says the Lord Yahweh: When I shall make you a desolate city, like the cities that are not inhabited; when I shall bring up the deep on you, and the great waters shall cover you;'),
  ('5f832161-6eaf-54c4-ae5e-141cc4694874', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 20, 20, 'then will I bring you down with those who descend into the pit, to the people of old time, and will make you to dwell in the lower parts of the earth, in the places that are desolate of old, with those who go down to the pit, that you be not inhabited; and I will set glory in the land of the living:'),
  ('b30e6515-2a6a-5dd2-afd0-6efa7bcd5dc9', '30afd5fa-8805-5718-af93-e00e1e033fa3', NULL, 21, 21, 'I will make you a terror, and you shall no more have any being; though you are sought for, yet you will never be found again, says the Lord Yahweh.'),
  ('d4159066-9428-5668-adf2-35b7bf23315c', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 1, 1, 'The word of Yahweh came again to me, saying,'),
  ('091ab59e-5a77-59d6-a1a8-c727b410f12b', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 2, 2, 'You, son of man, take up a lamentation over Tyre;'),
  ('35748688-1013-56e8-aefa-b96af47bf342', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 3, 3, 'and tell Tyre, you who dwell at the entry of the sea, who are the merchant of the peoples to many islands, thus says the Lord Yahweh: You, Tyre, have said, I am perfect in beauty.'),
  ('f785a931-40c6-530b-a7cc-231ddf5ac9ef', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 4, 4, 'Your borders are in the heart of the seas; your builders have perfected your beauty.'),
  ('60ac5a5d-473b-5710-a821-edaf85b59c46', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 5, 5, 'They have made all your planks of fir trees from Senir; they have taken a cedar from Lebanon to make a mast for you.'),
  ('b8d93594-aa83-553d-aea0-02cadf78192c', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 6, 6, 'Of the oaks of Bashan have they made your oars; they have made your benches of ivory inlaid in boxwood, from the islands of Kittim.'),
  ('b54cc2cf-4d05-5504-acd2-1b1b9f9ac795', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 7, 7, 'Of fine linen with embroidered work from Egypt was your sail, that it might be to you for a banner; blue and purple from the islands of Elishah was your awning.'),
  ('c8e21b5f-ffa1-5827-a0c3-665b5a32156c', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 8, 8, 'The inhabitants of Sidon and Arvad were your rowers: your wise men, Tyre, were in you, they were your pilots.'),
  ('e8dc1da9-fcdd-52d5-a3b4-37aca3b90f76', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 9, 9, 'The old men of Gebal and the wise men of it were in you your repairers of ship seams: all the ships of the sea with their mariners were in you to deal in your merchandise.'),
  ('d7f7d0bd-df23-5baa-ada7-8bb2a3ac2aac', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 10, 10, 'Persia and Lud and Put were in your army, your men of war: they hanged the shield and helmet in you; they set forth your comeliness.'),
  ('d82a3d94-c416-5afb-a5d2-8e17e6bdd44e', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 11, 11, 'The men of Arvad with your army were on your walls all around, and valorous men were in your towers; they hanged their shields on your walls all around; they have perfected your beauty.'),
  ('814e6907-d186-5099-ad00-b82b81454ef9', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 12, 12, 'Tarshish was your merchant by reason of the multitude of all kinds of riches; with silver, iron, tin, and lead, they traded for your wares.'),
  ('4fd613f2-b84e-55f1-a79c-3b43d738154b', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 13, 13, 'Javan, Tubal, and Meshech, they were your traffickers; they traded the persons of men and vessels of brass for your merchandise.'),
  ('372f3106-04aa-51ad-aa21-7a8dab638e4b', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 14, 14, 'They of the house of Togarmah traded for your wares with horses and war horses and mules.'),
  ('7356653a-113d-5b03-a558-cb2d63e3dc89', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 15, 15, 'The men of Dedan were your traffickers; many islands were the market of your hand: they brought you in exchange horns of ivory and ebony.'),
  ('273ef55b-be08-5cc8-aa16-cb5ae9e5d604', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 16, 16, 'Syria was your merchant by reason of the multitude of your handiworks: they traded for your wares with emeralds, purple, and embroidered work, and fine linen, and coral, and rubies.'),
  ('02e02dca-f4e6-5bca-af6b-a23d6fce175d', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 17, 17, 'Judah, and the land of Israel, they were your traffickers: they traded for your merchandise wheat of Minnith, and confections, and honey, and oil, and balm.'),
  ('39f7c6f1-69df-576c-a066-1e11a324c879', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 18, 18, 'Damascus was your merchant for the multitude of your handiworks, by reason of the multitude of all kinds of riches, with the wine of Helbon, and white wool.'),
  ('a514da5f-2ed0-5209-a078-a9dcd8dab56a', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 19, 19, 'Vedan and Javan traded with yarn for your wares: bright iron, cassia, and calamus, were among your merchandise.'),
  ('3464f92a-0405-5da1-a9d0-8a6d19a75091', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 20, 20, 'Dedan was your trafficker in precious cloths for riding.'),
  ('0337afc0-5299-5d95-a618-904ea265da06', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 21, 21, 'Arabia, and all the princes of Kedar, they were the merchants of your hand; in lambs, and rams, and goats, in these were they your merchants.'),
  ('2ca09241-c328-52a0-aada-1baff187d2c8', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 22, 22, 'The traffickers of Sheba and Raamah, they were your traffickers; they traded for your wares with the chief of all spices, and with all precious stones, and gold.'),
  ('952af7f8-ca79-5d1a-a085-f9241b3db89b', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 23, 23, 'Haran and Canneh and Eden, the traffickers of Sheba, Asshur [and] Chilmad, were your traffickers.'),
  ('4aa6be05-863e-530b-ad8b-3894e948842b', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 24, 24, 'These were your traffickers in choice wares, in wrappings of blue and embroidered work, and in chests of rich clothing, bound with cords and made of cedar, among your merchandise.'),
  ('54f0ea1d-cfa1-5420-a3ec-c32e1e093488', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 25, 25, 'The ships of Tarshish were your caravans for your merchandise: and you were replenished, and made very glorious in the heart of the seas.'),
  ('45ef9e29-aea8-5d0b-adec-9623486648e1', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 26, 26, 'Your rowers have brought you into great waters: the east wind has broken you in the heart of the seas.'),
  ('21444e7f-9ac1-5ec9-aee3-6cc0951cc3f9', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 27, 27, 'Your riches, and your wares, your merchandise, your mariners, and your pilots, your repairers of ship seams, and the dealers in your merchandise, and all your men of war, who are in you, with all your company which is in the midst of you, shall fall into the heart of the seas in the day of your ruin.'),
  ('e4f27f2c-f01d-56fe-a70c-77118b1a7581', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 28, 28, 'At the sound of the cry of your pilots the suburbs shall shake.'),
  ('a4edfd85-69ed-54d0-ac51-6a5d87e732cf', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 29, 29, 'All who handled the oar, the mariners, [and] all the pilots of the sea, shall come down from their ships; they shall stand on the land,'),
  ('910ce290-8920-5826-a61f-1026130c6279', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 30, 30, 'and shall cause their voice to be heard over you, and shall cry bitterly, and shall cast up dust on their heads, they shall wallow themselves in the ashes:'),
  ('1865cf5b-2a60-5110-a2bf-683293c7116b', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 31, 31, 'and they shall make themselves bald for you, and clothe them with sackcloth, and they shall weep for you in bitterness of soul with bitter mourning.'),
  ('0d75cdb2-d635-57de-af88-7487c36a945a', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 32, 32, 'In their wailing they shall take up a lamentation for you, and lament over you, [saying], Who is there like Tyre, like her who is brought to silence in the midst of the sea?'),
  ('19afb799-5291-5a9c-a2aa-832dec2e0a06', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 33, 33, 'When your wares went forth out of the seas, you filled many peoples; you did enrich the kings of the earth with the multitude of your riches and of your merchandise.'),
  ('0abda083-8d21-54cc-a484-1491fbecf87f', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 34, 34, 'In the time that you were broken by the seas in the depths of the waters, your merchandise and all your company did fall in the midst of you.'),
  ('c0de9621-91f7-54a0-a718-82c4ae4915d5', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 35, 35, 'All the inhabitants of the islands are astonished at you, and their kings are horribly afraid; they are troubled in their face.'),
  ('a646eadb-5d69-5ebe-ae9c-23a6d90e58a4', 'fe85e602-ef0b-5c63-a9ad-b1b217b910d1', NULL, 36, 36, 'The merchants among the peoples hiss at you; you are become a terror, and you shall nevermore have any being.'),
  ('554d09d8-b411-57f4-a751-c5aea2902fc6', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 1, 1, 'The word of Yahweh came again to me, saying,'),
  ('314e03a2-260d-5013-ae43-0231fdfa8d97', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 2, 2, 'Son of man, tell the prince of Tyre, Thus says the Lord Yahweh: Because your heart is lifted up, and you have said, I am a god, I sit in the seat of God, in the midst of the seas; yet you are man, and not God, though you did set your heart as the heart of God--'),
  ('7f9c4174-98b7-5de0-a90b-4d4b1c135d53', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 3, 3, 'behold, you are wiser than Daniel; there is no secret that is hidden from you;'),
  ('54fd102d-35ce-5531-a6a2-3a29f3be8e56', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 4, 4, 'by your wisdom and by your understanding you have gotten yourself riches, and have gotten gold and silver into your treasures;'),
  ('9f47d7d0-9b94-5d37-a1d6-9141b54387ce', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 5, 5, 'by your great wisdom [and] by your traffic you have increased your riches, and your heart is lifted up because of your riches--'),
  ('d18e0491-21a9-53f8-adf4-6a96e143ba46', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 6, 6, 'therefore thus says the Lord Yahweh: Because you have set your heart as the heart of God,'),
  ('8b81e5ca-d653-57e9-a9fb-37cb64afc930', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 7, 7, 'therefore, behold, I will bring strangers on you, the terrible of the nations; and they shall draw their swords against the beauty of your wisdom, and they shall defile your brightness.'),
  ('cec1cbd5-bff7-5d73-a74c-8221b2e23a02', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 8, 8, 'They shall bring you down to the pit; and you shall die the death of those who are slain, in the heart of the seas.'),
  ('c5d92e79-324a-5041-abab-cb884fc82638', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 9, 9, 'Will you yet say before him who kills you, I am God? but you are man, and not God, in the hand of him who wounds you.'),
  ('d1ba254d-e278-55fa-ad8c-71d14b0632ed', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 10, 10, 'You shall die the death of the uncircumcised by the hand of strangers: for I have spoken it, says the Lord Yahweh.'),
  ('1775b84f-7b3a-5124-a771-42998216f438', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 11, 11, 'Moreover the word of Yahweh came to me, saying,'),
  ('2fff6b0e-7ee5-5604-a329-e80b13da51fd', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 12, 12, 'Son of man, take up a lamentation over the king of Tyre, and tell him, Thus says the Lord Yahweh: You seal up the sum, full of wisdom, and perfect in beauty.'),
  ('d967c703-d710-509a-a0ad-f7d94e49d5d3', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 13, 13, 'You were in Eden, the garden of God; every precious stone adorned you: ruby, topaz, emerald, chrysolite, onyx, jasper, sapphire, turquoise, and beryl. Gold work of tambourines and of pipes was in you. In the day that you were created they were prepared.'),
  ('cb05dd74-a0f6-59d5-a0a3-20c12692672b', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 14, 14, 'You were the anointed cherub who covers: and I set you, [so that] you were on the holy mountain of God; you have walked up and down in the midst of the stones of fire.'),
  ('c40ad0b2-298d-5002-abc5-22a429781d49', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 15, 15, 'You were perfect in your ways from the day that you were created, until unrighteousness was found in you.'),
  ('5c8d9243-6d3e-5041-a4bb-34d7d9793877', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 16, 16, 'By the abundance of your traffic they filled the midst of you with violence, and you have sinned: therefore I have cast you as profane out of the mountain of God; and I have destroyed you, covering cherub, from the midst of the stones of fire.'),
  ('3139122e-df33-5d40-a299-b0680aed1de1', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 17, 17, 'Your heart was lifted up because of your beauty; you have corrupted your wisdom by reason of your brightness: I have cast you to the ground; I have laid you before kings, that they may see you.'),
  ('d0ec2308-6e47-5ec6-abc5-481b897e82e1', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 18, 18, 'By the multitude of your iniquities, in the unrighteousness of your traffic, you have profaned your sanctuaries; therefore have I brought forth a fire from the midst of you; it has devoured you, and I have turned you to ashes on the earth in the sight of all those who see you.'),
  ('a89fe889-6b83-567a-ac17-a19e36d2fea7', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 19, 19, 'All those who know you among the peoples shall be astonished at you: you have become a terror, and you shall nevermore have any being.'),
  ('366ad086-d561-50eb-a416-9ad05f834b29', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 20, 20, 'The word of Yahweh came to me, saying,'),
  ('f7beab89-5df8-5011-a2ff-c7908aefb704', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 21, 21, 'Son of man, set your face toward Sidon, and prophesy against it,'),
  ('71236628-593d-51b5-ad58-220713cd82d3', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 22, 22, 'and say, Thus says the Lord Yahweh: Behold, I am against you, Sidon; and I will be glorified in the midst of you; and they shall know that I am Yahweh, when I shall have executed judgments in her, and shall be sanctified in her.'),
  ('4366a97c-70b9-51a9-a88e-a296cc707d09', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 23, 23, 'For I will send pestilence into her, and blood into her streets; and the wounded shall fall in the midst of her, with the sword on her on every side; and they shall know that I am Yahweh.'),
  ('4e9f7aaf-dacf-5de6-a078-d8c69ec5d0e0', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 24, 24, 'There shall be no more a pricking brier to the house of Israel, nor a hurting thorn of any that are around them, that did despite to them; and they shall know that I am the Lord Yahweh.'),
  ('4e7fda18-683b-59f2-aee8-1ec45eb82fac', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 25, 25, 'Thus says the Lord Yahweh: When I shall have gathered the house of Israel from the peoples among whom they are scattered, and shall be sanctified in them in the sight of the nations, then shall they dwell in their own land which I gave to my servant Jacob.'),
  ('12bdcd37-6176-5f55-ab1d-38058bbe39af', '8d61eb39-6853-53f4-a3da-3a397c9ef8f5', NULL, 26, 26, 'They shall dwell securely therein; yes, they shall build houses, and plant vineyards, and shall dwell securely, when I have executed judgments on all those who do them despite all around them; and they shall know that I am Yahweh their God.'),
  ('c680c7f2-4ff8-5ce7-a20c-e5cb567a068f', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 1, 1, 'In the tenth year, in the tenth month, on the twelfth day of the month, the word of Yahweh came to me, saying,'),
  ('6e391064-e691-5429-a265-b6f85be924ed', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 2, 2, '"Son of man, set your face against Pharaoh king of Egypt, and prophesy against him and against all Egypt.'),
  ('65fddefb-2886-5298-a137-c6cf47eddff1', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 3, 3, 'Speak and say, ''Thus says the Lord Yahweh: "Behold, I am against you, Pharaoh king of Egypt, the great monster that lies in the midst of his rivers, that has said, ''My river is my own, and I have made it for myself.'''),
  ('0b6b4afe-b948-541a-a547-a029e20bfcfb', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 4, 4, 'I will put hooks in your jaws, and I will make the fish of your rivers stick to your scales; and I will bring you up out of the midst of your rivers, with all the fish of your rivers which stick to your scales.'),
  ('2367e476-9531-56b0-aa51-c63580c801c2', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 5, 5, 'I''ll cast you forth into the wilderness, you and all the fish of your rivers. You''ll fall on the open field. You won''t be brought together, nor gathered. I have given you for food to the animals of the earth and to the birds of the sky.'),
  ('2b80b607-44c4-5307-a0f6-140ac7dd3129', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 6, 6, 'All the inhabitants of Egypt will know that I am Yahweh, because they have been a staff of reed to the house of Israel.'),
  ('b2b59209-1992-5f13-a7de-57425d3595d9', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 7, 7, 'When they took hold of you by your hand, you broke, and tore all their shoulders; and when they leaned on you, you broke, and paralyzed all of their thighs."'),
  ('d946070c-48d6-5694-a3a5-7c4ce5d5cae3', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 8, 8, 'Therefore thus says the Lord Yahweh: "Behold, I will bring a sword on you, and will cut off man and animal from you.'),
  ('994ab5c7-6058-5203-a8b0-28546f170ab8', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 9, 9, 'The land of Egypt shall be a desolation and a waste; and they shall know that I am Yahweh. Because he has said, ''The river is mine, and I have made it;'''),
  ('73e992ce-8196-53d7-aa92-b5289757887c', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 10, 10, 'therefore, behold, I am against you, and against your rivers, and I will make the land of Egypt an utter waste and desolation, from the tower of Seveneh even to the border of Ethiopia.'),
  ('85e9d3da-edbc-5b1d-a562-73fdbe73f25e', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 11, 11, 'No foot of man shall pass through it, nor foot of animal shall pass through it, neither shall it be inhabited forty years.'),
  ('7b4bb940-11cd-537d-a8fb-bfe77bf11b83', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 12, 12, 'I will make the land of Egypt a desolation in the midst of the countries that are desolate; and her cities among the cities that are laid waste shall be a desolation forty years; and I will scatter the Egyptians among the nations, and will disperse them through the countries."'),
  ('b4414441-84fe-53a5-a9e6-77fc40217516', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 13, 13, 'For thus says the Lord Yahweh: "At the end of forty years will I gather the Egyptians from the peoples where they were scattered;'),
  ('6f2f8c93-8562-5e5f-a1cf-aa443e6a7d33', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 14, 14, 'and I will bring back the captivity of Egypt, and will cause them to return into the land of Pathros, into the land of their birth; and they shall be there a base kingdom.'),
  ('00c3381d-b996-5222-a183-82908006ec2d', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 15, 15, 'It shall be the base of the kingdoms; neither shall it any more lift itself up above the nations: and I will diminish them, that they shall no more rule over the nations.'),
  ('66a5c00d-9114-5427-a457-1084a2217df7', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 16, 16, 'It shall be no more the confidence of the house of Israel, bringing iniquity to memory, when they turn to look after them: and they shall know that I am the Lord Yahweh."''"'),
  ('c4f6c34b-f3c9-52a7-a4cc-65313a4d5d05', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 17, 17, 'It came to pass in the seven and twentieth year, in the first [month], in the first [day] of the month, the word of Yahweh came to me, saying,'),
  ('0e91fa0a-2c39-54f0-a6c3-23e4f0751e25', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 18, 18, 'Son of man, Nebuchadnezzar king of Babylon caused his army to serve a great service against Tyre: every head was made bald, and every shoulder was worn; yet had he no wages, nor his army, from Tyre, for the service that he had served against it.'),
  ('b809dc25-3b74-5211-a410-8508e87835d3', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 19, 19, 'Therefore thus says the Lord Yahweh: Behold, I will give the land of Egypt to Nebuchadnezzar king of Babylon; and he shall carry off her multitude, and take her spoil, and take her prey; and it shall be the wages for his army.'),
  ('1e63cb17-ecbe-54e7-a859-0fb391d687a8', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 20, 20, 'I have given him the land of Egypt as his recompense for which he served, because they worked for me, says the Lord Yahweh.'),
  ('a2390ab4-d551-5a8c-abc3-8720a7c957e7', 'f9783267-d679-54f3-a242-1b043eea570b', NULL, 21, 21, 'In that day will I cause a horn to bud forth to the house of Israel, and I will give you the opening of the mouth in the midst of them; and they shall know that I am Yahweh.'),
  ('6a1cf54e-65db-57c8-a100-77d1546262c7', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 1, 1, 'The word of Yahweh came again to me, saying,'),
  ('cb79fda0-328f-5afa-abaf-1546f789bfbb', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 2, 2, 'Son of man, prophesy, and say, Thus says the Lord Yahweh: Wail, Alas for the day!'),
  ('5d7fed82-7152-5ea6-ab5e-a265e42f33d3', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 3, 3, 'For the day is near, even the day of Yahweh is near; it shall be a day of clouds, a time of the nations.'),
  ('89806649-b461-5f63-a230-d6b0ae1b08d0', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 4, 4, 'A sword shall come on Egypt, and anguish shall be in Ethiopia, when the slain shall fall in Egypt; and they shall take away her multitude, and her foundations shall be broken down.'),
  ('103c2d1b-c286-5f9b-aa0b-eefa7ced962f', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 5, 5, 'Ethiopia, and Put, and Lud, and all the mixed people, and Cub, and the children of the land that is allied with them, shall fall with them by the sword.'),
  ('aced34b4-bef0-5185-aaa4-d23484c8658e', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 6, 6, 'Thus says Yahweh: They also who uphold Egypt shall fall; and the pride of her power shall come down: from the tower of Seveneh shall they fall in it by the sword, says the Lord Yahweh.'),
  ('1c0ac8c2-dca5-5b34-a64e-bbceba6e76c0', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 7, 7, 'They shall be desolate in the midst of the countries that are desolate; and her cities shall be in the midst of the cities that are wasted.'),
  ('6a3f650f-9a4f-552c-ac08-90b8588b48cb', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 8, 8, 'They shall know that I am Yahweh, when I have set a fire in Egypt, and all her helpers are destroyed.'),
  ('c28256f1-ec7b-5393-aa49-9a2d1d343f94', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 9, 9, 'In that day shall messengers go forth from before me in ships to make the careless Ethiopians afraid; and there shall be anguish on them, as in the day of Egypt; for, behold, it comes.'),
  ('02c963aa-f11f-5901-a6bd-f54757f4102b', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 10, 10, 'Thus says the Lord Yahweh: I will also make the multitude of Egypt to cease, by the hand of Nebuchadnezzar king of Babylon.'),
  ('31860526-c87e-51b9-a5d2-6f53a4a88673', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 11, 11, 'He and his people with him, the terrible of the nations, shall be brought in to destroy the land; and they shall draw their swords against Egypt, and fill the land with the slain.'),
  ('57bf172a-dfaf-5144-aded-77dcaca5efd9', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 12, 12, 'I will make the rivers dry, and will sell the land into the hand of evil men; and I will make the land desolate, and all that is therein, by the hand of strangers: I, Yahweh, have spoken it.'),
  ('a991e74a-1b72-508d-a846-ffb94b88c3de', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 13, 13, 'Thus says the Lord Yahweh: I will also destroy the idols, and I will cause the images to cease from Memphis; and there shall be no more a prince from the land of Egypt: and I will put a fear in the land of Egypt.'),
  ('fc726d94-93cd-5a02-aabd-33eb83153372', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 14, 14, 'I will make Pathros desolate, and will set a fire in Zoan, and will execute judgments on No.'),
  ('5f0016b1-0703-569a-a1f3-cb2653051a45', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 15, 15, 'I will pour my wrath on Sin, the stronghold of Egypt; and I will cut off the multitude of No.'),
  ('9a922751-d697-54c6-a417-2ce8f547a9d5', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 16, 16, 'I will set a fire in Egypt: Sin shall be in great anguish, and No shall be broken up; and Memphis [shall have] adversaries in the daytime.'),
  ('6d190781-6779-58d8-ab3b-1ff217bee1d2', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 17, 17, 'The young men of Aven and of Pibeseth shall fall by the sword; and these [cities] shall go into captivity.'),
  ('9ec70a68-738c-5f1d-a6cd-4aa31632292f', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 18, 18, 'At Tehaphnehes also the day shall withdraw itself, when I shall break there the yokes of Egypt, and the pride of her power shall cease in her: as for her, a cloud shall cover her, and her daughters shall go into captivity.'),
  ('f6dea506-eb0e-5546-a3cd-c8de6f7c5099', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 19, 19, 'Thus will I execute judgments on Egypt; and they shall know that I am Yahweh.'),
  ('80ca07ae-3cbd-537f-a547-82206fa3cceb', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 20, 20, 'It happened in the eleventh year, in the first [month], in the seventh [day] of the month, that the word of Yahweh came to me, saying,'),
  ('ee983d85-d288-5ad3-a082-022ee6ea6215', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 21, 21, 'Son of man, I have broken the arm of Pharaoh king of Egypt; and behold, it has not been bound up, to apply [healing] medicines, to put a bandage to bind it, that it be strong to hold the sword.'),
  ('823df3d6-7ac0-5831-a282-3efcd4f1fb24', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 22, 22, 'Therefore thus says the Lord Yahweh: Behold, I am against Pharaoh king of Egypt, and will break his arms, the strong [arm], and that which was broken; and I will cause the sword to fall out of his hand.'),
  ('497e5da4-92bf-5c4c-abeb-298f30ef8092', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 23, 23, 'I will scatter the Egyptians among the nations, and will disperse them through the countries.'),
  ('e5abdbb6-05b6-5937-a722-8c399c06e11e', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 24, 24, 'I will strengthen the arms of the king of Babylon, and put my sword in his hand: but I will break the arms of Pharaoh, and he shall groan before him with the groanings of a deadly wounded man.'),
  ('e21c3f35-c5d0-505b-a316-d5528dcdbf1e', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 25, 25, 'I will hold up the arms of the king of Babylon; and the arms of Pharaoh shall fall down; and they shall know that I am Yahweh, when I shall put my sword into the hand of the king of Babylon, and he shall stretch it out on the land of Egypt.'),
  ('aecc7c92-a402-53e6-a59a-2d5578dd42c1', 'ad23c7d5-629e-5188-a606-b3bf3a72494e', NULL, 26, 26, 'I will scatter the Egyptians among the nations, and disperse them through the countries; and they shall know that I am Yahweh.'),
  ('7cc25102-7d24-583d-a18a-151b6bdb0711', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 1, 1, 'It happened in the eleventh year, in the third [month], in the first [day] of the month, that the word of Yahweh came to me, saying,'),
  ('23e237d8-a32e-536e-ae89-309d86b3aeb2', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 2, 2, 'Son of man, tell Pharaoh king of Egypt, and to his multitude: Whom are you like in your greatness?'),
  ('e3c1517a-909e-57d1-a945-30c59c90c1fb', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 3, 3, 'Behold, the Assyrian was a cedar in Lebanon with beautiful branches, and with a forest-like shade, and of high stature; and its top was among the thick boughs.'),
  ('a790d15f-f641-5aee-a0cf-49a859ffe85d', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 4, 4, 'The waters nourished it, the deep made it to grow: its rivers ran all around its plantation; and it sent out its channels to all the trees of the field.'),
  ('be7c265e-a9cd-582e-a9b2-4aa334f63026', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 5, 5, 'Therefore its stature was exalted above all the trees of the field; and its boughs were multiplied, and its branches became long by reason of many waters, when it shot [them] forth.'),
  ('97b5053f-039a-5c92-ab54-5dd8f5426529', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 6, 6, 'All the birds of the sky made their nests in its boughs; and under its branches did all the animals of the field bring forth their young; and under its shadow lived all great nations.'),
  ('795c6842-c4fd-5ea0-af9b-fe04f23dc0e3', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 7, 7, 'Thus was it beautiful in its greatness, in the length of its branches; for its root was by many waters.'),
  ('400b83a6-69bb-5a8e-a977-5f44e680f0f0', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 8, 8, 'The cedars in the garden of God could not hide it; the fir trees were not like its boughs, and the plane trees were not as its branches; nor was any tree in the garden of God like it in its beauty.'),
  ('ca0f34ad-860a-546c-a4ba-b72ba539479f', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 9, 9, 'I made it beautiful by the multitude of its branches, so that all the trees of Eden, that were in the garden of God, envied it.'),
  ('7b470296-4537-5c08-a419-aa02c13988af', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 10, 10, 'Therefore thus said the Lord Yahweh: Because you are exalted in stature, and he has set his top among the thick boughs, and his heart is lifted up in his height;'),
  ('cc83d3c7-c5fb-5062-a4ee-cee95ea1b3d9', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 11, 11, 'I will even deliver him into the hand of the mighty one of the nations; he shall surely deal with him; I have driven him out for his wickedness.'),
  ('c203bf4f-e50b-5723-a91d-d8939b8138ff', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 12, 12, 'Strangers, the terrible of the nations, have cut him off, and have left him: on the mountains and in all the valleys his branches are fallen, and his boughs are broken by all the watercourses of the land; and all the peoples of the earth are gone down from his shadow, and have left him.'),
  ('f0a8af2f-4ccb-5b6a-a0ee-4b6cca69e189', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 13, 13, 'On his ruin all the birds of the sky shall dwell, and all the animals of the field shall be on his branches;'),
  ('0fe6e550-2b15-5a84-ae90-4082315be8b3', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 14, 14, 'to the end that none of all the trees by the waters exalt themselves in their stature, neither set their top among the thick boughs, nor that their mighty ones stand up on their height, [even] all who drink water: for they are all delivered to death, to the lower parts of the earth, in the midst of the children of men, with those who go down to the pit.'),
  ('1928c775-a7fc-5361-ae6c-1ffbefb02af3', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 15, 15, 'Thus says the Lord Yahweh: In the day when he went down to Sheol I caused a mourning: I covered the deep for him, and I restrained its rivers; and the great waters were stayed; and I caused Lebanon to mourn for him, and all the trees of the field fainted for him.'),
  ('b232aa56-bb6f-5e79-a8fd-38a3fd3aa66c', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 16, 16, 'I made the nations to shake at the sound of his fall, when I cast him down to Sheol with those who descend into the pit; and all the trees of Eden, the choice and best of Lebanon, all that drink water, were comforted in the lower parts of the earth.'),
  ('36a466cf-80a0-574e-ab8a-f013cb3efefd', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 17, 17, 'They also went down into Sheol with him to those who are slain by the sword; yes, those who were his arm, [that] lived under his shadow in the midst of the nations.'),
  ('d503930c-1b66-55cb-ab79-15735e42f3a9', '56175d39-1f63-5ca6-a6eb-f01a59ae045e', NULL, 18, 18, 'To whom are you thus like in glory and in greatness among the trees of Eden? yet you will be brought down with the trees of Eden to the lower parts of the earth: you shall lie in the midst of the uncircumcised, with those who are slain by the sword. This is Pharaoh and all his multitude, says the Lord Yahweh.'),
  ('1b0058d3-1924-5fe5-a4ef-2d0e61d77cec', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 1, 1, 'It happened in the twelfth year, in the twelfth month, in the first [day] of the month, that the word of Yahweh came to me, saying,'),
  ('3c0dd502-6b95-5e63-ac68-479ecc05c925', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 2, 2, 'Son of man, take up a lamentation over Pharaoh king of Egypt, and tell him, You were likened to a young lion of the nations: yet you are as a monster in the seas; and you did break forth with your rivers, and troubled the waters with your feet, and fouled their rivers.'),
  ('1b3ad386-fa90-5251-a5eb-52043964224f', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 3, 3, 'Thus says the Lord Yahweh: I will spread out my net on you with a company of many peoples; and they shall bring you up in my net.'),
  ('78237073-5edf-5bb1-aa78-5dcb57b36e43', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 4, 4, 'I will leave you on the land, I will cast you forth on the open field, and will cause all the birds of the sky to settle on you, and I will satisfy the animals of the whole earth with you.'),
  ('1e3deaf8-c9bf-53ae-a993-5af2d35f9959', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 5, 5, 'I will lay your flesh on the mountains, and fill the valleys with your height.'),
  ('a8de4092-2c33-5c3e-a619-99c44d27b099', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 6, 6, 'I will also water with your blood the land in which you swim, even to the mountains; and the watercourses shall be full of you.'),
  ('fa5897c4-d619-5cd7-a0c3-5a33610058cc', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 7, 7, 'When I shall extinguish you, I will cover the heavens, and make its stars dark; I will cover the sun with a cloud, and the moon shall not give its light.'),
  ('edbb558f-a824-5878-ad7b-0e3544609d4d', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 8, 8, 'All the bright lights of the sky will I make dark over you, and set darkness on your land, says the Lord Yahweh.'),
  ('baaa63a5-8056-50d3-a2ba-b6c21bcf40fa', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 9, 9, 'I will also trouble the hearts of many peoples, when I shall bring your destruction among the nations, into the countries which you have not known.'),
  ('683a36d6-7745-56fb-a1ec-5e3d98f71ade', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 10, 10, 'Yes, I will make many peoples amazed at you, and their kings shall be horribly afraid for you, when I shall brandish my sword before them; and they shall tremble at every moment, every man for his own life, in the day of your fall.'),
  ('c02ee6b6-6f48-51a0-aae1-0cb709f4fc3b', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 11, 11, 'For thus says the Lord Yahweh: The sword of the king of Babylon shall come on you.'),
  ('a1c734d3-fcab-5333-aa3b-976482c8c29c', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 12, 12, 'By the swords of the mighty will I cause your multitude to fall; the terrible of the nations are they all: and they shall bring to nothing the pride of Egypt, and all its multitude shall be destroyed.'),
  ('1d40ffe3-f11a-55eb-a947-0b420b1f9db0', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 13, 13, 'I will destroy also all its animals from beside many waters; neither shall the foot of man trouble them any more, nor the hoofs of animals trouble them.'),
  ('d98250c4-15a8-5bcd-ae2b-7571294ebaba', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 14, 14, 'Then will I make their waters clear, and cause their rivers to run like oil, says the Lord Yahweh.'),
  ('16750811-3412-577e-aca3-9ab5ee60f378', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 15, 15, 'When I shall make the land of Egypt desolate and waste, a land destitute of that of which it was full, when I shall strike all those who dwell therein, then shall they know that I am Yahweh.'),
  ('9999c8d2-8947-5d64-a7b3-36b4d6e25fe2', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 16, 16, 'This is the lamentation with which they shall lament; the daughters of the nations shall lament therewith; over Egypt, and over all her multitude, shall they lament therewith, says the Lord Yahweh.'),
  ('74b0abd4-bc0c-5ba4-a8bf-7d66247953b9', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 17, 17, 'It happened also in the twelfth year, in the fifteenth [day] of the month, that the word of Yahweh came to me, saying,'),
  ('d4f25253-91e4-5ed1-a486-5dcd8a464e17', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 18, 18, 'Son of man, wail for the multitude of Egypt, and cast them down, even her, and the daughters of the famous nations, to the lower parts of the earth, with those who go down into the pit.'),
  ('7f8adfa2-5453-5010-a840-30e9651510b7', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 19, 19, 'Whom do you pass in beauty? Go down, and be laid with the uncircumcised.'),
  ('1af7b886-14a9-50cb-a74d-efb7f91735a8', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 20, 20, 'They shall fall in the midst of those who are slain by the sword: she is delivered to the sword; draw her away and all her multitudes.'),
  ('42c58a64-c3ba-561e-afd1-11e14066e9f2', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 21, 21, 'The strong among the mighty shall speak to him out of the midst of Sheol with those who help him: they are gone down, they lie still, even the uncircumcised, slain by the sword.'),
  ('f5eb162b-9bab-5839-a776-aaf5ad061b7c', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 22, 22, 'Asshur is there and all her company; her graves are all around her; all of them slain, fallen by the sword;'),
  ('15299a88-df78-50ec-a1a7-03836502843b', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 23, 23, 'whose graves are set in the uttermost parts of the pit, and her company is around her grave; all of them slain, fallen by the sword, who caused terror in the land of the living.'),
  ('077786fe-3d03-5559-a370-7ee84ef26677', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 24, 24, 'There is Elam and all her multitude around her grave; all of them slain, fallen by the sword, who are gone down uncircumcised into the lower parts of the earth, who caused their terror in the land of the living, and have borne their shame with those who go down to the pit.'),
  ('893ed2e9-1dc3-5998-a7ec-0ce91242a367', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 25, 25, 'They have set her a bed in the midst of the slain with all her multitude; her graves are around her; all of them uncircumcised, slain by the sword; for their terror was caused in the land of the living, and they have borne their shame with those who go down to the pit: he is put in the midst of those who are slain.'),
  ('44501761-0dcf-5e3d-a993-ab5a2e3ca803', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 26, 26, 'There is Meshech, Tubal, and all their multitude; their graves are around them; all of them uncircumcised, slain by the sword; for they caused their terror in the land of the living.'),
  ('574c9c63-d36d-54ac-a9f3-da1b09a5e61e', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 27, 27, 'They shall not lie with the mighty who are fallen of the uncircumcised, who are gone down to Sheol with their weapons of war, and have laid their swords under their heads, and their iniquities are on their bones; for [they were] the terror of the mighty in the land of the living.'),
  ('857f4919-14ad-5ec1-ad4c-12bdf4a052cb', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 28, 28, 'But you shall be broken in the midst of the uncircumcised, and shall lie with those who are slain by the sword.'),
  ('3dccc910-e9a0-54b4-a7dc-aea9f8f546dc', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 29, 29, 'There is Edom, her kings and all her princes, who in their might are laid with those who are slain by the sword: they shall lie with the uncircumcised, and with those who go down to the pit.'),
  ('13dabb7a-b031-5e1f-a283-f907ed7b2cb4', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 30, 30, 'There are the princes of the north, all of them, and all the Sidonians, who are gone down with the slain; in the terror which they caused by their might they are put to shame; and they lie uncircumcised with those who are slain by the sword, and bear their shame with those who go down to the pit.'),
  ('8f97de9e-4b1e-5e26-a842-d853f422b25f', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 31, 31, 'Pharaoh shall see them, and shall be comforted over all his multitude, even Pharaoh and all his army, slain by the sword, says the Lord Yahweh.'),
  ('f160559f-0228-5d5e-ad32-afce370b6dfe', '72ea4785-ac82-5330-aa9d-0187b89e633e', NULL, 32, 32, 'For I have put his terror in the land of the living; and he shall be laid in the midst of the uncircumcised, with those who are slain by the sword, even Pharaoh and all his multitude, says the Lord Yahweh.'),
  ('bb03f7af-5cb9-5145-a013-e4af213ef5fb', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('d8301a6f-d062-5045-abe4-c3a8e6a6b903', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 2, 2, 'Son of man, speak to the children of your people, and tell them, When I bring the sword on a land, and the people of the land take a man from among them, and set him for their watchman;'),
  ('6badb2fa-ad58-5657-a625-122a9e8727f4', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 3, 3, 'if, when he sees the sword come on the land, he blow the trumpet, and warn the people;'),
  ('e027ec81-cbd3-5760-a892-e358523ad40e', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 4, 4, 'then whoever hears the sound of the trumpet, and doesn''t take warning, if the sword come, and take him away, his blood shall be on his own head.'),
  ('0ed7c327-49ad-5d86-ab72-28b906f86e5a', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 5, 5, 'He heard the sound of the trumpet, and didn''t take warning; his blood shall be on him; whereas if he had taken warning, he would have delivered his soul.'),
  ('bff73d8a-581c-5095-a0a7-d838ee2c763f', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 6, 6, 'But if the watchman sees the sword come, and doesn''t blow the trumpet, and the people aren''t warned, and the sword comes, and take any person from among them; he is taken away in his iniquity, but his blood will I require at the watchman''s hand.'),
  ('2e4904c1-15fe-537c-a88e-e4d27c7cd921', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 7, 7, 'So you, son of man, I have set you a watchman to the house of Israel; therefore hear the word at my mouth, and give them warning from me.'),
  ('91bf9e35-d27e-553a-ac6a-167b1826bb23', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 8, 8, 'When I tell the wicked, O wicked man, you shall surely die, and you don''t speak to warn the wicked from his way; that wicked man shall die in his iniquity, but his blood will I require at your hand.'),
  ('a68d9d25-d6f0-5f1a-af61-eb4d8b95eba7', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 9, 9, 'Nevertheless, if you warn the wicked of his way to turn from it, and he doesn''t turn from his way; he shall die in his iniquity, but you have delivered your soul.'),
  ('5b73eedb-d28c-5f4f-a8a8-c380242aeb9b', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 10, 10, 'You, son of man, tell the house of Israel: Thus you speak, saying, Our transgressions and our sins are on us, and we pine away in them; how then can we live?'),
  ('4671894d-8ced-5bf3-a935-d060df8573db', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 11, 11, 'Tell them, As I live, says the Lord Yahweh, I have no pleasure in the death of the wicked; but that the wicked turn from his way and live: turn, turn from your evil ways; for why will you die, house of Israel?'),
  ('72981873-a64a-5372-a5ad-d70d77508921', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 12, 12, 'You, son of man, tell the children of your people, The righteousness of the righteous shall not deliver him in the day of his disobedience; and as for the wickedness of the wicked, he shall not fall thereby in the day that he turns from his wickedness; neither shall he who is righteous be able to live thereby in the day that he sins.'),
  ('4d02f931-6fbb-5e3b-a3a7-86994558f05c', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 13, 13, 'When I tell the righteous, that he shall surely live; if he trust to his righteousness, and commit iniquity, none of his righteous deeds shall be remembered; but in his iniquity that he has committed, therein shall he die.'),
  ('117625d2-020f-5d46-ac38-9dbe88bf4c7c', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 14, 14, 'Again, when I say to the wicked, You shall surely die; if he turn from his sin, and do that which is lawful and right;'),
  ('0c7ce457-885f-5fe3-a2d1-42bfd4c7543a', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 15, 15, 'if the wicked restore the pledge, give again that which he had taken by robbery, walk in the statutes of life, committing no iniquity; he shall surely live, he shall not die.'),
  ('da0fe6ef-56e4-5a7c-aa81-764a393aa603', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 16, 16, 'None of his sins that he has committed shall be remembered against him: he has done that which is lawful and right; he shall surely live.'),
  ('422906a4-82fe-5ee2-af96-781adde1cb7d', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 17, 17, 'Yet the children of your people say, The way of the Lord is not equal: but as for them, their way is not equal.'),
  ('a3c21c5c-5c7a-5a23-a3fc-e69d6b3d9737', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 18, 18, 'When the righteous turns from his righteousness, and commits iniquity, he shall even die therein.'),
  ('cccba4b2-1caa-5c5a-af06-ba3a55aecc48', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 19, 19, 'When the wicked turns from his wickedness, and does that which is lawful and right, he shall live thereby.'),
  ('d3e579b9-744b-5730-a236-65d6ebf08a6e', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 20, 20, 'Yet you say, The way of the Lord is not equal. House of Israel, I will judge every one of you after his ways.'),
  ('06805a96-32bd-573a-a6a2-93f91754a369', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 21, 21, 'It happened in the twelfth year of our captivity, in the tenth [month], in the fifth [day] of the month, that one who had escaped out of Jerusalem came to me, saying, The city has been struck.'),
  ('35248013-7f01-5180-ad5c-f4ec8e386e90', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 22, 22, 'Now the hand of Yahweh had been on me in the evening, before he who was escaped came; and he had opened my mouth, until he came to me in the morning; and my mouth was opened, and I was no more mute.'),
  ('3098eec1-79ec-5c16-ab9d-1563e9c67e8b', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 23, 23, 'The word of Yahweh came to me, saying,'),
  ('9e5da8e5-6f5c-54e6-a144-5f9c5af7d9ff', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 24, 24, 'Son of man, they who inhabit those waste places in the land of Israel speak, saying, Abraham was one, and he inherited the land: but we are many; the land is given us for inheritance.'),
  ('592ae27c-c715-5d35-a586-722c481eb196', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 25, 25, 'Therefore tell them, Thus says the Lord Yahweh: You eat with the blood, and lift up your eyes to your idols, and shed blood: and shall you possess the land?'),
  ('0a6eb58b-37c2-5c84-aefe-97ea9e85336b', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 26, 26, 'You stand on your sword, you work abomination, and every one of you defiles his neighbor''s wife: and shall you possess the land?'),
  ('28b560e2-0c88-50ec-aac8-4b0537ea9d75', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 27, 27, 'You shall tell them, Thus says the Lord Yahweh: As I live, surely those who are in the waste places shall fall by the sword; and him who is in the open field will I give to the animals to be devoured; and those who are in the strongholds and in the caves shall die of the pestilence.'),
  ('c42bd9f7-52f2-50c6-ae7f-464009d90bd5', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 28, 28, 'I will make the land a desolation and an astonishment; and the pride of her power shall cease; and the mountains of Israel shall be desolate, so that none shall pass through.'),
  ('9f23d071-6b1e-5371-a261-32c0b7f4f597', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 29, 29, 'Then shall they know that I am Yahweh, when I have made the land a desolation and an astonishment, because of all their abominations which they have committed.'),
  ('39f3bf97-b470-5aa3-aeff-24fb360c1242', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 30, 30, 'As for you, son of man, the children of your people talk of you by the walls and in the doors of the houses, and speak one to another, everyone to his brother, saying, Please come and hear what is the word that comes forth from Yahweh.'),
  ('5682edbc-c7b7-5252-acc7-de900659803b', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 31, 31, 'They come to you as the people come, and they sit before you as my people, and they hear your words, but don''t do them; for with their mouth they show much love, but their heart goes after their gain.'),
  ('08b5c8af-e5c7-57a0-aa8d-ca037d8ab018', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 32, 32, 'Behold, you are to them as a very lovely song of one who has a pleasant voice, and can play well on an instrument; for they hear your words, but they don''t do them.'),
  ('fba14ed5-bf1c-5e9e-adbd-6e05a642b6ad', '885ea22d-db3e-546f-a437-5a74367a8daf', NULL, 33, 33, 'When this comes to pass, (behold, it comes), then shall they know that a prophet has been among them.'),
  ('e6af43e6-0b99-5b5e-a003-3e346caa9e1c', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('cb221cf8-be3b-55ce-a467-f71bcb1405b2', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 2, 2, 'Son of man, prophesy against the shepherds of Israel, prophesy, and tell them, even to the shepherds, Thus says the Lord Yahweh: Woe to the shepherds of Israel who feed themselves! Shouldn''t the shepherds feed the sheep?'),
  ('d3360d6a-607b-5b24-a4dc-432444d0909e', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 3, 3, 'You eat the fat, and you clothe yourself with the wool, you kill the fatlings; but you don''t feed the sheep.'),
  ('744f2045-e43c-52fb-ac0c-faf058464e29', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 4, 4, 'You haven''t strengthened the diseased, neither have you healed that which was sick, neither have you bound up that which was broken, neither have you brought back that which was driven away, neither have you sought that which was lost; but with force and with rigor you have ruled over them.'),
  ('b071d326-77c8-5c94-a147-f0f1930a6921', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 5, 5, 'They were scattered, because there was no shepherd; and they became food to all the animals of the field, and were scattered.'),
  ('101bf041-430c-59b1-a831-5a5ea6cdd104', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 6, 6, 'My sheep wandered through all the mountains, and on every high hill: yes, my sheep were scattered on all the surface of the earth; and there was none who searched or sought.'),
  ('972b6428-724d-5bf0-a502-24a7049c6992', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 7, 7, 'Therefore, you shepherds, hear the word of Yahweh:'),
  ('748947dd-3541-5b6c-a38e-97d83fd684a6', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 8, 8, 'As I live, says the Lord Yahweh, surely because my sheep became a prey, and my sheep became food to all the animals of the field, because there was no shepherd, neither did my shepherds search for my sheep, but the shepherds fed themselves, and didn''t feed my sheep;'),
  ('2e95e801-94b9-5682-aa0a-e77da79251e3', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 9, 9, 'therefore, you shepherds, hear the word of Yahweh:'),
  ('ddd588df-e353-5f18-a94e-ac45d474b8bf', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 10, 10, 'Thus says the Lord Yahweh: Behold, I am against the shepherds; and I will require my sheep at their hand, and cause them to cease from feeding the sheep; neither shall the shepherds feed themselves any more; and I will deliver my sheep from their mouth, that they may not be food for them.'),
  ('6c32c667-2acb-5a0c-a252-6b6fa65e4f8d', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 11, 11, 'For thus says the Lord Yahweh: Behold, I myself, even I, will search for my sheep, and will seek them out.'),
  ('ac874c3d-4ec2-5429-a872-455e1eee73e0', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 12, 12, 'As a shepherd seeks out his flock in the day that he is among his sheep that are scattered abroad, so will I seek out my sheep; and I will deliver them out of all places where they have been scattered in the cloudy and dark day.'),
  ('3fe7e339-b92f-5b94-afe5-907ea2b50212', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 13, 13, 'I will bring them out from the peoples, and gather them from the countries, and will bring them into their own land; and I will feed them on the mountains of Israel, by the watercourses, and in all the inhabited places of the country.'),
  ('16bda8a1-7ef1-5fe7-a411-0ed459643549', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 14, 14, 'I will feed them with good pasture; and on the mountains of the height of Israel shall their fold be: there shall they lie down in a good fold; and on fat pasture shall they feed on the mountains of Israel.'),
  ('97bb7ed1-9e67-5264-aa56-2c30569b4586', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 15, 15, 'I myself will be the shepherd of my sheep, and I will cause them to lie down, says the Lord Yahweh.'),
  ('61e714f6-e3f6-5eb8-a66f-ee465566803f', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 16, 16, 'I will seek that which was lost, and will bring back that which was driven away, and will bind up that which was broken, and will strengthen that which was sick: but the fat and the strong I will destroy; I will feed them in justice.'),
  ('484b78d7-08fb-5b5b-aa81-73312d271b07', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 17, 17, 'As for you, O my flock, thus says the Lord Yahweh: Behold, I judge between sheep and sheep, the rams and the male goats.'),
  ('91d10277-0afa-5ceb-a3ed-fd3382f2d1ce', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 18, 18, 'Does it seem a small thing to you to have fed on the good pasture, but you must tread down with your feet the residue of your pasture? and to have drunk of the clear waters, but you must foul the residue with your feet?'),
  ('9b1ae341-84e8-5669-aabe-9735e123667a', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 19, 19, 'As for my sheep, they eat that which you have trodden with your feet, and they drink that which you have fouled with your feet.'),
  ('472d0b40-6229-51bd-a625-89d8b8d61c75', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 20, 20, 'Therefore thus says the Lord Yahweh to them: Behold, I, even I, will judge between the fat sheep and the lean sheep.'),
  ('20e1ab9c-544e-55c7-a075-d6471b4c973a', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 21, 21, 'Because you thrust with side and with shoulder, and push all the diseased with your horns, until you have scattered them abroad;'),
  ('942ba2b7-2346-5fc0-ab9d-1ade3baee98d', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 22, 22, 'therefore will I save my flock, and they shall no more be a prey; and I will judge between sheep and sheep.'),
  ('424b4940-08e5-5dc1-a450-0ed19f5079c7', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 23, 23, 'I will set up one shepherd over them, and he shall feed them, even my servant David; he shall feed them, and he shall be their shepherd.'),
  ('d7b0a40a-ed1b-5e14-a7f5-3f0303f94b71', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 24, 24, 'I, Yahweh, will be their God, and my servant David prince among them; I, Yahweh, have spoken it.'),
  ('48d41bea-5f0f-5360-a877-a1941e8c40c4', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 25, 25, 'I will make with them a covenant of peace, and will cause evil animals to cease out of the land; and they shall dwell securely in the wilderness, and sleep in the woods.'),
  ('d05e36d1-2ac9-58ad-afa3-dd7b7ef9e0a9', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 26, 26, 'I will make them and the places around my hill a blessing; and I will cause the shower to come down in its season; there shall be showers of blessing.'),
  ('4feb142a-4f1c-52fa-af69-3e37d125faa5', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 27, 27, 'The tree of the field shall yield its fruit, and the earth shall yield its increase, and they shall be secure in their land; and they shall know that I am Yahweh, when I have broken the bars of their yoke, and have delivered them out of the hand of those who made slaves of them.'),
  ('39b8ed62-86d0-5bca-a745-d46d1b6d6d33', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 28, 28, 'They shall no more be a prey to the nations, neither shall the animals of the earth devour them; but they shall dwell securely, and none shall make them afraid.'),
  ('03804e05-7a32-521f-a863-8226999432fa', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 29, 29, 'I will raise up to them a plantation for renown, and they shall be no more consumed with famine in the land, neither bear the shame of the nations any more.'),
  ('6a6579fd-7f17-5f41-aeec-50a5a869ad55', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 30, 30, 'They shall know that I, Yahweh, their God am with them, and that they, the house of Israel, are my people, says the Lord Yahweh.'),
  ('3287d473-bf2d-50d7-a20e-51c42ff26f00', '323d5c8d-4eae-52ac-ac48-edf4f790d510', NULL, 31, 31, 'You my sheep, the sheep of my pasture, are men, and I am your God, says the Lord Yahweh.'),
  ('5c168927-5f7a-5843-a833-962b467449dc', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 1, 1, 'Moreover the word of Yahweh came to me, saying,'),
  ('d275cb1e-7cdb-5085-a274-62da4ec4b69c', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 2, 2, 'Son of man, set your face against Mount Seir, and prophesy against it,'),
  ('3c333008-1da5-530d-a04e-b7742644b0bb', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 3, 3, 'and tell it, Thus says the Lord Yahweh: Behold, I am against you, Mount Seir, and I will stretch out my hand against you, and I will make you a desolation and an astonishment.'),
  ('e92cc75b-ac57-529e-a979-4386bb9c3d2d', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 4, 4, 'I will lay your cities waste, and you shall be desolate; and you shall know that I am Yahweh.'),
  ('0ca4bfa5-274d-5773-ab3e-74c7c7644d1c', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 5, 5, 'Because you have had a perpetual enmity, and have given over the children of Israel to the power of the sword in the time of their calamity, in the time of the iniquity of the end;'),
  ('8e06bc85-4eb7-5407-a43d-091b5c9794ca', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 6, 6, 'therefore, as I live, says the Lord Yahweh, I will prepare you for blood, and blood shall pursue you: since you have not hated blood, therefore blood shall pursue you.'),
  ('c16a9627-afd2-5da5-aecd-02224d49627b', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 7, 7, 'Thus will I make Mount Seir an astonishment and a desolation; and I will cut off from it him who passes through and him who returns.'),
  ('258b19a0-288c-52b2-a623-797989273558', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 8, 8, 'I will fill its mountains with its slain: in your hills and in your valleys and in all your watercourses shall they fall who are slain with the sword.'),
  ('acba33ff-a24a-5a53-aa52-fd07a48bf0ee', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 9, 9, 'I will make you a perpetual desolation, and your cities shall not be inhabited; and you shall know that I am Yahweh.'),
  ('76010570-fc63-5851-a374-af16d42ed458', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 10, 10, 'Because you have said, These two nations and these two countries shall be mine, and we will possess it; whereas Yahweh was there:'),
  ('9bc2a035-c749-5b51-a649-6aa39b509b60', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 11, 11, 'therefore, as I live, says the Lord Yahweh, I will do according to your anger, and according to your envy which you have shown out of your hatred against them; and I will make myself known among them, when I shall judge you.'),
  ('05944c1a-b243-54f8-a83d-9d378277d210', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 12, 12, 'You shall know that I, Yahweh, have heard all your insults which you have spoken against the mountains of Israel, saying, They are laid desolate, they have been given us to devour.'),
  ('c601608c-f484-5152-a2a8-e3af9f457c7a', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 13, 13, 'You have magnified yourselves against me with your mouth, and have multiplied your words against me: I have heard it.'),
  ('3274ea39-5ab2-5d62-a276-4176a9ce3d91', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 14, 14, 'Thus says the Lord Yahweh: When the whole earth rejoices, I will make you desolate.'),
  ('ad66a36b-b63b-5812-adab-62f1ef9d65d7', '97522dc6-121a-53c4-a8d8-e3bb8ddfdaea', NULL, 15, 15, 'As you rejoiced over the inheritance of the house of Israel, because it was desolate, so will I do to you: you shall be desolate, Mount Seir, and all Edom, even all of it; and they shall know that I am Yahweh.'),
  ('388039ec-8fa5-5374-aa2c-c10d509565aa', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 1, 1, 'You, son of man, prophesy to the mountains of Israel, and say, You mountains of Israel, hear the word of Yahweh.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('f2765edf-4a4d-5e4a-abad-9d40de265285', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 2, 2, 'Thus says the Lord Yahweh: Because the enemy has said against you, Aha! and, The ancient high places are ours in possession;'),
  ('375fe274-46f2-57df-a81d-9e8a8fd1bfb9', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 3, 3, 'therefore prophesy, and say, Thus says the Lord Yahweh: Because, even because they have made you desolate, and swallowed you up on every side, that you might be a possession to the residue of the nations, and you are taken up in the lips of talkers, and the evil report of the people;'),
  ('93e6023a-5621-5404-aa93-8d43120dd94d', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 4, 4, 'therefore, you mountains of Israel, hear the word of the Lord Yahweh: Thus says the Lord Yahweh to the mountains and to the hills, to the watercourses and to the valleys, to the desolate wastes and to the cities that are forsaken, which are become a prey and derision to the residue of the nations that are all around;'),
  ('beb40e94-4a7a-5073-a93a-1f67c222cc96', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 5, 5, 'therefore thus says the Lord Yahweh: Surely in the fire of my jealousy have I spoken against the residue of the nations, and against all Edom, that have appointed my land to themselves for a possession with the joy of all their heart, with despite of soul, to cast it out for a prey.'),
  ('73436aea-1aab-53ff-a5c8-92e2c25b7d9a', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 6, 6, 'Therefore prophesy concerning the land of Israel, and tell the mountains and to the hills, to the watercourses and to the valleys, Thus says the Lord Yahweh: Behold, I have spoken in my jealousy and in my wrath, because you have borne the shame of the nations:'),
  ('78d0cfb8-07b3-588f-a970-48fb20df12d2', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 7, 7, 'therefore thus says the Lord Yahweh: I have sworn, [saying], Surely the nations that are around you, they shall bear their shame.'),
  ('c69ea736-f511-5180-a262-a5554862d8bb', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 8, 8, 'But you, mountains of Israel, you shall shoot forth your branches, and yield your fruit to my people Israel; for they are at hand to come.'),
  ('b7acec05-f5f4-56d2-a429-f14ab80700b9', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 9, 9, 'For, behold, I am for you, and I will turn into you, and you shall be tilled and sown;'),
  ('153536c1-8d75-53aa-ad65-3ae94529357c', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 10, 10, 'and I will multiply men on you, all the house of Israel, even all of it; and the cities shall be inhabited, and the waste places shall be built;'),
  ('0b7df5dc-3843-5913-ab0e-da9a6255d6fd', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 11, 11, 'and I will multiply on you man and animal; and they shall increase and be fruitful; and I will cause you to be inhabited after your former estate, and will do better [to you] than at your beginnings: and you shall know that I am Yahweh.'),
  ('c659024c-17f4-5d28-aa79-833c6883bd87', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 12, 12, 'Yes, I will cause men to walk on you, even my people Israel; and they shall possess you, and you shall be their inheritance, and you shall no more henceforth bereave them of children.'),
  ('28ef9a55-a4db-555a-afc3-03960b0f6683', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 13, 13, 'Thus says the Lord Yahweh: Because they say to you, You are a devourer of men, and have been a bereaver of your nation;'),
  ('5ffd7de1-b6c5-5b7d-ace3-e37b88fa98be', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 14, 14, 'therefore you shall devour men no more, neither bereave your nation any more, says the Lord Yahweh;'),
  ('72f91207-88a5-5a0c-ae13-cbb37303369d', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 15, 15, 'neither will I let you hear any more the shame of the nations, neither shall you bear the reproach of the peoples any more, neither shall you cause your nation to stumble any more, says the Lord Yahweh.'),
  ('9efb352a-ebb0-50f9-af03-467a22a6e2b2', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 16, 16, 'Moreover the word of Yahweh came to me, saying,'),
  ('dde5c988-9e15-50f3-a673-a2ededcb1881', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 17, 17, 'Son of man, when the house of Israel lived in their own land, they defiled it by their way and by their doings: their way before me was as the uncleanness of a woman in her impurity.'),
  ('4dc8eb70-4db5-53bf-a77a-7275d60130f1', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 18, 18, 'Therefore I poured out my wrath on them for the blood which they had poured out on the land, and because they had defiled it with their idols;'),
  ('7dd37d35-f2d8-55ca-a888-6b1d867e3485', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 19, 19, 'and I scattered them among the nations, and they were dispersed through the countries: according to their way and according to their doings I judged them.'),
  ('04f5be53-82f9-520b-aae4-4883440a9c68', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 20, 20, 'When they came to the nations, where they went, they profaned my holy name; in that men said of them, These are the people of Yahweh, and are gone forth out of his land.'),
  ('83b94fa2-0a52-5ed3-a0bf-23bb18a4a788', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 21, 21, 'But I had respect for my holy name, which the house of Israel had profaned among the nations, where they went.'),
  ('8c2fd639-718a-5aaf-a7d4-1998f968858a', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 22, 22, 'Therefore tell the house of Israel, Thus says the Lord Yahweh: I don''t do [this] for your sake, house of Israel, but for my holy name, which you have profaned among the nations, where you went.'),
  ('9432b693-0a59-54e4-ab51-902cc05a79c4', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 23, 23, 'I will sanctify my great name, which has been profaned among the nations, which you have profaned in the midst of them; and the nations shall know that I am Yahweh, says the Lord Yahweh, when I shall be sanctified in you before their eyes.'),
  ('c131ba3c-c592-5eb9-ae25-0c76959137ef', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 24, 24, 'For I will take you from among the nations, and gather you out of all the countries, and will bring you into your own land.'),
  ('899118d9-4db1-5d85-acaa-16051ce793f4', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 25, 25, 'I will sprinkle clean water on you, and you shall be clean: from all your filthiness, and from all your idols, will I cleanse you.'),
  ('6fd6e2b5-b6f9-5a07-a184-004a0a286968', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 26, 26, 'I will also give you a new heart, and I will put a new spirit within you; and I will take away the stony heart out of your flesh, and I will give you a heart of flesh.'),
  ('46d4328f-3211-5fe7-a76a-00ccb35d1ea1', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 27, 27, 'I will put my Spirit within you, and cause you to walk in my statutes, and you shall keep my ordinances, and do them.'),
  ('e0c6f6e4-5ab0-53c3-a400-0a22fb2fce31', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 28, 28, 'You shall dwell in the land that I gave to your fathers; and you shall be my people, and I will be your God.'),
  ('ff2d91f5-e2d1-5c48-a1b7-273538167f30', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 29, 29, 'I will save you from all your uncleanness: and I will call for the grain, and will multiply it, and lay no famine on you.'),
  ('3189d724-0d33-5b3d-a89f-085ec93bc78a', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 30, 30, 'I will multiply the fruit of the tree, and the increase of the field, that you may receive no more the reproach of famine among the nations.'),
  ('f24342a8-09a7-5a99-ae2c-5eaa306a1475', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 31, 31, 'Then you shall remember your evil ways, and your doings that were not good; and you shall loathe yourselves in your own sight for your iniquities and for your abominations.'),
  ('7ffb4947-871e-5cc4-ae0e-1fac8420a76a', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 32, 32, 'Nor for your sake do I [this], says the Lord Yahweh, be it known to you: be ashamed and confounded for your ways, house of Israel.'),
  ('377a12b5-539d-5c29-aa4a-eb4344110c5a', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 33, 33, 'Thus says the Lord Yahweh: In the day that I cleanse you from all your iniquities, I will cause the cities to be inhabited, and the waste places shall be built.'),
  ('21879149-c5ca-555c-ab73-ab57273cad4e', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 34, 34, 'The land that was desolate shall be tilled, whereas it was a desolation in the sight of all who passed by.'),
  ('5b16a4f7-5084-5edf-a6c2-4719b6311614', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 35, 35, 'They shall say, This land that was desolate is become like the garden of Eden; and the waste and desolate and ruined cities are fortified and inhabited.'),
  ('1b696def-9a2e-5445-a9dc-ada8621c0726', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 36, 36, 'Then the nations that are left around you shall know that I, Yahweh, have built the ruined places, and planted that which was desolate: I, Yahweh, have spoken it, and I will do it.'),
  ('193dc28e-9b6f-5b8b-a752-dd31d20b48b2', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 37, 37, 'Thus says the Lord Yahweh: For this, moreover, will I be inquired of by the house of Israel, to do it for them: I will increase them with men like a flock.'),
  ('15b1160c-8a24-549f-a4ef-e64037db6346', 'a57e0294-9906-5f67-ab98-d04ebd777fea', NULL, 38, 38, 'As the flock for sacrifice, as the flock of Jerusalem in her appointed feasts, so shall the waste cities be filled with flocks of men; and they shall know that I am Yahweh.'),
  ('e360ffb0-5010-5822-af8c-2b8d0eb8db1c', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 1, 1, 'The hand of Yahweh was on me, and he brought me out in the Spirit of Yahweh, and set me down in the midst of the valley; and it was full of bones.'),
  ('df035081-df85-547b-a12f-52efa07257ee', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 2, 2, 'He caused me to pass by them all around: and behold, there were very many in the open valley; and behold, they were very dry.'),
  ('9ded6bea-606f-568f-adbd-5e9d4192fcfd', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 3, 3, 'He said to me, Son of man, can these bones live? I answered, Lord Yahweh, you know.'),
  ('39778d02-2400-54bb-a003-247e7a814f3b', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 4, 4, 'Again he said to me, Prophesy over these bones, and tell them, you dry bones, hear the word of Yahweh.'),
  ('97568762-89cc-50ef-a68f-0077c22119cc', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 5, 5, 'Thus says the Lord Yahweh to these bones: Behold, I will cause breath to enter into you, and you shall live.'),
  ('248652e2-3e27-5bf0-ac95-0257c87d36fd', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 6, 6, 'I will lay sinews on you, and will bring up flesh on you, and cover you with skin, and put breath in you, and you shall live; and you shall know that I am Yahweh.'),
  ('730bfab3-8dd1-5161-a11c-a2a19c53fb52', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 7, 7, 'So I prophesied as I was commanded: and as I prophesied, there was a noise, and behold, an earthquake; and the bones came together, bone to its bone.'),
  ('104f2088-a12a-553c-a461-ab241fdb650d', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 8, 8, 'I saw, and, behold, there were sinews on them, and flesh came up, and skin covered them above; but there was no breath in them.'),
  ('db075148-1942-5d32-a786-43a4c80ff640', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 9, 9, 'Then he said to me, Prophesy to the wind, prophesy, son of man, and tell the wind, Thus says the Lord Yahweh: Come from the four winds, breath, and breathe on these slain, that they may live.'),
  ('345e35dd-0663-506b-aa97-8e19d187fd58', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 10, 10, 'So I prophesied as he commanded me, and the breath came into them, and they lived, and stood up on their feet, an exceedingly great army.'),
  ('4cacf9ca-8a3b-5f90-a46c-eccfac32dad6', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 11, 11, 'Then he said to me, Son of man, these bones are the whole house of Israel: behold, they say, Our bones are dried up, and our hope is lost; we are clean cut off.'),
  ('1c79fdfd-2876-5b76-a228-d1a22d429dac', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 12, 12, 'Therefore prophesy, and tell them, Thus says the Lord Yahweh: Behold, I will open your graves, and cause you to come up out of your graves, my people; and I will bring you into the land of Israel.'),
  ('a390a407-c02b-56a7-a630-c42b85b1375b', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 13, 13, 'You shall know that I am Yahweh, when I have opened your graves, and caused you to come up out of your graves, my people.'),
  ('3c06a6b0-8d78-54a3-a0fa-3d765dec9732', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 14, 14, 'I will put my Spirit in you, and you shall live, and I will place you in your own land: and you shall know that I, Yahweh, have spoken it and performed it, says Yahweh.'),
  ('b6217fba-4a39-5621-a00b-1a1064956bb8', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 15, 15, 'The word of Yahweh came again to me, saying,'),
  ('bd457177-0742-5ec0-aa5d-2316e25eaefc', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 16, 16, 'You, son of man, take one stick, and write on it, For Judah, and for the children of Israel his companions: then take another stick, and write on it, For Joseph, the stick of Ephraim, and [for] all the house of Israel his companions:'),
  ('478507ea-0734-5bf1-aa5f-a3890a7e1b48', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 17, 17, 'and join them for you one to another into one stick, that they may become one in your hand.'),
  ('5dd6e9d8-bea4-59a7-af6d-7d5b8c052ff5', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 18, 18, 'When the children of your people shall speak to you, saying, Will you not show us what you mean by these?'),
  ('185efa56-adc4-5d8a-a29c-7da8bb034acb', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 19, 19, 'tell them, Thus says the Lord Yahweh: Behold, I will take the stick of Joseph, which is in the hand of Ephraim, and the tribes of Israel his companions; and I will put them with it, [even] with the stick of Judah, and make them one stick, and they shall be one in my hand.'),
  ('c4e49150-b6cc-5e52-a4fa-f1b4bfec2b88', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 20, 20, 'The sticks whereon you write shall be in your hand before their eyes.'),
  ('c250a403-0762-5f9d-af79-1377845b71a7', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 21, 21, 'Say to them, Thus says the Lord Yahweh: Behold, I will take the children of Israel from among the nations, where they are gone, and will gather them on every side, and bring them into their own land:'),
  ('90749847-f12e-50f1-ad59-10840a4337f4', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 22, 22, 'and I will make them one nation in the land, on the mountains of Israel; and one king shall be king to them all; and they shall be no more two nations, neither shall they be divided into two kingdoms any more at all;'),
  ('874e32da-6c75-56e6-a483-5c0e3eed6687', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 23, 23, 'neither shall they defile themselves any more with their idols, nor with their detestable things, nor with any of their transgressions; but I will save them out of all their dwelling places, in which they have sinned, and will cleanse them: so shall they be my people, and I will be their God.'),
  ('3ac6c681-d3e2-51cc-a4c6-364523992e12', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 24, 24, 'My servant David shall be king over them; and they all shall have one shepherd: they shall also walk in my ordinances, and observe my statutes, and do them.'),
  ('c21e726d-1f42-54e3-a99b-2f13c6274af8', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 25, 25, 'They shall dwell in the land that I have given to Jacob my servant, in which your fathers lived; and they shall dwell therein, they, and their children, and their children''s children, forever: and David my servant shall be their prince for ever.'),
  ('3a3a53b1-dacf-5a91-a212-acec4f7139fa', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 26, 26, 'Moreover I will make a covenant of peace with them; it shall be an everlasting covenant with them; and I will place them, and multiply them, and will set my sanctuary in the midst of them forevermore.'),
  ('008f6716-c3af-54ad-a1a8-6ceb27322800', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 27, 27, 'My tent also shall be with them; and I will be their God, and they shall be my people.'),
  ('4a137ce0-25fe-5f3c-a976-9943d254e631', '25e87c74-83c7-58fc-a1a7-806e38c6f5a9', NULL, 28, 28, 'The nations shall know that I am Yahweh who sanctifies Israel, when my sanctuary shall be in the midst of them forevermore.'),
  ('e21a417e-e89f-51c6-a747-d3ec5109fa92', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 1, 1, 'The word of Yahweh came to me, saying,'),
  ('be4197f9-4946-5ec0-ae6e-b8e4020ae909', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 2, 2, 'Son of man, set your face toward Gog, of the land of Magog, the prince of Rosh, Meshech, and Tubal, and prophesy against him,'),
  ('e3eaec01-0372-5a0e-a792-2dbf2f362047', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 3, 3, 'and say, Thus says the Lord Yahweh: Behold, I am against you, Gog, prince of Rosh, Meshech, and Tubal:'),
  ('69a1f550-a805-5947-a9a5-52f8cf1dd592', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 4, 4, 'and I will turn you around, and put hooks into your jaws, and I will bring you forth, with all your army, horses and horsemen, all of them clothed in full armor, a great company with buckler and shield, all of them handling swords;'),
  ('c70e32a9-847a-557f-ada8-7d1c874e56b7', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 5, 5, 'Persia, Cush, and Put with them, all of them with shield and helmet;'),
  ('6567f332-127d-5c41-a95d-db9931bc5057', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 6, 6, 'Gomer, and all his hordes; the house of Togarmah in the uttermost parts of the north, and all his hordes; even many peoples with you.'),
  ('75e98ee6-c6c7-5a84-a632-1323ff796621', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 7, 7, 'Be prepared, yes, prepare yourself, you, and all your companies who are assembled to you, and be a guard to them.'),
  ('9da846e8-a0f4-570a-a4a1-47c107a18bad', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 8, 8, 'After many days you shall be visited: in the latter years you shall come into the land that is brought back from the sword, that is gathered out of many peoples, on the mountains of Israel, which have been a continual waste; but it is brought forth out of the peoples, and they shall dwell securely, all of them.'),
  ('5ccfa900-6825-5c5d-aa38-d3c0ce42b995', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 9, 9, 'You shall ascend, you shall come like a storm, you shall be like a cloud to cover the land, you, and all your hordes, and many peoples with you.'),
  ('4b9bec56-c20b-5eff-a6c5-7efc683eb3d9', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 10, 10, 'Thus says the Lord Yahweh: It shall happen in that day, that things shall come into your mind, and you shall devise an evil device:'),
  ('5a46ed8d-2d1b-5f2c-acd7-5967f0a372af', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 11, 11, 'and you shall say, I will go up to the land of unwalled villages; I will go to those who are at rest, who dwell securely, all of them dwelling without walls, and having neither bars nor gates;'),
  ('a0169f54-b586-5371-a928-f86582a86e2b', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 12, 12, 'to take the spoil and to take the prey; to turn your hand against the waste places that are [now] inhabited, and against the people who are gathered out of the nations, who have gotten livestock and goods, who dwell in the middle of the earth.'),
  ('4581ad7f-e631-5c01-a7d2-fb1e5f72fbad', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 13, 13, 'Sheba, and Dedan, and the merchants of Tarshish, with all the young lions of it, shall tell you, Have you come to take the spoil? have you assembled your company to take the prey? to carry away silver and gold, to take away livestock and goods, to take great spoil?'),
  ('66b9d97f-ad84-567f-ac34-cc3e4b183af0', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 14, 14, 'Therefore, son of man, prophesy, and tell Gog, Thus says the Lord Yahweh: In that day when my people Israel dwells securely, shall you not know it?'),
  ('fb31a0d3-e0af-5d5d-a9f8-051e3340cbfe', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 15, 15, 'You shall come from your place out of the uttermost parts of the north, you, and many peoples with you, all of them riding on horses, a great company and a mighty army;'),
  ('597b54e4-57f3-544a-a354-a1fefa4db98b', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 16, 16, 'and you shall come up against my people Israel, as a cloud to cover the land: it shall happen in the latter days, that I will bring you against my land, that the nations may know me, when I shall be sanctified in you, Gog, before their eyes.'),
  ('064d6bd6-f37d-522c-a8df-d15b85587fe4', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 17, 17, 'Thus says the Lord Yahweh: Are you he of whom I spoke in old time by my servants the prophets of Israel, who prophesied in those days for [many] years that I would bring you against them?'),
  ('8dedf7f0-4224-5689-a354-b8623519aa9e', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 18, 18, 'It shall happen in that day, when Gog shall come against the land of Israel, says the Lord Yahweh, that my wrath shall come up into my nostrils.'),
  ('71acca42-2b51-52c0-a7b8-3a6f6864c2b7', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 19, 19, 'For in my jealousy and in the fire of my wrath have I spoken, Surely in that day there shall be a great shaking in the land of Israel;'),
  ('52516172-70d8-5577-a072-e7943a089b98', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 20, 20, 'so that the fish of the sea, and the birds of the sky, and the animals of the field, and all creeping things who creep on the earth, and all the men who are on the surface of the earth, shall shake at my presence, and the mountains shall be thrown down, and the steep places shall fall, and every wall shall fall to the ground.'),
  ('39eb4043-08ab-510a-a4e4-90471ac87ff4', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 21, 21, 'I will call for a sword against him to all my mountains, says the Lord Yahweh: every man''s sword shall be against his brother.'),
  ('2971f92c-8818-54f5-a173-a4b38d4b4e3f', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 22, 22, 'With pestilence and with blood will I enter into judgment with him; and I will rain on him, and on his hordes, and on the many peoples who are with him, an overflowing shower, and great hailstones, fire, and sulfur.'),
  ('872f0470-80bb-5e85-a6fd-294fb43a9056', '556ea9ee-e4ac-5de0-a39e-2b3ba62715ab', NULL, 23, 23, 'I will magnify myself, and sanctify myself, and I will make myself known in the eyes of many nations; and they shall know that I am Yahweh.'),
  ('38925e70-912f-55ec-a9b5-493ae89a173e', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 1, 1, 'You, son of man, prophesy against Gog, and say, Thus says the Lord Yahweh: Behold, I am against you, Gog, prince of Rosh, Meshech, and Tubal:'),
  ('7566d418-27be-5371-ab0b-7a1fbe7ee235', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 2, 2, 'and I will turn you around, and will lead you on, and will cause you to come up from the uttermost parts of the north; and I will bring you on the mountains of Israel;'),
  ('96c097b4-cac6-5a1b-abc6-5eb92fa0d02a', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 3, 3, 'and I will strike your bow out of your left hand, and will cause your arrows to fall out of your right hand.'),
  ('e73fddff-259b-5be0-ae4e-c9fc0d23384f', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 4, 4, 'You shall fall on the mountains of Israel, you, and all your hordes, and the peoples who are with you: I will give you to the ravenous birds of every sort, and to the animals of the field to be devoured.'),
  ('d5b007b8-4217-5b7e-a8ab-34eb27faa84c', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 5, 5, 'You shall fall on the open field; for I have spoken it, says the Lord Yahweh.'),
  ('698888ae-fa53-5278-a6ee-c6228424e255', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 6, 6, 'I will send a fire on Magog, and on those who dwell securely in the islands; and they shall know that I am Yahweh.'),
  ('cc1b92f7-dcaf-55ab-a64f-c113bbaad748', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 7, 7, 'My holy name will I make known in the midst of my people Israel; neither will I allow my holy name to be profaned any more: and the nations shall know that I am Yahweh, the Holy One in Israel.'),
  ('a1e84d7e-c537-595e-a9aa-913decdf7921', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 8, 8, 'Behold, it comes, and it shall be done, says the Lord Yahweh; this is the day about which I have spoken.'),
  ('49f4ee48-ae30-5294-a45d-37618f01aeb6', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 9, 9, 'Those who dwell in the cities of Israel shall go forth, and shall make fires of the weapons and burn them, both the shields and the bucklers, the bows and the arrows, and the war clubs, and the spears, and they shall make fires of them seven years;'),
  ('f68e079c-92dc-5b1d-a2e2-435d690db6ff', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 10, 10, 'so that they shall take no wood out of the field, neither cut down any out of the forests; for they shall make fires of the weapons; and they shall plunder those who plundered them, and rob those who robbed them, says the Lord Yahweh.'),
  ('bb965d2d-d8dc-532c-ab95-b5406d2b5a84', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 11, 11, 'It shall happen in that day, that I will give to Gog a place for burial in Israel, the valley of those who pass through on the east of the sea; and it shall stop those who pass through: and there shall they bury Gog and all his multitude; and they shall call it The valley of Hamon Gog.'),
  ('ed2d234f-e71f-50de-a754-216ac1a07ce7', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 12, 12, 'Seven months shall the house of Israel be burying them, that they may cleanse the land.'),
  ('48b24ad2-9236-56c6-a572-8e63d4b44578', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 13, 13, 'Yes, all the people of the land shall bury them; and it shall be to them a renown in the day that I shall be glorified, says the Lord Yahweh.'),
  ('89e9e8a0-dd35-5d40-a648-1169ebddba3d', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 14, 14, 'They shall set apart men of continual employment, who shall pass through the land, and, with those who pass through, those who bury those who remain on the surface of the land, to cleanse it: after the end of seven months shall they search.'),
  ('8694cce9-8f4f-5541-ae2e-e98bc24c0499', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 15, 15, 'Those who pass through the land shall pass through; and when any sees a man''s bone, then shall he set up a sign by it, until the undertakers have buried it in the valley of Hamon Gog.'),
  ('c8ef8342-a3a0-5a81-a5fd-ebc59fd1e6ba', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 16, 16, 'Hamonah shall also be the name of a city. Thus shall they cleanse the land.'),
  ('d027335d-895c-52b1-a3bc-e8670942330c', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 17, 17, 'You, son of man, thus says the Lord Yahweh: Speak to the birds of every sort, and to every animal of the field, Assemble yourselves, and come; gather yourselves on every side to my sacrifice that I do sacrifice for you, even a great sacrifice on the mountains of Israel, that you may eat flesh and drink blood.'),
  ('b4080462-d64b-5e7b-a375-15a6b149dfb5', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 18, 18, 'You shall eat the flesh of the mighty, and drink the blood of the princes of the earth, of rams, of lambs, and of goats, of bulls, all of them fatlings of Bashan.'),
  ('6d276462-9583-55dc-aae9-91179a9bc2bd', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 19, 19, 'You shall eat fat until you be full, and drink blood until you are drunk, of my sacrifice which I have sacrificed for you.'),
  ('1b2fd7f8-5a88-54fd-aa02-922de332d960', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 20, 20, 'You shall be filled at my table with horses and chariots, with mighty men, and with all men of war, says the Lord Yahweh.'),
  ('a49cdec6-9ec5-596b-aaa5-a3e8ce43a23f', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 21, 21, 'I will set my glory among the nations; and all the nations shall see my judgment that I have executed, and my hand that I have laid on them.'),
  ('29b1bd17-d224-5a7e-a137-c6530c0ab900', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 22, 22, 'So the house of Israel shall know that I am Yahweh their God, from that day and forward.'),
  ('9e3bbe96-c69a-566f-a885-8ae3ae9859b7', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 23, 23, 'The nations shall know that the house of Israel went into captivity for their iniquity; because they trespassed against me, and I hid my face from them: so I gave them into the hand of their adversaries, and they fell all of them by the sword.'),
  ('c437f150-a699-5e59-aba6-96d9f78fe12b', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 24, 24, 'According to their uncleanness and according to their transgressions did I to them; and I hid my face from them.'),
  ('3676751a-7b80-5b9b-ae0f-a5b5b0718723', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 25, 25, 'Therefore thus says the Lord Yahweh: Now will I bring back the captivity of Jacob, and have mercy on the whole house of Israel; and I will be jealous for my holy name.'),
  ('c188ba00-db9e-569c-a931-39a2db3baa6a', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 26, 26, 'They shall bear their shame, and all their trespasses by which they have trespassed against me, when they shall dwell securely in their land, and none shall make them afraid;'),
  ('aa5ef2cc-741f-58ce-a36c-f28ea2eb8ff5', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 27, 27, 'when I have brought them back from the peoples, and gathered them out of their enemies'' lands, and am sanctified in them in the sight of many nations.'),
  ('de2c4b65-4d34-5546-a1ae-65dba5f53e95', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 28, 28, 'They shall know that I am Yahweh their God, in that I caused them to go into captivity among the nations, and have gathered them to their own land; and I will leave none of them any more there;'),
  ('47b8385d-c431-5bee-abf0-f75c4d03da71', '9c822701-1e67-5d55-a594-0615df7438fc', NULL, 29, 29, 'neither will I hide my face any more from them; for I have poured out my Spirit on the house of Israel, says the Lord Yahweh.'),
  ('ae89ba83-056c-56d2-a97e-046be2898bfb', '16f81810-abbc-5735-a53a-b33629874090', NULL, 1, 1, 'In the five and twentieth year of our captivity, in the beginning of the year, in the tenth [day] of the month, in the fourteenth year after that the city was struck, in the same day, the hand of Yahweh was on me, and he brought me there.'),
  ('ef9442a4-9e88-56c6-a93c-233087fa1537', '16f81810-abbc-5735-a53a-b33629874090', NULL, 2, 2, 'In the visions of God brought he me into the land of Israel, and set me down on a very high mountain, whereon was as it were the frame of a city on the south.'),
  ('ce463517-e983-5d70-a1ea-fc763fd07139', '16f81810-abbc-5735-a53a-b33629874090', NULL, 3, 3, 'He brought me there; and, behold, there was a man, whose appearance was like the appearance of brass, with a line of flax in his hand, and a measuring reed; and he stood in the gate.'),
  ('ffd62b2d-3664-5250-a9a5-6bbec754882e', '16f81810-abbc-5735-a53a-b33629874090', NULL, 4, 4, 'The man said to me, Son of man, see with your eyes, and hear with your ears, and set your heart on all that I shall show you; for, to the intent that I may show them to you, you are brought here: declare all that you see to the house of Israel.'),
  ('3cb16d64-172d-5904-a883-1cab3669dd41', '16f81810-abbc-5735-a53a-b33629874090', NULL, 5, 5, 'Behold, a wall on the outside of the house all around, and in the man''s hand a measuring reed six cubits long, of a cubit and a handbreadth each: so he measured the thickness of the building, one reed; and the height, one reed.'),
  ('0e8d1ac7-6b77-5a5c-a4c1-e3ba46cec35d', '16f81810-abbc-5735-a53a-b33629874090', NULL, 6, 6, 'Then came he to the gate which looks toward the east, and went up its steps: and he measured the threshold of the gate, one reed broad; and the other threshold, one reed broad.'),
  ('03376028-98ce-5178-a7e0-8333e3f53196', '16f81810-abbc-5735-a53a-b33629874090', NULL, 7, 7, 'Every lodge was one reed long, and one reed broad; and [the space] between the lodges was five cubits; and the threshold of the gate by the porch of the gate toward the house was one reed.'),
  ('73490ecc-7d0c-5e17-a914-7ac37bb41b8a', '16f81810-abbc-5735-a53a-b33629874090', NULL, 8, 8, 'He measured also the porch of the gate toward the house, one reed.'),
  ('cccb6cbc-ea67-5136-ad24-4a607716cae5', '16f81810-abbc-5735-a53a-b33629874090', NULL, 9, 9, 'Then measured he the porch of the gate, eight cubits; and its posts, two cubits; and the porch of the gate was toward the house.'),
  ('39becb46-f651-57b0-abce-4494f7160ca8', '16f81810-abbc-5735-a53a-b33629874090', NULL, 10, 10, 'The lodges of the gate eastward were three on this side, and three on that side; they three were of one measure: and the posts had one measure on this side and on that side.'),
  ('3e4e20d7-e7ee-5c14-ad7b-4559490e0327', '16f81810-abbc-5735-a53a-b33629874090', NULL, 11, 11, 'He measured the breadth of the opening of the gate, ten cubits; and the length of the gate, thirteen cubits;'),
  ('24ca1dba-05f1-5871-a7e6-a3d8654d2bed', '16f81810-abbc-5735-a53a-b33629874090', NULL, 12, 12, 'and a border before the lodges, one cubit [on this side], and a border, one cubit on that side; and the lodges, six cubits on this side, and six cubits on that side.'),
  ('80e0672d-003d-517f-ac2b-8b27974e9ef2', '16f81810-abbc-5735-a53a-b33629874090', NULL, 13, 13, 'He measured the gate from the roof of the one lodge to the roof of the other, a breadth of twenty-five cubits; door against door.'),
  ('80610888-2207-536e-ad1a-5866e0774073', '16f81810-abbc-5735-a53a-b33629874090', NULL, 14, 14, 'He made also posts, sixty cubits; and the court [reached] to the posts, around the gate.'),
  ('f640cecd-e605-5322-a3b9-3c0ca5bf20fb', '16f81810-abbc-5735-a53a-b33629874090', NULL, 15, 15, '[From] the forefront of the gate at the entrance to the forefront of the inner porch of the gate were fifty cubits.'),
  ('98629a1f-85b8-5926-ac30-f9a089b7af9f', '16f81810-abbc-5735-a53a-b33629874090', NULL, 16, 16, 'There were closed windows to the lodges, and to their posts within the gate all around, and likewise to the arches; and windows were around inward; and on [each] post were palm trees.'),
  ('600787c0-b2da-557e-a938-c3bf68c8e25b', '16f81810-abbc-5735-a53a-b33629874090', NULL, 17, 17, 'Then brought he me into the outer court; and behold, there were rooms and a pavement, made for the court all around: thirty rooms were on the pavement.'),
  ('3ec8af72-dbf2-527a-a315-3ac768fff60e', '16f81810-abbc-5735-a53a-b33629874090', NULL, 18, 18, 'The pavement was by the side of the gates, answerable to the length of the gates, even the lower pavement.'),
  ('31a9baa3-400b-5bbf-aa40-8583717dc327', '16f81810-abbc-5735-a53a-b33629874090', NULL, 19, 19, 'Then he measured the breadth from the forefront of the lower gate to the forefront of the inner court outside, one hundred cubits, [both] on the east and on the north.'),
  ('3fc56114-fd09-5067-ac50-0649dd0d7bd6', '16f81810-abbc-5735-a53a-b33629874090', NULL, 20, 20, 'The gate of the outer court whose prospect is toward the north, he measured its length and its breadth.'),
  ('7780e613-fdf6-5a01-a18d-712500a4095f', '16f81810-abbc-5735-a53a-b33629874090', NULL, 21, 21, 'The lodges of it were three on this side and three on that side; and its posts and its arches were after the measure of the first gate: its length was fifty cubits, and the breadth twenty-five cubits.'),
  ('233c4036-6971-5b19-a620-a955270e4d18', '16f81810-abbc-5735-a53a-b33629874090', NULL, 22, 22, 'The windows of it, and its arches, and the palm trees of it, were after the measure of the gate whose prospect is toward the east; and they went up to it by seven steps; and its arches were before them.'),
  ('fee53ea9-639b-594b-aca1-faea74782ec4', '16f81810-abbc-5735-a53a-b33629874090', NULL, 23, 23, 'There was a gate to the inner court over against the [other] gate, [both] on the north and on the east; and he measured from gate to gate one hundred cubits.'),
  ('e946d613-c0f0-5289-a36b-5eee283a9829', '16f81810-abbc-5735-a53a-b33629874090', NULL, 24, 24, 'He led me toward the south; and behold, a gate toward the south: and he measured its posts and its arches according to these measures.'),
  ('45e13d3c-058d-5340-ac78-acf2129b6269', '16f81810-abbc-5735-a53a-b33629874090', NULL, 25, 25, 'There were windows in it and in its arches all around, like those windows: the length was fifty cubits, and the breadth twenty-five cubits.'),
  ('21ec9088-35e4-5a84-ade6-1a7da5ec0a61', '16f81810-abbc-5735-a53a-b33629874090', NULL, 26, 26, 'There were seven steps to go up to it, and its arches were before them; and it had palm trees, one on this side, and another on that side, on its posts.'),
  ('6dc1ebda-5420-571c-a734-5258eaef5002', '16f81810-abbc-5735-a53a-b33629874090', NULL, 27, 27, 'There was a gate to the inner court toward the south: and he measured from gate to gate toward the south a hundred cubits.'),
  ('8b4b2174-5e72-5891-a0b8-b0662729f419', '16f81810-abbc-5735-a53a-b33629874090', NULL, 28, 28, 'Then he brought me to the inner court by the south gate: and he measured the south gate according to these measures;'),
  ('2da340e0-11e5-5a78-a991-f2b77a958bc4', '16f81810-abbc-5735-a53a-b33629874090', NULL, 29, 29, 'and its lodges, and its posts, and its arches, according to these measures: and there were windows in it and in its arches all around; it was fifty cubits long, and twenty-five cubits broad.'),
  ('df9cfe58-1671-5adc-a263-b7a4403ca975', '16f81810-abbc-5735-a53a-b33629874090', NULL, 30, 30, 'There were arches all around, twenty-five cubits long, and five cubits broad.'),
  ('0c3c8653-e1ba-518c-a053-0efdaff8b180', '16f81810-abbc-5735-a53a-b33629874090', NULL, 31, 31, 'The arches of it were toward the outer court; and palm trees were on its posts: and the ascent to it had eight steps.'),
  ('401c8fe9-5956-56f0-aba6-49e4162a6741', '16f81810-abbc-5735-a53a-b33629874090', NULL, 32, 32, 'He brought me into the inner court toward the east: and he measured the gate according to these measures;'),
  ('7e3f6118-1296-50a4-ad40-ee0db8074fd3', '16f81810-abbc-5735-a53a-b33629874090', NULL, 33, 33, 'and its lodges, and its posts, and its arches, according to these measures: and there were windows therein and in its arches all around; it was fifty cubits long, and twenty-five cubits broad.'),
  ('855e4142-6b8a-5fe1-a3f9-cfe98b6761d0', '16f81810-abbc-5735-a53a-b33629874090', NULL, 34, 34, 'The arches of it were toward the outer court; and palm trees were on its posts, on this side, and on that side: and the ascent to it had eight steps.'),
  ('d74571df-7869-5868-a9ff-20875f0eaafb', '16f81810-abbc-5735-a53a-b33629874090', NULL, 35, 35, 'He brought me to the north gate: and he measured [it] according to these measures;'),
  ('4c78bf37-e4f8-5aaf-a8c8-d4975357b98f', '16f81810-abbc-5735-a53a-b33629874090', NULL, 36, 36, 'its lodges, its posts, and its arches: and there were windows therein all around; the length was fifty cubits, and the breadth twenty-five cubits.'),
  ('1aad49ea-172e-5768-a8af-0cd121c8f4a2', '16f81810-abbc-5735-a53a-b33629874090', NULL, 37, 37, 'The posts of it were toward the outer court; and palm trees were on its posts, on this side, and on that side: and the ascent to it had eight steps.'),
  ('4b05b15f-df60-59fb-aa36-39a20432d2bd', '16f81810-abbc-5735-a53a-b33629874090', NULL, 38, 38, 'A room with its door was by the posts at the gates; there they washed the burnt offering.'),
  ('75de196d-37cd-5801-a7fb-0d011ddc85c0', '16f81810-abbc-5735-a53a-b33629874090', NULL, 39, 39, 'In the porch of the gate were two tables on this side, and two tables on that side, to kill thereon the burnt offering and the sin offering and the trespass offering.'),
  ('ba35c2fb-2b8d-5ac3-a829-a00bcd291cb5', '16f81810-abbc-5735-a53a-b33629874090', NULL, 40, 40, 'On the [one] side outside, as one goes up to the entry of the gate toward the north, were two tables; and on the other side, which belonged to the porch of the gate, were two tables.'),
  ('e986011a-6223-55f9-a80f-0517be9ccd48', '16f81810-abbc-5735-a53a-b33629874090', NULL, 41, 41, 'Four tables were on this side, and four tables on that side, by the side of the gate; eight tables, whereupon they killed [the sacrifices].'),
  ('81171815-dca8-5b9f-a8db-87d0e41b86c4', '16f81810-abbc-5735-a53a-b33629874090', NULL, 42, 42, 'There were four tables for the burnt offering, of cut stone, a cubit and a half long, and a cubit and a half broad, and one cubit high; whereupon they laid the instruments with which they killed the burnt offering and the sacrifice.'),
  ('d8b657c3-d84d-5385-aef8-7795c1197ef4', '16f81810-abbc-5735-a53a-b33629874090', NULL, 43, 43, 'The hooks, a handbreadth long, were fastened within all around: and on the tables was the flesh of the offering.'),
  ('b5ef3b6b-52e1-538a-abf8-bdecfacbda95', '16f81810-abbc-5735-a53a-b33629874090', NULL, 44, 44, 'Outside of the inner gate were rooms for the singers in the inner court, which was at the side of the north gate; and their prospect was toward the south; one at the side of the east gate having the prospect toward the north.'),
  ('7c541a31-ebb9-51eb-ae04-db04cee3c44a', '16f81810-abbc-5735-a53a-b33629874090', NULL, 45, 45, 'He said to me, This room, whose prospect is toward the south, is for the priests, the keepers of the duty of the house;'),
  ('3db40c43-790b-5c75-ab04-ee28c9b7e657', '16f81810-abbc-5735-a53a-b33629874090', NULL, 46, 46, 'and the room whose prospect is toward the north is for the priests, the keepers of the duty of the altar: these are the sons of Zadok, who from among the sons of Levi come near to Yahweh to minister to him.'),
  ('e0da3467-e941-586a-af69-d3b78321eddd', '16f81810-abbc-5735-a53a-b33629874090', NULL, 47, 47, 'He measured the court, one hundred cubits long, and a hundred cubits broad, foursquare; and the altar was before the house.'),
  ('df34136f-f72d-502d-ab75-05e821035a79', '16f81810-abbc-5735-a53a-b33629874090', NULL, 48, 48, 'Then he brought me to the porch of the house, and measured each post of the porch, five cubits on this side, and five cubits on that side: and the breadth of the gate was three cubits on this side, and three cubits on that side.'),
  ('c543490d-a0cf-59a0-a589-99a103fc9cec', '16f81810-abbc-5735-a53a-b33629874090', NULL, 49, 49, 'The length of the porch was twenty cubits, and the breadth eleven cubits; even by the steps by which they went up to it: and there were pillars by the posts, one on this side, and another on that side.'),
  ('05838d2a-a07a-5145-a65e-887dba226286', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 1, 1, 'He brought me to the temple, and measured the posts, six cubits broad on the one side, and six cubits broad on the other side, which was the breadth of the tent.'),
  ('0ee36a07-8175-5f55-abad-50171d70e9a4', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 2, 2, 'The breadth of the entrance was ten cubits; and the sides of the entrance were five cubits on the one side, and five cubits on the other side: and he measured its length, forty cubits, and the breadth, twenty cubits.'),
  ('317d482f-05cd-5085-a2ae-19941fd9845c', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 3, 3, 'Then went he inward, and measured each post of the entrance, two cubits; and the entrance, six cubits; and the breadth of the entrance, seven cubits.'),
  ('a33748cd-0bfe-501d-a57e-0a7e9c0175b0', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 4, 4, 'He measured its length, twenty cubits, and the breadth, twenty cubits, before the temple: and he said to me, This is the most holy place.'),
  ('7756f0c2-ba1d-569e-ac0c-2127460ed81f', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 5, 5, 'Then he measured the wall of the house, six cubits; and the breadth of every side room, four cubits, all around the house on every side.'),
  ('02f4e99d-b9c9-5848-a272-617d72bff682', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 6, 6, 'The side rooms were in three stories, one over another, and thirty in order; and they entered into the wall which belonged to the house for the side rooms all around, that they might have hold [therein], and not have hold in the wall of the house.'),
  ('46b0934f-fb3a-5247-aad7-3d3d4dcd90b5', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 7, 7, 'The side rooms were broader as they encompassed [the house] higher and higher; for the encompassing of the house went higher and higher around the house: therefore the breadth of the house [continued] upward; and so one went up [from] the lowest [room] to the highest by the middle [room].'),
  ('23d6e857-9c37-5085-a9d3-e2fe286b0696', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 8, 8, 'I saw also that the house had a raised base all around: the foundations of the side rooms were a full reed of six great cubits.'),
  ('d3683a7a-9f09-588e-af5e-66ac3cfe9bf0', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 9, 9, 'The thickness of the wall, which was for the side rooms, on the outside, was five cubits: and that which was left was the place of the side rooms that belonged to the house.'),
  ('5c40a226-c13b-58b8-a321-b1734b5998f5', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 10, 10, 'Between the rooms was a breadth of twenty cubits around the house on every side.'),
  ('5231d8d9-2a28-5694-ad69-0f2174f74972', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 11, 11, 'The doors of the side rooms were toward [the place] that was left, one door toward the north, and another door toward the south: and the breadth of the place that was left was five cubits all around.'),
  ('8dd0b94d-5b2c-543f-ae01-6823536bdd37', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 12, 12, 'The building that was before the separate place at the side toward the west was seventy cubits broad; and the wall of the building was five cubits thick all around, and its length ninety cubits.'),
  ('af3f6d00-c450-5031-ad1b-34bad10f2f9b', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 13, 13, 'So he measured the house, one hundred cubits long; and the separate place, and the building, with its walls, one hundred cubits long;'),
  ('a7903d49-6818-5341-a0ab-26091f331fd8', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 14, 14, 'also the breadth of the face of the house, and of the separate place toward the east, one hundred cubits.'),
  ('44955086-6705-5948-abad-8be278fefa9d', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 15, 15, 'He measured the length of the building before the separate place which was at its back, and its galleries on the one side and on the other side, one hundred cubits; and the inner temple, and the porches of the court;'),
  ('24eace5b-6aeb-587b-a819-764c8981fc64', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 16, 16, 'the thresholds, and the closed windows, and the galleries around on their three stories, over against the threshold, with wood ceilings all around, and [from] the ground up to the windows, (now the windows were covered),'),
  ('5ea7439e-d8ea-56b8-a4ea-2e5c187cb1f7', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 17, 17, 'to [the space] above the door, even to the inner house, and outside, and by all the wall all around inside and outside, by measure.'),
  ('77e4378e-8158-5f08-a3d2-dbb84dedcff6', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 18, 18, 'It was made with cherubim and palm trees; and a palm tree was between cherub and cherub, and every cherub had two faces;'),
  ('7f479297-6501-557a-a59d-7dc8d66a443c', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 19, 19, 'so that there was the face of a man toward the palm tree on the one side, and the face of a young lion toward the palm tree on the other side. [thus was it] made through all the house all around:'),
  ('026a1a60-5f54-5994-ab3e-af9ab5e5b72d', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 20, 20, 'from the ground to above the door were cherubim and palm trees made: thus was the wall of the temple.'),
  ('ab4e4783-bec7-562f-a843-530db33bfc72', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 21, 21, 'As for the temple, the door posts were squared; and as for the face of the sanctuary, the appearance [of it] was as the appearance [of the temple].'),
  ('18f8eef1-a2fb-5bd1-ab44-e32ed5e6c765', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 22, 22, 'The altar was of wood, three cubits high, and its length two cubits; and its corners, and its length, and its walls, were of wood: and he said to me, This is the table that is before Yahweh.'),
  ('68ed5519-9f31-5010-a254-3220e5fc7a69', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 23, 23, 'The temple and the sanctuary had two doors.'),
  ('4d4a2043-cde2-5078-affc-65328474fa29', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 24, 24, 'The doors had two leaves [apiece], two turning leaves: two [leaves] for the one door, and two leaves for the other.'),
  ('1d229c5d-138b-54e7-a0b1-763012563e9c', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 25, 25, 'There were made on them, on the doors of the temple, cherubim and palm trees, like as were made on the walls; and there was a threshold of wood on the face of the porch outside.'),
  ('5f76aec1-f601-5692-af0b-93449fc05083', '9ac0a290-27a7-5dd8-a453-339a93e844da', NULL, 26, 26, 'There were closed windows and palm trees on the one side and on the other side, on the sides of the porch: thus were the side rooms of the house, and the thresholds.'),
  ('94c9172b-578f-5606-a47d-a02deb501ab5', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 1, 1, 'Then he brought me forth into the outer court, the way toward the north: and he brought me into the room that was over against the separate place, and which was over against the building toward the north.'),
  ('55225638-bb63-5c07-a0fe-2a7e5c39bd30', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 2, 2, 'Before the length of one hundred cubits was the north door, and the breadth was fifty cubits.'),
  ('d4f83ece-2432-576a-a667-9ed9e24f87ed', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 3, 3, 'Over against the twenty [cubits] which belonged to the inner court, and over against the pavement which belonged to the outer court, was gallery against gallery in the third story.'),
  ('80fa16a6-d87b-5077-ae75-93f2b9b02573', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 4, 4, 'Before the rooms was a walk of ten cubits'' breadth inward, a way of one cubit; and their doors were toward the north.'),
  ('f18e1267-0000-5031-ac9c-88daee36a717', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 5, 5, 'Now the upper rooms were shorter; for the galleries took away from these, more than from the lower and the middle, in the building.'),
  ('876546de-f3f4-54d4-a186-0b067011820a', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 6, 6, 'For they were in three stories, and they didn''t have pillars as the pillars of the courts: therefore [the uppermost] was straitened more than the lowest and the middle from the ground.'),
  ('1ef08e07-aa16-56b2-a0ab-12d45ef44e80', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 7, 7, 'The wall that was outside by the side of the rooms, toward the outer court before the rooms, its length was fifty cubits.'),
  ('5f1202b1-6d3e-5989-a6ef-1341c239d895', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 8, 8, 'For the length of the rooms that were in the outer court was fifty cubits: and behold, before the temple were one hundred cubits.'),
  ('ef336f22-1587-5c9e-ab04-4d97d3bf3d8f', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 9, 9, 'From under these rooms was the entry on the east side, as one goes into them from the outer court.'),
  ('d462727e-b133-5ef2-a060-89ed9474b5fd', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 10, 10, 'In the thickness of the wall of the court toward the east, before the separate place, and before the building, there were rooms.'),
  ('befba273-656d-5895-a290-531ce5c539b9', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 11, 11, 'The way before them was like the appearance of [the way of] the rooms which were toward the north; according to their length so was their breadth: and all their exits were both according to their fashions, and according to their doors.'),
  ('21b2037b-d7a4-585e-aedd-a890de3d66b7', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 12, 12, 'According to the doors of the rooms that were toward the south was a door at the head of the way, even the way directly before the wall toward the east, as one enters into them.'),
  ('982823ee-5541-56fd-a9fe-917b090f2394', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 13, 13, 'Then he said to me, The north rooms and the south rooms, which are before the separate place, they are the holy rooms, where the priests who are near to Yahweh shall eat the most holy things: there shall they lay the most holy things, and the meal offering, and the sin offering, and the trespass offering; for the place is holy.'),
  ('dc4e6b8e-cdfc-5bfa-af89-f8200c3a01b4', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 14, 14, 'When the priests enter in, then shall they not go out of the holy place into the outer court, but there they shall lay their garments in which they minister; for they are holy: and they shall put on other garments, and shall approach to that which pertains to the people.'),
  ('92a76cd3-71d8-588a-a332-85890489c131', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 15, 15, 'Now when he had made an end of measuring the inner house, he brought me forth by the way of the gate whose prospect is toward the east, and measured it all around.'),
  ('86aa3845-967c-5a91-adf1-906062629788', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 16, 16, 'He measured on the east side with the measuring reed five hundred reeds, with the measuring reed all around.'),
  ('74a4aa0a-1136-5782-a0a0-c6f11171ae1d', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 17, 17, 'He measured on the north side five hundred reeds with the measuring reed all around.'),
  ('3675f0c1-9430-5ca1-a26a-e78bba5aa7d2', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 18, 18, 'He measured on the south side five hundred reeds with the measuring reed.'),
  ('ea59a034-ee37-5eac-a24f-72ffd8c62564', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 19, 19, 'He turned about to the west side, and measured five hundred reeds with the measuring reed.'),
  ('a8ab36d7-5fe8-50c4-a829-72ae3ef6b9ee', '32ceacad-c034-5ca0-aea3-beea0a228b9f', NULL, 20, 20, 'He measured it on the four sides: it had a wall around it, the length five hundred, and the breadth five hundred, to make a separation between that which was holy and that which was common.'),
  ('10951ed0-ca53-524e-ae5a-244408f5874e', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 1, 1, 'Afterward he brought me to the gate, even the gate that looks toward the east.'),
  ('4c869416-dca9-563f-a32a-40e387b19ea2', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 2, 2, 'Behold, the glory of the God of Israel came from the way of the east: and his voice was like the sound of many waters; and the earth shined with his glory.'),
  ('a6e65eb1-fceb-5d07-ae0a-a538527dca92', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 3, 3, 'It was according to the appearance of the vision which I saw, even according to the vision that I saw when I came to destroy the city; and the visions were like the vision that I saw by the river Chebar; and I fell on my face.'),
  ('95bf8a17-deb4-5a07-a50c-0fc99cb07bda', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 4, 4, 'The glory of Yahweh came into the house by the way of the gate whose prospect is toward the east.'),
  ('c7d79705-1571-5980-a8df-74aebcad97f3', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 5, 5, 'The Spirit took me up, and brought me into the inner court; and behold, the glory of Yahweh filled the house.'),
  ('de532c4d-0336-51c0-a828-738b448d0fe0', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 6, 6, 'I heard one speaking to me out of the house; and a man stood by me.'),
  ('c785063e-1168-5e93-a414-567c4e283a06', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 7, 7, 'He said to me, Son of man, [this is] the place of my throne, and the place of the soles of my feet, where I will dwell in the midst of the children of Israel forever. The house of Israel shall no more defile my holy name, neither they, nor their kings, by their prostitution, and by the dead bodies of their kings [in] their high places;'),
  ('e9759248-a866-55bd-a218-e1f5708f6762', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 8, 8, 'in their setting of their threshold by my threshold, and their doorpost beside my doorpost, and there was [but] the wall between me and them; and they have defiled my holy name by their abominations which they have committed: therefore I have consumed them in my anger.'),
  ('807228f6-576e-508b-a040-a7623506e396', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 9, 9, 'Now let them put away their prostitution, and the dead bodies of their kings, far from me; and I will dwell in the midst of them forever.'),
  ('dde93b36-0cc3-58b1-ae4c-07b39666f52d', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 10, 10, 'You, son of man, show the house to the house of Israel, that they may be ashamed of their iniquities; and let them measure the pattern.'),
  ('c2ef23ba-5000-57d5-ac67-b5a086773387', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 11, 11, 'If they be ashamed of all that they have done, make known to them the form of the house, and its fashion, and its exits, and its entrances, and all its forms, and all its ordinances, and all its forms, and all its laws; and write it in their sight; that they may keep the whole form of it, and all its ordinances, and do them.'),
  ('e9eba628-245f-5923-a1e1-005a5d87ba05', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 12, 12, 'This is the law of the house: on the top of the mountain the whole limit around it shall be most holy. Behold, this is the law of the house.'),
  ('ba95b65a-2bee-5fee-a8b3-da357a393080', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 13, 13, 'These are the measures of the altar by cubits (the cubit is a cubit and a handbreadth): the bottom shall be a cubit, and the breadth a cubit, and its border around its edge a span; and this shall be the base of the altar.'),
  ('8c47bdb5-d6b6-5329-af1d-dfb06a9dfbd9', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 14, 14, 'From the bottom on the ground to the lower ledge shall be two cubits, and the breadth one cubit; and from the lesser ledge to the greater ledge shall be four cubits, and the breadth a cubit.'),
  ('327e0e21-37ac-528f-a2e3-779ecf9aab67', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 15, 15, 'The upper altar shall be four cubits; and from the altar hearth and upward there shall be four horns.'),
  ('b3c637ba-7839-5184-a65b-10b219417650', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 16, 16, 'The altar hearth shall be twelve [cubits] long by twelve broad, square in the four sides of it.'),
  ('64c57b1e-56d2-55a1-af4b-41e1a5810766', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 17, 17, 'The ledge shall be fourteen [cubits] long by fourteen broad in the four sides of it; and the border about it shall be half a cubit; and its bottom shall be a cubit around; and its steps shall look toward the east.'),
  ('dde2112d-a3b5-56fb-aced-2c0a5e0b26a0', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 18, 18, 'He said to me, Son of man, thus says the Lord Yahweh: These are the ordinances of the altar in the day when they shall make it, to offer burnt offerings thereon, and to sprinkle blood thereon.'),
  ('f8c24d54-c288-5668-a38d-c09f67d0e260', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 19, 19, 'You shall give to the priests the Levites who are of the seed of Zadok, who are near to me, to minister to me, says the Lord Yahweh, a young bull for a sin offering.'),
  ('5cf05aab-2927-54fd-a6d3-b6f91e39f454', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 20, 20, 'You shall take of its blood, and put it on the four horns of it, and on the four corners of the ledge, and on the border all around: thus you shall cleanse it and make atonement for it.'),
  ('7fd23a31-09df-5399-ad8c-bc1aa028820e', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 21, 21, 'You shall also take the bull of the sin offering, and it shall be burnt in the appointed place of the house, outside of the sanctuary.'),
  ('ea57d1a4-c1b9-5fb7-ad8e-84cca8757ccf', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 22, 22, 'On the second day you shall offer a male goat without blemish for a sin offering; and they shall cleanse the altar, as they did cleanse it with the bull.'),
  ('bfc6bf5c-cb34-5e30-a2d2-80f56d24d01a', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 23, 23, 'When you have finished cleansing it, you shall offer a young bull without blemish, and a ram out of the flock without blemish.'),
  ('b8a8897b-6ebd-55e9-a49d-af18cd75a60a', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 24, 24, 'You shall bring them near to Yahweh, and the priests shall cast salt on them, and they shall offer them up for a burnt offering to Yahweh.'),
  ('1bcbdee4-1eba-5d2c-abe3-e2adcf62ccbe', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 25, 25, 'Seven days you shall prepare every day a goat for a sin offering: they shall also prepare a young bull, and a ram out of the flock, without blemish.'),
  ('6fb24a5c-f5e7-53f1-ad4f-94b3bbefde0c', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 26, 26, 'Seven days shall they make atonement for the altar and purify it; so shall they consecrate it.'),
  ('e5bb229d-86fb-5ea1-ada6-a99a5e6d3958', '0d7d5647-53da-58c9-ad86-df9f2b141c55', NULL, 27, 27, 'When they have accomplished the days, it shall be that on the eighth day, and forward, the priests shall make your burnt offerings on the altar, and your peace offerings; and I will accept you, says the Lord Yahweh.'),
  ('3fc60650-d7d3-5e43-ac91-75c67b44e33e', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 1, 1, 'Then he brought me back by the way of the outer gate of the sanctuary, which looks toward the east; and it was shut.'),
  ('3bed4a14-f433-5447-a9e8-7bfb3f4b2521', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 2, 2, 'Yahweh said to me, This gate shall be shut; it shall not be opened, neither shall any man enter in by it; for Yahweh, the God of Israel, has entered in by it; therefore it shall be shut.'),
  ('e8c42d29-7f04-5407-a38e-324151212bc1', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 3, 3, 'As for the prince, he shall sit therein as prince to eat bread before Yahweh; he shall enter by the way of the porch of the gate, and shall go out by the way of the same.'),
  ('72249a50-3371-5b72-a818-6bf02f50a9ba', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 4, 4, 'Then he brought me by the way of the north gate before the house; and I looked, and behold, the glory of Yahweh filled the house of Yahweh: and I fell on my face.'),
  ('2bd3de86-9add-5adb-a957-3a6ab6fbf291', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 5, 5, 'Yahweh said to me, Son of man, mark well, and see with your eyes, and hear with your ears all that I tell you concerning all the ordinances of the house of Yahweh, and all its laws; and mark well the entrance of the house, with every exit of the sanctuary.'),
  ('66d67a57-9206-5d2b-a81e-4cd017c725ff', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 6, 6, 'You shall tell the rebellious, even to the house of Israel, Thus says the Lord Yahweh: you house of Israel, let it suffice you of all your abominations,'),
  ('5e2eb77b-138c-5a33-ada2-d0f711726453', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 7, 7, 'in that you have brought in foreigners, uncircumcised in heart and uncircumcised in flesh, to be in my sanctuary, to profane it, even my house, when you offer my bread, the fat and the blood, and they have broken my covenant, [to add] to all your abominations.'),
  ('6c629549-4c6d-557b-a6ed-b93ce140bba9', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 8, 8, 'You have not performed the duty of my holy things; but you have set performers of my duty in my sanctuary for yourselves.'),
  ('6f4c45ac-c671-59d6-add6-7ce9653899ba', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 9, 9, 'Thus says the Lord Yahweh, No foreigner, uncircumcised in heart and uncircumcised in flesh, shall enter into my sanctuary, of any foreigners who are among the children of Israel.'),
  ('2c8dcd4f-c99e-51ab-a680-818dab2aef14', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 10, 10, 'But the Levites who went far from me, when Israel went astray, who went astray from me after their idols, they shall bear their iniquity.'),
  ('316e60a9-26a8-57d5-a62c-5ebe05ef565c', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 11, 11, 'Yet they shall be ministers in my sanctuary, having oversight at the gates of the house, and ministering in the house: they shall kill the burnt offering and the sacrifice for the people, and they shall stand before them to minister to them.')
INSERT INTO public.bible_verses (id, chapter_id, section_id, source_order, verse_number, text)
VALUES
  ('2c6f97cb-ee76-5cfe-a777-7895c1f43726', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 12, 12, 'Because they ministered to them before their idols, and became a stumbling block of iniquity to the house of Israel; therefore have I lifted up my hand against them, says the Lord Yahweh, and they shall bear their iniquity.'),
  ('56ee509d-713f-5772-aa29-b67bb21c16ca', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 13, 13, 'They shall not come near to me, to execute the office of priest to me, nor to come near to any of my holy things, to the things that are most holy; but they shall bear their shame, and their abominations which they have committed.'),
  ('063e69d9-2904-5c02-a3f7-4e2fb6e586b3', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 14, 14, 'Yet will I make them performers of the duty of the house, for all its service, and for all that shall be done therein.'),
  ('46f5549f-085a-5452-a01a-0c408ff126e6', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 15, 15, 'But the priests the Levites, the sons of Zadok, who performed the duty of my sanctuary when the children of Israel went astray from me, they shall come near to me to minister to me; and they shall stand before me to offer to me the fat and the blood, says the Lord Yahweh:'),
  ('4cce0f98-5dac-5e6e-a000-20ada6ee508f', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 16, 16, 'they shall enter into my sanctuary, and they shall come near to my table, to minister to me, and they shall keep my instruction.'),
  ('7ced3f89-10fd-51c1-ab84-6a2e8922709e', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 17, 17, 'It shall be that, when they enter in at the gates of the inner court, they shall be clothed with linen garments; and no wool shall come on them, while they minister in the gates of the inner court, and within.'),
  ('5d428942-ea6c-5f24-a2a1-490f8ecc241e', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 18, 18, 'They shall have linen tires on their heads, and shall have linen breeches on their waists; they shall not clothe themselves with [anything that causes] sweat.'),
  ('614162cb-6dc4-53ba-a026-601294d9bb25', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 19, 19, 'When they go forth into the outer court, even into the outer court to the people, they shall put off their garments in which they minister, and lay them in the holy rooms; and they shall put on other garments, that they not sanctify the people with their garments.'),
  ('401220a8-a5cf-55a8-a03e-7199cb7adc2f', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 20, 20, 'Neither shall they shave their heads, nor allow their locks to grow long; they shall only cut off the hair of their heads.'),
  ('3488ed1a-6c04-5bec-a3e4-2136ac472655', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 21, 21, 'Neither shall any of the priests drink wine, when they enter into the inner court.'),
  ('6a03406c-387f-5009-ae05-130836703b0b', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 22, 22, 'Neither shall they take for their wives a widow, nor her who is put away; but they shall take virgins of the seed of the house of Israel, or a widow who is the widow of a priest.'),
  ('619c896e-56c0-5db0-ac18-342b65fd944a', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 23, 23, 'They shall teach my people the difference between the holy and the common, and cause them to discern between the unclean and the clean.'),
  ('0752ab66-703f-5441-a7ed-b7cd5b06a380', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 24, 24, 'In a controversy they shall stand to judge; according to my ordinances shall they judge it: and they shall keep my laws and my statutes in all my appointed feasts; and they shall make my Sabbaths holy.'),
  ('41e78230-843b-5acd-afbd-5b74ecbc2384', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 25, 25, 'They shall go in to no dead person to defile themselves; but for father, or for mother, or for son, or for daughter, for brother, or for sister who has had no husband, they may defile themselves.'),
  ('1bace576-c64d-571f-a3b4-ef1cef5f6292', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 26, 26, 'After he is cleansed, they shall reckon to him seven days.'),
  ('0f3a6eff-cf31-590a-a42a-c45cbcba05d7', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 27, 27, 'In the day that he goes into the sanctuary, into the inner court, to minister in the sanctuary, he shall offer his sin offering, says the Lord Yahweh.'),
  ('630c350f-7219-558d-aa15-a56af2f8418a', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 28, 28, 'They shall have an inheritance: I am their inheritance; and you shall give them no possession in Israel; I am their possession.'),
  ('712e0330-58cc-50b3-a9a3-5217855477db', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 29, 29, 'They shall eat the meal offering, and the sin offering, and the trespass offering; and every devoted thing in Israel shall be theirs.'),
  ('4b84d908-3343-5f24-a72e-e074e83ee71a', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 30, 30, 'The first of all the first fruits of every thing, and every offering of everything, of all your offerings, shall be for the priest: you shall also give to the priests the first of your dough, to cause a blessing to rest on your house.'),
  ('af1ff4ff-3619-5d32-a2e6-c739c59afede', '545862cc-2d61-50e8-a1fd-5c29b2179784', NULL, 31, 31, 'The priests shall not eat of anything that dies of itself, or is torn, whether it be bird or animal.'),
  ('2c69ef03-f082-525e-a87f-26c9712fcae0', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 1, 1, 'Moreover, when you shall divide by lot the land for inheritance, you shall offer an offering to Yahweh, a holy portion of the land; the length shall be the length of twenty-five thousand [reeds], and the breadth shall be ten thousand: it shall be holy in all its border all around.'),
  ('d303f954-e3bc-580b-abe7-91f5cf04a3da', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 2, 2, 'Of this there shall be for the holy place five hundred [in length] by five hundred [in breadth], square all around; and fifty cubits for its suburbs all around.'),
  ('d02bb89c-c62c-5909-abea-e1b783071b13', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 3, 3, 'Of this measure you shall measure a length of twenty-five thousand, and a breadth of ten thousand: and in it shall be the sanctuary, which is most holy.'),
  ('164468d1-9cb2-5a81-a9cf-8f1105b8d66a', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 4, 4, 'It is a holy portion of the land; it shall be for the priests, the ministers of the sanctuary, who come near to minister to Yahweh; and it shall be a place for their houses, and a holy place for the sanctuary.'),
  ('102ef5b5-a0d2-54ee-a5e3-1efd8bf6614a', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 5, 5, 'Twenty-five thousand in length, and ten thousand in breadth, shall be to the Levites, the ministers of the house, for a possession to themselves, [for] twenty rooms.'),
  ('82394349-a5c7-5b22-a979-7efdb45035e9', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 6, 6, 'You shall appoint the possession of the city five thousand broad, and twenty-five thousand long, side by side with the offering of the holy portion: it shall be for the whole house of Israel.'),
  ('1a6b88b2-8eda-52da-a058-7cc259f85832', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 7, 7, '[Whatever is] for the prince [shall be] on the one side and on the other side of the holy offering and of the possession of the city, in front of the holy offering and in front of the possession of the city, on the west side westward, and on the east side eastward; and in length answerable to one of the portions, from the west border to the east border.'),
  ('2e1e9717-746e-50e9-a0bf-3acae81046a5', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 8, 8, 'In the land it shall be to him for a possession in Israel: and my princes shall no more oppress my people; but they shall give the land to the house of Israel according to their tribes.'),
  ('3f1be36f-1129-55b0-afaf-eb6c340797a9', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 9, 9, 'Thus says the Lord Yahweh: Let it suffice you, princes of Israel: remove violence and spoil, and execute justice and righteousness; dispossessing my people, says the Lord Yahweh.'),
  ('40a3bcc5-aff1-52c5-a16f-e31c26a2b00d', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 10, 10, 'You shall have just balances, and a just ephah, and a just bath.'),
  ('94007e9c-3d7f-5f47-ac1c-6c2d875f37db', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 11, 11, 'The ephah and the bath shall be of one measure, that the bath may contain the tenth part of a homer, and the ephah the tenth part of a homer: its measure shall be after the homer.'),
  ('6be0ccc4-2e0e-58ff-a855-4391af2aa385', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 12, 12, 'The shekel shall be twenty gerahs. Twenty shekels plus twenty-five shekels plus fifteen shekels shall be your mina.'),
  ('2c45f2e6-e019-5568-a6ec-63960c0c5fca', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 13, 13, 'This is the offering that you shall offer: the sixth part of an ephah from a homer of wheat; and you shall give the sixth part of an ephah from a homer of barley;'),
  ('894223e0-a9aa-5a53-a7fb-d45ab164fe70', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 14, 14, 'and the set portion of oil, of the bath of oil, the tenth part of a bath out of the cor, [which is] ten baths, even a homer; (for ten baths are a homer;)'),
  ('ff76fa74-da0d-5d74-a447-3231e998e44d', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 15, 15, 'and one lamb of the flock, out of two hundred, from the well-watered pastures of Israel--for a meal offering, and for a burnt offering, and for peace offerings, to make atonement for them, says the Lord Yahweh.'),
  ('9fc4cb35-d282-5330-ace9-218749fd61a3', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 16, 16, 'All the people of the land shall give to this offering for the prince in Israel.'),
  ('f14ac95b-ac4c-5894-a73e-6cae0a910656', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 17, 17, 'It shall be the prince''s part to give the burnt offerings, and the meal offerings, and the drink offerings, in the feasts, and on the new moons, and on the Sabbaths, in all the appointed feasts of the house of Israel: he shall prepare the sin offering, and the meal offering, and the burnt offering, and the peace offerings, to make atonement for the house of Israel.'),
  ('29ecc460-beb4-576d-aadf-09bb322754ca', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 18, 18, 'Thus says the Lord Yahweh: In the first [month], in the first [day] of the month, you shall take a young bull without blemish; and you shall cleanse the sanctuary.'),
  ('21a9c567-e42c-51c6-a89f-cfcd658fe93e', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 19, 19, 'The priest shall take of the blood of the sin offering, and put it on the door posts of the house, and on the four corners of the ledge of the altar, and on the posts of the gate of the inner court.'),
  ('85f2a7db-4da4-52e4-afbc-40c0679d4142', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 20, 20, 'So you shall do on the seventh [day] of the month for everyone who errs, and for him who is simple: so you shall make atonement for the house.'),
  ('24e30249-98c1-5310-a893-45fa530f393c', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 21, 21, 'In the first [month], in the fourteenth day of the month, you shall have the Passover, a feast of seven days; unleavened bread shall be eaten.'),
  ('8921ade3-28d7-5433-a7e8-b00040d3fb62', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 22, 22, 'On that day shall the prince prepare for himself and for all the people of the land a bull for a sin offering.'),
  ('95a9ada5-48e2-5a76-a86e-0aef0410d3f8', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 23, 23, 'The seven days of the feast he shall prepare a burnt offering to Yahweh, seven bulls and seven rams without blemish daily the seven days; and a male goat daily for a sin offering.'),
  ('7175f7af-7c28-588f-a7e6-c2f7f484089f', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 24, 24, 'He shall prepare a meal offering, an ephah for a bull, and an ephah for a ram, and a hin of oil to an ephah.'),
  ('ef8b7b3e-1e64-5425-a473-5408ac55bbcc', '806fe218-e4c2-5477-ab15-0ea72a7d4612', NULL, 25, 25, 'In the seventh [month], in the fifteenth day of the month, in the feast, shall he do the like the seven days; according to the sin offering, according to the burnt offering, and according to the meal offering, and according to the oil.'),
  ('18c6cc6a-6f2e-580c-a82f-003d377e70c5', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 1, 1, 'Thus says the Lord Yahweh: The gate of the inner court that looks toward the east shall be shut the six working days; but on the Sabbath day it shall be opened, and on the day of the new moon it shall be opened.'),
  ('6eb6fed7-adec-52b2-adc0-1215f0ca8acd', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 2, 2, 'The prince shall enter by the way of the porch of the gate outside, and shall stand by the post of the gate; and the priests shall prepare his burnt offering and his peace offerings, and he shall worship at the threshold of the gate: then he shall go forth; but the gate shall not be shut until the evening.'),
  ('33c3cb2f-2b16-5f60-a87a-809823d579fa', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 3, 3, 'The people of the land shall worship at the door of that gate before Yahweh on the Sabbaths and on the new moons.'),
  ('57918707-afbf-5ffd-a424-0f3b55dffa59', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 4, 4, 'The burnt offering that the prince shall offer to Yahweh shall be on the Sabbath day six lambs without blemish and a ram without blemish;'),
  ('c188a1d2-12e4-5376-a36d-9a935aaf8b5f', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 5, 5, 'and the meal offering shall be an ephah for the ram, and the meal offering for the lambs as he is able to give, and a hin of oil to an ephah.'),
  ('9808e5ce-a662-5f72-a5f3-24a5d7402a7a', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 6, 6, 'On the day of the new moon it shall be a young bull without blemish, and six lambs, and a ram; they shall be without blemish:'),
  ('87b976df-3833-57ff-a306-b7502954659a', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 7, 7, 'and he shall prepare a meal offering, an ephah for the bull, and an ephah for the ram, and for the lambs according as he is able, and a hin of oil to an ephah.'),
  ('6eb59072-26e1-5d23-ac83-9ce550b63581', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 8, 8, 'When the prince shall enter, he shall go in by the way of the porch of the gate, and he shall go forth by its way.'),
  ('5ed7f1cf-01a4-56f7-ab73-9ce2c9310a59', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 9, 9, 'But when the people of the land shall come before Yahweh in the appointed feasts, he who enters by the way of the north gate to worship shall go forth by the way of the south gate; and he who enters by the way of the south gate shall go forth by the way of the north gate: he shall not return by the way of the gate by which he came in, but shall go forth straight before him.'),
  ('a6476f67-c76a-5445-ac0c-700e2c5e33d2', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 10, 10, 'The prince, when they go in, shall go in with of them; and when they go out, he shall go out.'),
  ('106a0920-4c5c-58fe-ad74-7c4afcddbd33', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 11, 11, 'In the feasts and in the solemnities the meal offering shall be an ephah for a bull, and an ephah for a ram, and for the lambs as he is able to give, and a hin of oil to an ephah.'),
  ('35c42fcc-8321-55c2-a105-90c5e1322610', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 12, 12, 'When the prince shall prepare a freewill offering, a burnt offering or peace offerings as a freewill offering to Yahweh, one shall open for him the gate that looks toward the east; and he shall prepare his burnt offering and his peace offerings, as he does on the Sabbath day: then he shall go forth; and after his going forth one shall shut the gate.'),
  ('48814cae-f2dc-53ed-aeed-80c0708ca6e0', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 13, 13, 'You shall prepare a lamb a year old without blemish for a burnt offering to Yahweh daily: morning by morning you shall prepare it.'),
  ('dfbbe13a-dc8b-53ea-a60f-7f8154176eb4', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 14, 14, 'You shall prepare a meal offering with it morning by morning, the sixth part of an ephah, and the third part of a hin of oil, to moisten the fine flour; a meal offering to Yahweh continually by a perpetual ordinance.'),
  ('2c69bedf-ea97-5977-a594-4d2bbbe51a54', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 15, 15, 'Thus shall they prepare the lamb, and the meal offering, and the oil, morning by morning, for a continual burnt offering.'),
  ('c06c016a-ea97-578d-aae1-1c3dd60fe1fd', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 16, 16, 'Thus says the Lord Yahweh: If the prince give a gift to any of his sons, it is his inheritance, it shall belong to his sons; it is their possession by inheritance.'),
  ('2d5312db-5a99-5135-ab8c-a486dac61d0b', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 17, 17, 'But if he give of his inheritance a gift to one of his servants, it shall be his to the year of liberty; then it shall return to the prince; but as for his inheritance, it shall be for his sons.'),
  ('e518d19d-a7a5-5607-ae13-8166288e311a', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 18, 18, 'Moreover the prince shall not take of the people''s inheritance, to thrust them out of their possession; he shall give inheritance to his sons out of his own possession, that my people not be scattered every man from his possession.'),
  ('6814ced5-6866-5599-a422-886b76e13b07', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 19, 19, 'Then he brought me through the entry, which was at the side of the gate, into the holy rooms for the priests, which looked toward the north: and behold, there was a place on the hinder part westward.'),
  ('c5670e00-29a3-54bf-a2e9-c5b2aa0b2361', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 20, 20, 'He said to me, This is the place where the priests shall boil the trespass offering and the sin offering, [and] where they shall bake the meal offering; that they not bring them forth into the outer court, to sanctify the people.'),
  ('4d30e32d-1815-5085-a59c-a8147afac01d', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 21, 21, 'Then he brought me forth into the outer court, and caused me to pass by the four corners of the court; and behold, in every corner of the court there was a court.'),
  ('fa08cb4d-c4ff-5a62-a74e-3fc912cc7334', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 22, 22, 'In the four corners of the court there were courts enclosed, forty [cubits] long and thirty broad: these four in the corners were of one measure.'),
  ('021c0bcd-c86f-58eb-a0dc-03148f35e842', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 23, 23, 'There was a wall around in them, around the four, and boiling places were made under the walls all around.'),
  ('5fc17852-b693-5e21-a058-753f0865ae21', '49822ab8-5d00-5c2f-a5d0-760a587a3231', NULL, 24, 24, 'Then he said to me, These are the boiling houses, where the ministers of the house shall boil the sacrifice of the people.'),
  ('96a04c7a-8936-550c-a263-129fa2c1824e', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 1, 1, 'He brought me back to the door of the house; and behold, waters issued out from under the threshold of the house eastward; (for the forefront of the house was toward the east;) and the waters came down from under, from the right side of the house, on the south of the altar.'),
  ('06761012-b9e6-5872-ab2d-9c952bd5b6fe', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 2, 2, 'Then he brought me out by the way of the gate northward, and led me round by the way outside to the outer gate, by the way of [the gate] that looks toward the east; and behold, there ran out waters on the right side.'),
  ('a425c936-1dbb-53fc-a1bb-39fe51a51e99', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 3, 3, 'When the man went forth eastward with the line in his hand, he measured one thousand cubits, and he caused me to pass through the waters, waters that were to the ankles.'),
  ('4ab0a541-954e-5e58-a421-f4d38bf82837', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 4, 4, 'Again he measured one thousand, and caused me to pass through the waters, waters that were to the knees. Again he measured one thousand, and caused me to pass through [the waters], waters that were to the waist.'),
  ('1b0f2823-7dcd-5946-a6fd-9cc402fb8187', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 5, 5, 'Afterward he measured one thousand; [and it was] a river that I could not pass through; for the waters were risen, waters to swim in, a river that could not be passed through.'),
  ('aa897adb-cd0e-5d98-aea4-6b6cfc1d44d6', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 6, 6, 'He said to me, Son of man, have you seen [this]? Then he brought me, and caused me to return to the bank of the river.'),
  ('411af468-4b04-5fc2-a994-8823b2457b18', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 7, 7, 'Now when I had returned, behold, on the bank of the river were very many trees on the one side and on the other.'),
  ('78fe7bbd-63b8-516d-a308-0b5cbc320dde', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 8, 8, 'Then he said to me, These waters issue forth toward the eastern region, and shall go down into the Arabah; and they shall go toward the sea; into the sea [shall the waters go] which were made to issue forth; and the waters shall be healed.'),
  ('550c165e-0a61-503a-a9e7-e181ba123a1c', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 9, 9, 'It shall happen, that every living creature which swarms, in every place where the rivers come, shall live; and there shall be a very great multitude of fish; for these waters are come there, and [the waters of the sea] shall be healed, and everything shall live wherever the river comes.'),
  ('de117c90-af71-5eee-aa42-860096449110', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 10, 10, 'It shall happen, that fishermen shall stand by it: from En Gedi even to En Eglaim shall be a place for the spreading of nets; their fish shall be after their kinds, as the fish of the great sea, exceeding many.'),
  ('742cce61-f752-5b8e-a508-6bde58d74889', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 11, 11, 'But the miry places of it, and its marshes, shall not be healed; they shall be given up to salt.'),
  ('22c7f269-0fd7-5081-ad92-7df1b4e789de', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 12, 12, 'By the river on its bank, on this side and on that side, shall grow every tree for food, whose leaf shall not wither, neither shall its fruit fail: it shall bring forth new fruit every month, because its waters issue out of the sanctuary; and its fruit shall be for food, and its leaf for healing.'),
  ('cc0b948f-285d-54a5-a355-3fed8a3d0ab6', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 13, 13, 'Thus says the Lord Yahweh: This shall be the border, by which you shall divide the land for inheritance according to the twelve tribes of Israel: Joseph [shall have two] portions.'),
  ('52c6517b-3d14-5d25-a1a4-845e6a8a9a3c', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 14, 14, 'You shall inherit it, one as well as another; for I swore to give it to your fathers: and this land shall fall to you for inheritance.'),
  ('8ba49129-0b5a-5d41-a1f8-f3d4e82edeaa', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 15, 15, 'This shall be the border of the land: On the north side, from the great sea, by the way of Hethlon, to the entrance of Zedad;'),
  ('ad068334-f145-5621-a8f1-6dca945b9384', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 16, 16, 'Hamath, Berothah, Sibraim, which is between the border of Damascus and the border of Hamath; Hazer Hatticon, which is by the border of Hauran.'),
  ('f7bdfe58-663d-59d3-a7d3-31660b52c7e7', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 17, 17, 'The border from the sea, shall be Hazar Enon at the border of Damascus; and on the north northward is the border of Hamath. This is the north side.'),
  ('fd93a1b0-b9d9-59ab-a9c8-b65f069a4824', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 18, 18, 'The east side, between Hauran and Damascus and Gilead, and the land of Israel, shall be the Jordan; from the [north] border to the east sea you shall measure. This is the east side.'),
  ('3d11d6dd-6c61-5943-acea-f8f672db4fe4', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 19, 19, 'The south side southward shall be from Tamar as far as the waters of Meriboth Kadesh, to the brook [of Egypt], to the great sea. This is the south side southward.'),
  ('70c54e48-3215-5a82-acb2-9646802a0b2e', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 20, 20, 'The west side shall be the great sea, from the [south] border as far as over against the entrance of Hamath. This is the west side.'),
  ('f4b6faad-cba1-54f5-acbe-0733b22c6d55', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 21, 21, 'So you shall divide this land to you according to the tribes of Israel.'),
  ('21d993f1-0bd4-504e-a54a-e530914272c7', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 22, 22, 'It shall happen, that you shall divide it by lot for an inheritance to you and to the aliens who live among you, who shall father children among you; and they shall be to you as the native-born among the children of Israel; they shall have inheritance with you among the tribes of Israel.'),
  ('2c3a5ea1-d8a8-5421-a266-a56761e355f2', 'e20cfb5d-a465-56ab-a226-ab572984877d', NULL, 23, 23, 'It shall happen, that in what tribe the stranger lives, there you shall give him his inheritance, says the Lord Yahweh.'),
  ('2bd2d589-ac39-5099-a7a5-205090d7d078', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 1, 1, 'Now these are the names of the tribes: From the north end, beside the way of Hethlon to the entrance of Hamath, Hazar Enan at the border of Damascus, northward beside Hamath, (and they shall have their sides east [and] west), Dan, one [portion].'),
  ('54ddffb9-9040-5ee0-a7eb-6cc384614062', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 2, 2, 'By the border of Dan, from the east side to the west side, Asher, one [portion].'),
  ('0e3dd8b3-bbec-5a37-a14a-1364fb1d1cb9', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 3, 3, 'By the border of Asher, from the east side even to the west side, Naphtali, one [portion].'),
  ('b8eda90b-307c-5f75-a93e-853b87bd666d', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 4, 4, 'By the border of Naphtali, from the east side to the west side, Manasseh, one [portion].'),
  ('c40b2f1f-391d-56a5-a9fc-23d748f426bd', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 5, 5, 'By the border of Manasseh, from the east side to the west side, Ephraim, one [portion].'),
  ('34412fba-9f93-550c-a960-2a0f919a9769', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 6, 6, 'By the border of Ephraim, from the east side even to the west side, Reuben, one [portion].'),
  ('655c48e1-a25d-5e29-a747-56842c35953d', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 7, 7, 'By the border of Reuben, from the east side to the west side, Judah, one [portion].'),
  ('7c556d6d-cd02-5ee5-ab83-907f502f1be2', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 8, 8, 'By the border of Judah, from the east side to the west side, shall be the offering which you shall offer, twenty-five thousand [reeds] in breadth, and in length as one of the portions, from the east side to the west side: and the sanctuary shall be in its midst.'),
  ('25da2d63-a7e7-57a0-a93c-b2b79a75eb18', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 9, 9, 'The offering that you shall offer to Yahweh shall be twenty-five thousand [reeds] in length, and ten thousand in breadth.'),
  ('868672e0-a9ef-57cc-a287-73eed9882533', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 10, 10, 'For these, even for the priests, shall be the holy offering: toward the north twenty-five thousand [in length], and toward the west ten thousand in breadth, and toward the east ten thousand in breadth, and toward the south twenty-five thousand in length: and the sanctuary of Yahweh shall be in its midst.'),
  ('b7c20b1c-6fe6-5da2-ac3a-8f051b625aa1', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 11, 11, '[It shall be] for the priests who are sanctified of the sons of Zadok, who have kept my instruction, who didn''t go astray when the children of Israel went astray, as the Levites went astray.'),
  ('909c96e3-6b7c-5b6e-a34d-ad60716c035e', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 12, 12, 'It shall be to them an offering from the offering of the land, a thing most holy, by the border of the Levites.'),
  ('f173d5b7-a743-5b80-aa17-f25d18c3630c', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 13, 13, 'Answerable to the border of the priests, the Levites shall have twenty-five thousand in length, and ten thousand in breadth: all the length shall be twenty-five thousand, and the breadth ten thousand.'),
  ('f732ea77-b2c6-5b90-ad9f-63124d6af99c', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 14, 14, 'They shall sell none of it, nor exchange it, nor shall the first fruits of the land be alienated; for it is holy to Yahweh.'),
  ('c5eb9555-44fb-5de6-a1c5-c252530b4731', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 15, 15, 'The five thousand that are left in the breadth, in front of the twenty-five thousand, shall be for common use, for the city, for dwelling and for suburbs; and the city shall be in its midst.'),
  ('670f3ace-7488-5549-a175-935a63b30541', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 16, 16, 'These shall be its measures: the north side four thousand and five hundred, and the south side four thousand and five hundred, and on the east side four thousand and five hundred, and the west side four thousand and five hundred.'),
  ('53524899-a4d1-583e-af9d-53447eefc72e', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 17, 17, 'The city shall have suburbs: toward the north two hundred fifty, and toward the south two hundred fifty, and toward the east two hundred fifty, and toward the west two hundred fifty.'),
  ('659caaf1-1feb-5258-a45e-60ac4eff938f', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 18, 18, 'The remainder in the length, answerable to the holy offering, shall be ten thousand eastward, and ten thousand westward; and it shall be answerable to the holy offering; and its increase shall be for food to those who labor in the city.'),
  ('7e91447c-7304-5fd7-af3d-192ccf08f2c4', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 19, 19, 'Those who labor in the city, out of all the tribes of Israel, shall cultivate it.'),
  ('530fbaf6-9eab-545a-a071-8de80c531861', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 20, 20, 'All the offering shall be twenty-five thousand by twenty-five thousand: you shall offer the holy offering foursquare, with the possession of the city.'),
  ('d291b0ac-d14f-5262-a352-3598bf074080', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 21, 21, 'The residue shall be for the prince, on the one side and on the other of the holy offering and of the possession of the city; in front of the twenty-five thousand of the offering toward the east border, and westward in front of the twenty-five thousand toward the west border, answerable to the portions, it shall be for the prince: and the holy offering and the sanctuary of the house shall be in its midst.'),
  ('3c664d96-a1dc-5991-a89b-c6a909f9daa9', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 22, 22, 'Moreover from the possession of the Levites, and from the possession of the city, being in the midst of that which is the prince''s, between the border of Judah and the border of Benjamin, it shall be for the prince.'),
  ('c7a4cd72-9b6c-5335-a52b-d4503dfdad0a', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 23, 23, 'As for the rest of the tribes: from the east side to the west side, Benjamin, one [portion].'),
  ('0dbf7db8-aee3-54a4-a957-f29123171c61', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 24, 24, 'By the border of Benjamin, from the east side to the west side, Simeon, one [portion].'),
  ('d4367186-4cab-5c3e-adef-8e71c5f97029', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 25, 25, 'By the border of Simeon, from the east side to the west side, Issachar, one [portion].'),
  ('a7f1bacc-252d-5f0f-a660-42c9a60479c2', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 26, 26, 'By the border of Issachar, from the east side to the west side, Zebulun, one [portion].'),
  ('0f97eeb0-0585-5e87-a76a-22e5ae3b25cc', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 27, 27, 'By the border of Zebulun, from the east side to the west side, Gad, one [portion].'),
  ('43b6d766-a927-58ed-afda-85436bd6271a', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 28, 28, 'By the border of Gad, at the south side southward, the border shall be even from Tamar to the waters of Meribath Kadesh, to the brook [of Egypt], to the great sea.'),
  ('dd93cbd6-a13f-5644-a93f-bba89d2b2171', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 29, 29, 'This is the land which you shall divide by lot to the tribes of Israel for inheritance, and these are their several portions, says the Lord Yahweh.'),
  ('d63b3824-f56c-50b7-af86-6cb689f1ac2e', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 30, 30, 'These are the exits of the city: On the north side four thousand and five hundred [reeds] by measure;'),
  ('62eb51da-e3c9-5cb2-a729-9dcdff93f230', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 31, 31, 'and the gates of the city shall be after the names of the tribes of Israel, three gates northward: the gate of Reuben, one; the gate of Judah, one; the gate of Levi, one.'),
  ('efc7c835-eedc-5daf-a22b-1054790d7265', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 32, 32, 'At the east side four thousand and five hundred [reeds], and three gates: even the gate of Joseph, one; the gate of Benjamin, one; the gate of Dan, one.'),
  ('878a76eb-6bb9-5eb6-a800-a0b0bbf0dfcd', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 33, 33, 'At the south side four thousand and five hundred [reeds] by measure, and three gates: the gate of Simeon, one; the gate of Issachar, one; the gate of Zebulun, one.'),
  ('5dec3106-2bf6-581a-af56-a6d13ae51032', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 34, 34, 'At the west side four thousand and five hundred [reeds], with their three gates: the gate of Gad, one; the gate of Asher, one; the gate of Naphtali, one.'),
  ('75c42455-ae52-53ac-ac93-5ff1c210d920', 'c64ed508-b323-5585-a3c9-093b77343cd9', NULL, 35, 35, 'It shall be eighteen thousand [reeds] around: and the name of the city from that day shall be, Yahweh is there.'),
  ('c58569ec-b1a6-57b8-ae78-abc28de80071', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 1, 1, 'In the third year of the reign of Jehoiakim king of Judah came Nebuchadnezzar king of Babylon to Jerusalem, and besieged it.'),
  ('795ceeaf-4b67-5ee8-a76b-c10f2bb37242', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 2, 2, 'The Lord gave Jehoiakim king of Judah into his hand, with part of the vessels of the house of God; and he carried them into the land of Shinar to the house of his god: and he brought the vessels into the treasure house of his god.'),
  ('3d606606-f35f-5884-a066-a1330dea511b', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 3, 3, 'The king spoke to Ashpenaz the master of his eunuchs, that he should bring in [certain] of the children of Israel, even of the seed royal and of the nobles;'),
  ('b8aff4d5-88d7-5023-a688-855212b95f7b', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 4, 4, 'youths in whom was no blemish, but well-favored, and skillful in all wisdom, and endowed with knowledge, and understanding science, and such as had ability to stand in the king''s palace; and that he should teach them the learning and the language of the Chaldeans.'),
  ('a825656b-26b9-5b18-a5b8-ebf57cd1fbc5', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 5, 5, 'The king appointed for them a daily portion of the king''s dainties, and of the wine which he drank, and that they should be nourished three years; that at its end they should stand before the king.'),
  ('40344132-e429-5776-a58b-651b893bf1ab', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 6, 6, 'Now among these were, of the children of Judah, Daniel, Hananiah, Mishael, and Azariah.'),
  ('aa896521-3408-5993-a52d-dbb37b1ca59a', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 7, 7, 'The prince of the eunuchs gave names to them: to Daniel he gave [the name of] Belteshazzar; and to Hananiah, [of] Shadrach; and to Mishael, [of] Meshach; and to Azariah, [of] Abednego.'),
  ('58d5f8f7-30e3-5696-af7d-c701dba355b0', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 8, 8, 'But Daniel purposed in his heart that he would not defile himself with the king''s dainties, nor with the wine which he drank: therefore he requested of the prince of the eunuchs that he might not defile himself.'),
  ('28688dd3-e6d4-5828-a3ed-abafe0f7c0f7', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 9, 9, 'Now God made Daniel to find kindness and compassion in the sight of the prince of the eunuchs.'),
  ('cff9cce2-af49-5818-a05d-9c93dedce0fe', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 10, 10, 'The prince of the eunuchs said to Daniel, I fear my lord the king, who has appointed your food and your drink: for why should he see your faces worse looking than the youths who are of your own age? so would you endanger my head with the king.'),
  ('5bfca081-5336-5145-ab67-7a363948acf2', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 11, 11, 'Then Daniel said to the steward whom the prince of the eunuchs had appointed over Daniel, Hananiah, Mishael, and Azariah:'),
  ('fdcddae7-a8db-5a4a-a5cb-849beb3e4962', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 12, 12, 'Test your servants, I beg you, ten days; and let them give us vegetables to eat, and water to drink.'),
  ('2351be65-59e3-522d-aa51-3273d178ea6a', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 13, 13, 'Then let our faces be looked on before you, and the face of the youths who eat of the king''s dainties; and as you see, deal with your servants.'),
  ('62c15079-d902-5318-afd6-af636948f098', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 14, 14, 'So he listened to them in this matter, and proved them ten days.'),
  ('65879765-cacc-56ab-a02e-4120cc5d13b5', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 15, 15, 'At the end of ten days their faces appeared fairer, and they were fatter in flesh, than all the youths who ate of the king''s dainties.'),
  ('74b468e5-9f8e-5953-aad1-168733f46679', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 16, 16, 'So the steward took away their dainties, and the wine that they should drink, and gave them pulse.'),
  ('b4927173-34a9-58cd-a8c3-2768ebe679c6', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 17, 17, 'Now as for these four youths, God gave them knowledge and skill in all learning and wisdom: and Daniel had understanding in all visions and dreams.'),
  ('46d1a0a2-af0a-5e34-a93c-3012a436b839', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 18, 18, 'At the end of the days which the king had appointed for bringing them in, the prince of the eunuchs brought them in before Nebuchadnezzar.'),
  ('32482869-ada5-56ca-ae1e-0c4c6238a4eb', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 19, 19, 'The king talked with them; and among them all was found none like Daniel, Hananiah, Mishael, and Azariah: therefore stood they before the king.'),
  ('17d2cbb5-b9ee-5503-ac67-9b343e83900c', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 20, 20, 'In every matter of wisdom and understanding, concerning which the king inquired of them, he found them ten times better than all the magicians and enchanters who were in all his realm.'),
  ('a0419ebb-88e8-51d2-a85e-568410f7d71e', '47a1ea45-3f03-5102-a0eb-2001ad45f26a', NULL, 21, 21, 'Daniel continued even to the first year of king Cyrus.'),
  ('41174189-f899-58ba-a7de-564d3c2c0759', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 1, 1, 'In the second year of the reign of Nebuchadnezzar, Nebuchadnezzar dreamed dreams; and his spirit was troubled, and his sleep went from him.'),
  ('494fd765-4375-5044-a136-09dff30f3d11', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 2, 2, 'Then the king commanded to call the magicians, and the enchanters, and the sorcerers, and the Chaldeans, to tell the king his dreams. So they came in and stood before the king.'),
  ('b145b86f-85ca-5e76-a322-567e35350164', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 3, 3, 'The king said to them, I have dreamed a dream, and my spirit is troubled to know the dream.'),
  ('34e4d24d-c8ff-5e35-a9ad-48b9c4a14c22', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 4, 4, 'Then spoke the Chaldeans to the king in the Syrian language, O king, live forever: tell your servants the dream, and we will show the interpretation.'),
  ('174f11c7-a7c9-5072-a2b0-9654b2796455', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 5, 5, 'The king answered the Chaldeans, The thing is gone from me: if you don''t make known to me the dream and its interpretation, you shall be cut in pieces, and your houses shall be made a dunghill.'),
  ('6bb4d471-146b-5a47-ab1f-9297b11f5f44', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 6, 6, 'But if you show the dream and its interpretation, you shall receive of me gifts and rewards and great honor: therefore show me the dream and its interpretation.'),
  ('dda18f0c-3e52-551f-a0d2-2ef61e3e69ef', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 7, 7, 'They answered the second time and said, Let the king tell his servants the dream, and we will show the interpretation.'),
  ('ec764bb7-e231-53c4-aeaf-588a6947dad7', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 8, 8, 'The king answered, I know of a certainty that you would gain time, because you see the thing is gone from me.'),
  ('b4e98109-c153-536f-a509-1270cab18142', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 9, 9, 'But if you don''t make known to me the dream, there is but one law for you; for you have prepared lying and corrupt words to speak before me, until the time be changed: therefore tell me the dream, and I shall know that you can show me its interpretation.'),
  ('cec5b61e-c203-5a37-ab1d-038295fd9a03', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 10, 10, 'The Chaldeans answered before the king, and said, There is not a man on the earth who can show the king''s matter, because no king, lord, or ruler, has asked such a thing of any magician, or enchanter, or Chaldean.'),
  ('2ad033a6-e0da-5b3b-a757-4af739167fad', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 11, 11, 'It is a rare thing that the king requires, and there is no other who can show it before the king, except the gods, whose dwelling is not with flesh.'),
  ('438fa4ee-2653-59de-a54b-91fe3310163d', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 12, 12, 'For this cause the king was angry and very furious, and commanded to destroy all the wise men of Babylon.'),
  ('cd33b04a-d46d-5d69-ab99-c8a0cc01d90e', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 13, 13, 'So the decree went forth, and the wise men were to be slain; and they sought Daniel and his companions to be slain.'),
  ('50d3c3a7-617e-5a9c-a87e-df4f5a4d9d58', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 14, 14, 'Then Daniel returned answer with counsel and prudence to Arioch the captain of the king''s guard, who was gone forth to kill the wise men of Babylon;'),
  ('3fc5849e-983a-5466-ad1c-598cbdb77d00', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 15, 15, 'he answered Arioch the king''s captain, Why is the decree so urgent from the king? Then Arioch made the thing known to Daniel.'),
  ('81977ff3-262f-5524-a192-efa7dcbb5809', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 16, 16, 'Daniel went in, and desired of the king that he would appoint him a time, and he would show the king the interpretation.'),
  ('0cc935ae-d881-50b0-a27c-da5ed66bb20d', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 17, 17, 'Then Daniel went to his house, and made the thing known to Hananiah, Mishael, and Azariah, his companions:'),
  ('530fcfa2-d3ac-581b-a66d-92fba71567da', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 18, 18, 'that they would desire mercies of the God of heaven concerning this secret; that Daniel and his companions should not perish with the rest of the wise men of Babylon.'),
  ('2b75d44e-330e-5208-a197-2e0021895324', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 19, 19, 'Then was the secret revealed to Daniel in a vision of the night. Then Daniel blessed the God of heaven.'),
  ('904c716d-3a57-504b-a5e9-752a3e019bb0', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 20, 20, 'Daniel answered, Blessed be the name of God forever and ever; for wisdom and might are his.'),
  ('50154ff0-95c4-5264-abd6-008644c62760', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 21, 21, 'He changes the times and the seasons; he removes kings, and sets up kings; he gives wisdom to the wise, and knowledge to those who have understanding;'),
  ('1df51256-fdc0-5dd8-af25-9d8725003b60', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 22, 22, 'he reveals the deep and secret things; he knows what is in the darkness, and the light dwells with him.'),
  ('43fd5202-e5a1-5f04-a391-16cfa99f82c1', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 23, 23, 'I thank you, and praise you, you God of my fathers, who have given me wisdom and might, and have now made known to me what we desired of you; for you have made known to us the king''s matter.'),
  ('4ead90ed-4453-52dd-a0c7-8a4fd63961a6', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 24, 24, 'Therefore Daniel went in to Arioch, whom the king had appointed to destroy the wise men of Babylon; he went and said thus to him: Don''t destroy the wise men of Babylon; bring me in before the king, and I will show to the king the interpretation.'),
  ('59bf7478-7798-54a0-acc0-587014615d92', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 25, 25, 'Then Arioch brought in Daniel before the king in haste, and said thus to him, I have found a man of the children of the captivity of Judah, who will make known to the king the interpretation.'),
  ('1bf3c256-6eb9-55fd-a2d5-80101c3a6912', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 26, 26, 'The king answered Daniel, whose name was Belteshazzar, Are you able to make known to me the dream which I have seen, and its interpretation?'),
  ('20b5df4a-73a0-513e-ad71-e83d48d77e51', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 27, 27, 'Daniel answered before the king, and said, The secret which the king has demanded can neither wise men, enchanters, magicians, nor soothsayers, show to the king;'),
  ('96cda9ef-da8a-52fc-af1b-3a24309f8b14', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 28, 28, 'but there is a God in heaven who reveals secrets, and he has made known to the king Nebuchadnezzar what shall be in the latter days. Your dream, and the visions of your head on your bed, are these:'),
  ('587cdfd8-9855-51c1-ab6f-bf6e116763f8', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 29, 29, 'as for you, O king, your thoughts came [into your mind] on your bed, what should happen hereafter; and he who reveals secrets has made known to you what shall happen.'),
  ('4f3ecc67-b087-5b15-a0d4-a7bc93e235a2', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 30, 30, 'But as for me, this secret is not revealed to me for any wisdom that I have more than any living, but to the intent that the interpretation may be made known to the king, and that you may know the thoughts of your heart.'),
  ('cfd7f420-6722-5f48-a5e8-bdfe5b604594', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 31, 31, 'You, O king, saw, and behold, a great image. This image, which was mighty, and whose brightness was excellent, stood before you; and its aspect was awesome.'),
  ('1df2a233-2346-5ddd-a151-a13ba41a8f09', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 32, 32, 'As for this image, its head was of fine gold, its breast and its arms of silver, its belly and its thighs of brass,'),
  ('a2100608-417d-5cfa-adc7-287697d250b1', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 33, 33, 'its legs of iron, its feet part of iron, and part of clay.'),
  ('0ae3d41e-b3f9-5043-a2d1-8a9c6f1f61c0', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 34, 34, 'You saw until a stone was cut out without hands, which struck the image on its feet that were of iron and clay, and broke them in pieces.'),
  ('1f98a311-2387-52a6-a4f3-b4f839992640', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 35, 35, 'Then was the iron, the clay, the brass, the silver, and the gold, broken in pieces together, and became like the chaff of the summer threshing floors; and the wind carried them away, so that no place was found for them: and the stone that struck the image became a great mountain, and filled the whole earth.'),
  ('88aea31b-a0c4-5d6d-a9d8-52bafc438446', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 36, 36, 'This is the dream; and we will tell its interpretation before the king.'),
  ('dabbd4b1-8ff9-5f87-af39-6d8e09b89a57', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 37, 37, 'You, O king, are king of kings, to whom the God of heaven has given the kingdom, the power, and the strength, and the glory;'),
  ('0a29f06f-b7c7-5192-a6d1-431256e36590', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 38, 38, 'and wherever the children of men dwell, the animals of the field and the birds of the sky has he given into your hand, and has made you to rule over them all: you are the head of gold.'),
  ('ccea6f3b-fd80-5b94-aabe-3b0627419fa4', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 39, 39, 'After you shall arise another kingdom inferior to you; and another third kingdom of brass, which shall bear rule over all the earth.'),
  ('32f391a3-4314-5a1b-a40e-ecc77146e8a5', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 40, 40, 'The fourth kingdom shall be strong as iron, because iron breaks in pieces and subdues all things; and as iron that crushes all these, shall it break in pieces and crush.'),
  ('c8d20f58-a4c0-5080-aeff-85cd4c817af5', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 41, 41, 'Whereas you saw the feet and toes, part of potters'' clay, and part of iron, it shall be a divided kingdom; but there shall be in it of the strength of the iron, because you saw the iron mixed with miry clay.'),
  ('372eb5ca-b21f-5cdf-a5e5-309453474cc8', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 42, 42, 'As the toes of the feet were part of iron, and part of clay, so the kingdom shall be partly strong, and partly broken.'),
  ('29a4a728-7f55-50d1-a6c0-9b1902086bdf', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 43, 43, 'Whereas you saw the iron mixed with miry clay, they shall mingle themselves with the seed of men; but they shall not cling to one another, even as iron does not mingle with clay.'),
  ('87512447-7d79-598d-a086-a01f8c946a8b', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 44, 44, 'In the days of those kings shall the God of heaven set up a kingdom which shall never be destroyed, nor shall its sovereignty be left to another people; but it shall break in pieces and consume all these kingdoms, and it shall stand forever.'),
  ('de2f19e6-7585-56d1-a757-92d33d0d79c4', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 45, 45, 'Because you saw that a stone was cut out of the mountain without hands, and that it broke in pieces the iron, the brass, the clay, the silver, and the gold; the great God has made known to the king what shall happen hereafter: and the dream is certain, and its interpretation sure.'),
  ('dfd17c2c-8e83-541a-a397-21917dee0f07', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 46, 46, 'Then the king Nebuchadnezzar fell on his face, and worshiped Daniel, and commanded that they should offer an offering and sweet odors to him.'),
  ('8050198b-8704-589b-ad1e-f8a8e7e74dad', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 47, 47, 'The king answered to Daniel, and said, Of a truth your God is the God of gods, and the Lord of kings, and a revealer of secrets, since you have been able to reveal this secret.'),
  ('2454bc62-1e90-5017-a776-fdc3e86afb76', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 48, 48, 'Then the king made Daniel great, and gave him many great gifts, and made him to rule over the whole province of Babylon, and to be chief governor over all the wise men of Babylon.'),
  ('65907ffe-ecb2-5528-a3ce-4039043ef97d', 'e144c6d2-66fb-5c89-a592-484fb3852c96', NULL, 49, 49, 'Daniel requested of the king, and he appointed Shadrach, Meshach, and Abednego, over the affairs of the province of Babylon: but Daniel was in the gate of the king.'),
  ('21c69cf2-5a64-51d4-a7f4-0e22e461c6cd', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 1, 1, 'Nebuchadnezzar the king made an image of gold, whose height was sixty cubits, and its breadth six cubits: he set it up in the plain of Dura, in the province of Babylon.'),
  ('51e5064d-6f7b-54e3-a963-02ac671cc7ca', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 2, 2, 'Then Nebuchadnezzar the king sent to gather together the satraps, the deputies, and the governors, the judges, the treasurers, the counselors, the sheriffs, and all the rulers of the provinces, to come to the dedication of the image which Nebuchadnezzar the king had set up.'),
  ('991d4e98-6a0a-56f5-a548-76c7d1a83c9c', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 3, 3, 'Then the satraps, the deputies, and the governors, the judges, the treasurers, the counselors, the sheriffs, and all the rulers of the provinces, were gathered together to the dedication of the image that Nebuchadnezzar the king had set up; and they stood before the image that Nebuchadnezzar had set up.'),
  ('a1ab2a37-561b-5821-adb8-4cb431bc26c4', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 4, 4, 'Then the herald cried aloud, To you it is commanded, peoples, nations, and languages,'),
  ('38caf502-2d8c-515d-ae51-554081b07c3a', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 5, 5, 'that whenever you hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, you fall down and worship the golden image that Nebuchadnezzar the king has set up;'),
  ('fb84dc63-7732-5b70-a60b-f6a835574e2a', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 6, 6, 'and whoever doesn''t fall down and worship shall the same hour be cast into the midst of a burning fiery furnace.'),
  ('95ca28bb-aac5-5f00-a635-4052d1f1903c', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 7, 7, 'Therefore at that time, when all the peoples heard the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, all the peoples, the nations, and the languages, fell down and worshiped the golden image that Nebuchadnezzar the king had set up.'),
  ('6363f33e-7a26-57cd-ad63-b08c559e56fa', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 8, 8, 'Therefore at that time certain Chaldeans came near, and brought accusation against the Jews.'),
  ('a8c72342-49eb-5f87-a72f-a3473ff02e40', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 9, 9, 'They answered Nebuchadnezzar the king, O king, live for ever.'),
  ('b7a3ab92-f4fe-5a91-aa60-20bb79b10a3a', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 10, 10, 'You, O king, have made a decree, that every man that shall hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music, shall fall down and worship the golden image;'),
  ('94372735-ce83-5ea8-a3c6-51aed743e96f', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 11, 11, 'and whoever doesn''t fall down and worship shall be cast into the midst of a burning fiery furnace.'),
  ('52c00c0e-84bb-507f-afdd-796d514a4ca1', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 12, 12, 'There are certain Jews whom you have appointed over the affairs of the province of Babylon: Shadrach, Meshach, and Abednego; these men, O king, have not respected you. They don''t serve your gods, nor worship the golden image which you have set up.'),
  ('bf2370c9-b0d0-5c3c-a309-152ea9b298ae', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 13, 13, 'Then Nebuchadnezzar in [his] rage and fury commanded to bring Shadrach, Meshach, and Abednego. Then they brought these men before the king.'),
  ('7abd2173-7d32-52b5-a79f-7eb2e424c1a2', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 14, 14, 'Nebuchadnezzar answered them, Is it on purpose, Shadrach, Meshach, and Abednego, that you don''t serve my god, nor worship the golden image which I have set up?'),
  ('3ed8468a-b041-5dec-a95b-bf3d40b1d8a5', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 15, 15, 'Now if you are ready whenever you hear the sound of the horn, flute, zither, lyre, harp, pipe, and all kinds of music to fall down and worship the image which I have made, [well]: but if you don''t worship, you shall be cast the same hour into the midst of a burning fiery furnace; and who is that god that shall deliver you out of my hands?'),
  ('fb2b5282-9630-5d77-a831-3380533490a4', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 16, 16, 'Shadrach, Meshach, and Abednego answered the king, Nebuchadnezzar, we have no need to answer you in this matter.'),
  ('c2d0ef04-eb05-57dd-ab2f-b1c6395e4922', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 17, 17, 'If it be [so], our God whom we serve is able to deliver us from the burning fiery furnace; and he will deliver us out of your hand, O king.'),
  ('82f48b70-953c-58f1-a8e9-56e5c36d7076', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 18, 18, 'But if not, be it known to you, O king, that we will not serve your gods, nor worship the golden image which you have set up.'),
  ('6651cd55-69e9-5e00-a7a5-3703ef836560', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 19, 19, 'Then was Nebuchadnezzar full of fury, and the form of his appearance was changed against Shadrach, Meshach, and Abednego: [therefore] he spoke, and commanded that they should heat the furnace seven times more than it was usually heated.'),
  ('bfcfdc72-058e-50bc-a52e-ea62359390dc', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 20, 20, 'He commanded certain mighty men who were in his army to bind Shadrach, Meshach, and Abednego, [and] to cast them into the burning fiery furnace.'),
  ('550ab693-ae4f-5e53-a1f8-66cd0cffdb65', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 21, 21, 'Then these men were bound in their pants, their tunics, and their mantles, and their [other] garments, and were cast into the midst of the burning fiery furnace.'),
  ('c44148ab-c6c1-5d79-aa00-48adb8117eeb', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 22, 22, 'Therefore because the king''s commandment was urgent, and the furnace exceeding hot, the flame of the fire killed those men who took up Shadrach, Meshach, and Abednego.'),
  ('7c93e4ea-a24a-5560-a043-fdb60411dc45', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 23, 23, 'These three men, Shadrach, Meshach, and Abednego, fell down bound into the midst of the burning fiery furnace.'),
  ('60155f28-569d-5957-a475-ac9aef69b8ff', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 24, 24, 'Then Nebuchadnezzar the king was astonished, and rose up in haste: he spoke and said to his counselors, Didn''t we cast three men bound into the midst of the fire? They answered the king, True, O king.'),
  ('cd64e401-018a-51ce-a303-6c546c145fc2', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 25, 25, 'He answered, Look, I see four men loose, walking in the midst of the fire, and they are unharmed; and the aspect of the fourth is like a son of the gods.'),
  ('4cf1025e-0b9a-5212-a32f-a2abf0c4e548', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 26, 26, 'Then Nebuchadnezzar came near to the mouth of the burning fiery furnace: he spoke and said, Shadrach, Meshach, and Abednego, you servants of the Most High God, come forth, and come here. Then Shadrach, Meshach, and Abednego came forth out of the midst of the fire.'),
  ('b5620099-9811-5b3b-a5c7-49018415e917', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 27, 27, 'The satraps, the deputies, and the governors, and the king''s counselors, being gathered together, saw these men, that the fire had no power on their bodies, nor was the hair of their head singed, neither were their pants changed, nor had the smell of fire passed on them.'),
  ('938ea0a8-77d9-5007-a72a-07df793652b0', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 28, 28, 'Nebuchadnezzar spoke and said, Blessed be the God of Shadrach, Meshach, and Abednego, who has sent his angel, and delivered his servants who trusted in him, and have changed the king''s word, and have yielded their bodies, that they might not serve nor worship any god, except their own God.'),
  ('67ebca6e-bac8-5d84-a075-7c1728193ba9', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 29, 29, 'Therefore I make a decree, that every people, nation, and language, which speak anything evil against the God of Shadrach, Meshach, and Abednego, shall be cut in pieces, and their houses shall be made a dunghill; because there is no other god who is able to deliver after this sort.'),
  ('0c6be296-f060-513d-aec5-07234c561eee', '668dd753-92ea-5663-a340-daa45e339c4a', NULL, 30, 30, 'Then the king promoted Shadrach, Meshach, and Abednego in the province of Babylon.'),
  ('8d91503c-ca19-5e4b-a085-9194bdf5fc41', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 1, 1, 'Nebuchadnezzar the king, to all the peoples, nations, and languages, who dwell in all the earth: Peace be multiplied to you.'),
  ('5d3e78a7-a351-54de-ab89-c8833c41808b', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 2, 2, 'It has seemed good to me to show the signs and wonders that the Most High God has worked toward me.'),
  ('e22dbd80-9ea3-53b5-a603-515cd3fa2074', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 3, 3, 'How great are his signs! and how mighty are his wonders! his kingdom is an everlasting kingdom, and his dominion is from generation to generation.'),
  ('d438a939-5d0f-5262-a0f3-43e52e5a28ae', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 4, 4, 'I, Nebuchadnezzar, was at rest in my house, and flourishing in my palace.'),
  ('56def74b-54cb-5141-a6ad-efcb27ee5ed5', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 5, 5, 'I saw a dream which made me afraid; and the thoughts on my bed and the visions of my head troubled me.'),
  ('34ea89eb-12f5-5072-ab86-b2a007c7d3df', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 6, 6, 'Therefore made I a decree to bring in all the wise men of Babylon before me, that they might make known to me the interpretation of the dream.'),
  ('6d72481b-4689-5997-a994-f8afe650f69e', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 7, 7, 'Then came in the magicians, the enchanters, the Chaldeans, and the soothsayers; and I told the dream before them; but they did not make known to me its interpretation.'),
  ('f0c0c15c-80c1-5213-a1b0-d621123676fe', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 8, 8, 'But at the last Daniel came in before me, whose name was Belteshazzar, according to the name of my god, and in whom is the spirit of the holy gods: and I told the dream before him, [saying],'),
  ('ec84bb23-dc31-55eb-a97a-5b4048565dd6', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 9, 9, 'Belteshazzar, master of the magicians, because I know that the spirit of the holy gods is in you, and no secret troubles you, tell me the visions of my dream that I have seen, and its interpretation.'),
  ('927f0229-7331-5944-a891-64990badb521', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 10, 10, 'Thus were the visions of my head on my bed: I saw, and behold, a tree in the midst of the earth; and its height was great.'),
  ('72473c13-ec63-5c0f-a1ff-ffd4a01d5fd3', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 11, 11, 'The tree grew, and was strong, and its height reached to the sky, and its sight to the end of all the earth.'),
  ('fe70e884-ecf1-5e8d-a260-e2f2505a06e9', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 12, 12, 'The leaves of it were beautiful, and its fruit much, and in it was food for all: the animals of the field had shadow under it, and the birds of the sky lived in its branches, and all flesh was fed from it.'),
  ('4034f63b-7e8b-542f-a242-8bb9ab6e1cc4', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 13, 13, 'I saw in the visions of my head on my bed, and behold, a watcher and a holy one came down from the sky.'),
  ('0aca7cf2-9517-52ab-a638-21198269b6a1', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 14, 14, 'He cried aloud, and said thus, Cut down the tree, and cut off its branches, shake off its leaves, and scatter its fruit: let the animals get away from under it, and the fowls from its branches.'),
  ('8b7446fa-ae78-5931-afd3-d6fd93ee29cc', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 15, 15, 'Nevertheless leave the stump of its roots in the earth, even with a band of iron and brass, in the tender grass of the field; and let it be wet with the dew of the sky: and let his portion be with the animals in the grass of the earth:'),
  ('eee702c7-22d1-515a-a9af-e7a8718961a5', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 16, 16, 'let his heart be changed from man''s, and let an animal''s heart be given to him; and let seven times pass over him.'),
  ('ff659957-cf85-58f1-a095-db4d38ccd242', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 17, 17, 'The sentence is by the decree of the watchers, and the demand by the word of the holy ones; to the intent that the living may know that the Most High rules in the kingdom of men, and gives it to whomever he will, and sets up over it the lowest of men.'),
  ('b9a8c573-7ce9-5eab-a5a0-d0e3eccd57a6', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 18, 18, 'This dream I, king Nebuchadnezzar, have seen; and you, Belteshazzar, declare the interpretation, because all the wise men of my kingdom are not able to make known to me the interpretation; but you are able; for the spirit of the holy gods is in you.'),
  ('7e463102-ffbb-5449-a7ab-1796d4cefcaa', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 19, 19, 'Then Daniel, whose name was Belteshazzar, was stricken mute for a while, and his thoughts troubled him. The king answered, Belteshazzar, don''t let the dream, or the interpretation, trouble you. Belteshazzar answered, My lord, the dream be to those who hate you, and its interpretation to your adversaries.'),
  ('8c2c9698-cb2f-50ed-a471-cc983d02da83', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 20, 20, 'The tree that you saw, which grew, and was strong, whose height reached to the sky, and its sight to all the earth;'),
  ('cc0c9f99-53ef-54cd-a6ca-7e8fe2cf8b83', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 21, 21, 'whose leaves were beautiful, and its fruit much, and in it was food for all; under which the animals of the field lived, and on whose branches the birds of the sky had their habitation:'),
  ('a3bf0b65-e21e-548b-acf3-3c62678533f0', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 22, 22, 'it is you, O king, that are grown and become strong; for your greatness is grown, and reaches to the sky, and your dominion to the end of the earth.'),
  ('52a0a40b-a7c6-557d-a1f6-e66fe3693121', 'cfc147cf-970a-5df6-a7d1-467b4ff5cead', NULL, 23, 23, 'Whereas the king saw a watcher and a holy one coming down from the sky, and saying, Cut down the tree, and destroy it; nevertheless leave the stump of its roots in the earth, even with a band of iron and brass, in the tender grass of the field, and let it be wet with the dew of the sky: and let his portion be with the animals of the field, until seven times pass over him;')
